    // القصة 1 — نزول الوحي
    // القصة 1 — نزول الوحي | المصادر: صحيح البخاري، كتاب بدء الوحي، حديث 3؛ سورة العلق 1-5؛ سورة المدثر 1-7.
    SeerahStory(
      id: 1, title: 'حين أضاء الوحي قلب العالم', subtitle: 'بداية الرسالة في غار حراء',
      category: 'الوحي', location: 'مكة المكرمة — غار حراء', readingMinutes: 7, emoji: '📖',
      storyParagraphs: [
        'قبل أن يُكلَّف النبي محمد ﷺ بالرسالة، عُرف بين قومه بالصدق والأمانة وحسن الخلق. وكان يرى ما شاع في المجتمع من عبادة الأصنام والظلم والتفاخر بالأنساب، فلا يطمئن إلى تلك الممارسات، ويحب الخلوة والتفكر بعيداً عن ضجيج مكة.',
        'وكان ﷺ يذهب إلى غار حراء، فيتعبد الليالي ذوات العدد، ثم يرجع إلى أهله فيتزود ويعود. وتذكر السيدة عائشة رضي الله عنها في الحديث الصحيح أن أول ما بُدئ به من الوحي الرؤيا الصالحة، فكان ما يراه في منامه يأتي واضحاً كضياء الصبح. وهذه المرحلة مهّدت قلبه لاستقبال أعظم أمانة: أمانة تبليغ رسالة الله إلى الناس.',
        'وفي إحدى ليالي رمضان، وهو في غار حراء، جاءه جبريل عليه السلام وقال له: «اقرأ». فقال النبي ﷺ: «ما أنا بقارئ». فضمه جبريل ثم أرسله، وكرر الأمر، حتى تلا عليه صدر سورة العلق: {اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ ۝ خَلَقَ الْإِنْسَانَ مِنْ عَلَقٍ ۝ اقْرَأْ وَرَبُّكَ الْأَكْرَمُ}. وكانت هذه الآيات أول ما نزل من القرآن على المشهور عند أهل العلم.',
        'عاد رسول الله ﷺ إلى بيته وقلبه يرجف مما رأى وسمع، وقال لخديجة رضي الله عنها: «زملوني زملوني». لم تقابله بالسخرية ولا بالتشكيك، بل احتوته وطمأنته، وذكّرته بأخلاقه وأعماله: صلة الرحم، ومساعدة المحتاج، وإكرام الضيف، والوقوف مع أصحاب الحق. كانت تعرف سيرته قبل النبوة، فاستدلت بأثر الخير في حياته على أن الله لا يضيعه.',
        'ثم ذهبت به خديجة إلى ابن عمها ورقة بن نوفل، وكان قد عرف شيئاً من الكتب السابقة. فلما سمع ما حدث قال إن هذا هو الناموس الذي نزل على موسى، وتمنى أن يكون حياً حين يلقى النبي ﷺ أذى قومه. وفي حديث عائشة الصحيح أن ورقة توفي بعد ذلك، ثم فتر الوحي مدة قبل أن يتتابع نزوله.',
        'لم تكن بداية الوحي إعلاناً عن مكانة شخصية فحسب، بل كانت بداية تكليف ومسؤولية. وبعد فترة الوحي نزل الأمر: {يَا أَيُّهَا الْمُدَّثِّرُ ۝ قُمْ فَأَنذِرْ}، فبدأ النبي ﷺ دعوة الناس إلى توحيد الله وترك الشرك، بالحكمة والصبر والرحمة.',
        'ومن المهم ألا نجزم بيوم محدد لنزول الوحي؛ فحديث بدء الوحي يثبت أصل القصة وتفاصيلها الأساسية، أما تحديد تاريخ اليوم من رمضان فليس عليه دليل صحيح صريح متفق عليه.',
      ],
      lessons: [
        'الصدق وحسن الخلق أساس الثقة التي يحتاج إليها صاحب الرسالة والإصلاح.',
        'العلم يبدأ بالتواضع وطلب المعرفة؛ فأول ما نزل من القرآن افتتح بالأمر بالقراءة باسم الله.',
        'الدعم الصادق قد يمنح الإنسان قوة لمواجهة مسؤولية عظيمة، كما فعلت خديجة رضي الله عنها.',
        'الأعمال الطيبة المتراكمة تصنع سيرة تشهد لصاحبها وقت الشدة.',
        'الإيمان لا يلغي الشعور بالخوف، لكنه يمنح الإنسان طريقاً صحيحاً للتعامل معه.',
      ],
      practicalApplication: 'اجعل من بداية الوحي برنامجاً عملياً لحياتك:\n\n• خصص وقتاً ثابتاً للقراءة والتعلم، واجعل نيتك أن تنتفع وتنفع غيرك.\n• راجع أخلاقك مع أهلك والضعفاء والضيوف؛ فالقيم تظهر في المواقف اليومية.\n• إذا واجهت أمراً يقلقك، فتحدث مع شخص حكيم تثق بدينه وعقله.\n• لا تنتظر الكمال حتى تبدأ عملاً صالحاً؛ ابدأ بما تستطيع واستعن بالله.\n\n**تأمل:** ما العلم الذي تحتاج إلى تعلمه الآن حتى تكون أنفع لنفسك وأسرتك؟',
      question: SeerahQuestion(
        question: 'ما أول الآيات التي نزلت على النبي ﷺ؟',
        options: ['أول سورة المدثر', 'أول سورة العلق', 'سورة الفاتحة', 'آخر سورة البقرة'],
        correctAnswer: 1,
        explanation: 'ثبت في حديث عائشة رضي الله عنها في صحيح البخاري أن جبريل عليه السلام تلا على النبي ﷺ صدر سورة العلق، وهي أول ما نزل من القرآن على المشهور.',
      ),
      relatedStories: ['إسلام خديجة رضي الله عنها', 'بداية الدعوة في مكة'],
    ),

    // القصة 2 — الهجرة | المصادر: صحيح البخاري 3905 و3653؛ سورة التوبة 40؛ سورة الأنفال 30.
    SeerahStory(
      id: 2, title: 'الهجرة: طريق الإيمان والتخطيط', subtitle: 'من مكة إلى المدينة في سبيل الله',
      category: 'الهجرة', location: 'من مكة المكرمة إلى المدينة المنورة', readingMinutes: 8, emoji: '🕌',
      storyParagraphs: [
        'ظل المسلمون في مكة سنوات يواجهون الأذى بسبب إيمانهم، وهاجر بعضهم قبل ذلك إلى الحبشة. ومع اشتداد أذى قريش، أذن الله لنبيه ﷺ بالهجرة إلى المدينة، حيث وجد المسلمون أنصاراً آووهم ونصروهم، وأصبحت هناك فرصة لبناء مجتمع يعبد الله بحرية.',
        'لم تكن الهجرة انتقالاً عادياً؛ فقد ترك النبي ﷺ بلده الذي نشأ فيه، وترك المسلمون بيوتاً وأموالاً وأهلاً. لكنها كانت تضحية من أجل حفظ الدين وإقامة مجتمع يقوم على الإيمان والتعاون. وتعلمنا أن حب الوطن لا يمنع الإنسان من مغادرته إذا اضطر إلى ذلك لحماية دينه وحياته.',
        'لما تآمرت قريش على قتل النبي ﷺ، أطلعه الله على مكرهم. وأمر علي بن أبي طالب رضي الله عنه أن يبيت في فراشه، وخرج النبي ﷺ من بيته. قال الله تعالى: {وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ}.',
        'اصطحب النبي ﷺ أبا بكر الصديق رضي الله عنه، واتجها أولاً إلى غار ثور في جهة الجنوب، مع أن المدينة تقع شمال مكة؛ وكان ذلك جزءاً من خطة التمويه. ومكثا في الغار ثلاث ليال، واستأجرا عبد الله بن أريقط دليلاً خبيراً بالطريق. كما كان عبد الله بن أبي بكر يأتيهما بأخبار قريش، وكانت أسماء بنت أبي بكر تجهز لهما الطعام.',
        'اقترب المطاردون من الغار حتى خاف أبو بكر رضي الله عنه أن يروهما، فقال للنبي ﷺ: لو أن أحدهم نظر تحت قدميه لأبصرنا. فقال له النبي ﷺ: «ما ظنك يا أبا بكر باثنين الله ثالثهما؟». وخلّد القرآن هذا الموقف في قوله تعالى: {إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ اللَّهُ إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ثَانِيَ اثْنَيْنِ إِذْ هُمَا فِي الْغَارِ...}.',
        'بعد انقضاء الأيام الثلاثة، خرج الركب في طريقه إلى المدينة. لم تكن الرحلة سهلة؛ فقد بذلت قريش جهوداً للعثور عليهما، ومع ذلك واصل النبي ﷺ سيره آخذاً بالأسباب، مع يقينه بحفظ الله. وتروي كتب السيرة تفاصيل أخرى عن الطريق، لكن لا يصح عرض كل تفصيل مشهور فيها على أنه ثابت بدرجة واحدة.',
        'وصل النبي ﷺ إلى قباء، وأقام فيها أياماً وبنى مسجد قباء، ثم دخل المدينة فاستقبله أهلها بفرح. وهناك بدأت مرحلة جديدة: بناء المسجد النبوي، والمؤاخاة بين المهاجرين والأنصار، وتنظيم المجتمع على أساس الإيمان والتكافل.',
        'الهجرة تعلمنا أن التوكل لا يعني ترك التخطيط؛ فقد اختار النبي ﷺ الرفيق، وحدد الطريق، واستأجر دليلاً، ورتب من ينقل الأخبار والطعام، ثم اعتمد على الله. فاجتمع صدق التوكل مع إحكام الأخذ بالأسباب.',
      ],
      lessons: [
        'قد يضطر الإنسان إلى ترك مألوفه من أجل مبدأ أعظم، لكن التضحية تحتاج إلى بصيرة.',
        'التوكل الصحيح يجمع بين الاعتماد على الله وبذل الأسباب المتاحة.',
        'الصاحب الصالح يظهر أثره في الشدائد، وأبو بكر رضي الله عنه صاحب النبي ﷺ في هذه الرحلة.',
        'نجاح الأعمال الكبيرة يحتاج إلى فريق متعاون وأدوار واضحة.',
        'بعد النجاة من الخطر، يبدأ عمل البناء والإصلاح ولا ينتهي بمجرد الوصول.',
      ],
      practicalApplication: 'حوّل دروس الهجرة إلى خطوات:\n\n• إذا أردت تغييراً مهماً، فاكتب هدفك وحدد العقبات وخطة التعامل معها.\n• اختر من يعينك على الخير، ولا تجعل قراراتك المصيرية مبنية على الحماس وحده.\n• وزّع المهام وثق بأصحاب الخبرة؛ فليس مطلوباً أن تقوم بكل شيء بنفسك.\n• اترك العادة أو البيئة التي تضرك إذا استطعت، واستبدل بها ما يعينك على الصلاح.\n• بعد كل بداية جديدة اسأل نفسك: ماذا سأبني؟\n\n**تأمل:** ما الخطوة التي تستطيع اتخاذها هذا الأسبوع لتنتقل إلى وضع أفضل؟',
      question: SeerahQuestion(
        question: 'كم ليلة مكث النبي ﷺ وأبو بكر رضي الله عنه في غار ثور؟',
        options: ['ليلة واحدة', 'ليلتين', 'ثلاث ليال', 'سبع ليال'],
        correctAnswer: 2,
        explanation: 'مكث النبي ﷺ وأبو بكر رضي الله عنه في غار ثور ثلاث ليال، ثم تابعا رحلتهما إلى المدينة وفق الخطة التي أعداها.',
      ),
      relatedStories: ['بناء مسجد قباء', 'المؤاخاة بين المهاجرين والأنصار'],
    ),

    // القصة 3 — بدر | المصادر: سورة الأنفال 5-19 و42-44؛ صحيح البخاري 3953؛ صحيح مسلم 1763.
    SeerahStory(
      id: 3, title: 'بدر: يوم الثبات والتوكل', subtitle: 'أول مواجهة كبرى بين المسلمين وقريش',
