      storyParagraphs: [
        'في السنة الثانية للهجرة، خرج النبي ﷺ مع أصحابه لاعتراض قافلة لقريش عائدة من الشام، في سياق الصراع بعد أن صادرت قريش أموال المهاجرين وآذتهم وأخرجتهم من ديارهم. لكن أبا سفيان غيّر طريق القافلة ونجا بها، ثم أرسلت قريش جيشاً من مكة.',
        'وجد المسلمون أنفسهم أمام موقف لم يخرجوا له ابتداءً؛ فالقافلة أفلتت وجيش قريش يتقدم. تشاور النبي ﷺ مع أصحابه، وسمع منهم كلمات تؤكد استعدادهم للثبات معه. ومن المواقف الثابتة في صحيح البخاري أن المقداد بن عمرو رضي الله عنه أعلن تأييده للنبي ﷺ، وقال إن المسلمين سيقاتلون معه ولن يخذلوه.',
        'كان جيش المسلمين أقل عدداً وعدة من جيش قريش، والمشهور أنه كان نحو ثلاثمائة وبضعة عشر رجلاً، مع اختلاف الروايات في ضبط العدد. أما قريش فجاءت في عدد أكبر. ومع ذلك نظم النبي ﷺ الصفوف، واختار موقع النزول، واستشار أصحابه، وأخذ بالأسباب الممكنة.',
        'وفي ليلة المعركة دعا النبي ﷺ ربه بإلحاح. وفي صحيح البخاري أن أبا بكر رضي الله عنه أخذ بيده وقال له ما معناه إن الله سينجز له وعده. ثم خرج النبي ﷺ يتلو قوله تعالى: {سَيُهْزَمُ الْجَمْعُ وَيُوَلُّونَ الدُّبُرَ}.',
        'وقعت المعركة في السابع عشر من رمضان من السنة الثانية للهجرة على المشهور. وثبت في القرآن أن الله أمد المؤمنين بالملائكة تثبيتاً وبشارة، وأن النصر من عنده سبحانه: {وَلَقَدْ نَصَرَكُمُ اللَّهُ بِبَدْرٍ وَأَنتُمْ أَذِلَّةٌ فَاتَّقُوا اللَّهَ لَعَلَّكُمْ تَشْكُرُونَ}. وانتهت المعركة بانتصار المسلمين، وقُتل من قريش عدد من قادتها وأُسر آخرون.',
        'لم تكن بدر مجرد مواجهة عسكرية؛ فقد كشفت أثر الثبات والطاعة والشورى، وأظهرت أن النصر لا يرتبط دائماً بكثرة العدد. وفي الوقت نفسه لم يكن المسلمون متواكلين؛ فقد خططوا وتحركوا ونظموا صفوفهم، ثم دعوا الله وتوكلوا عليه.',
        'وبعد المعركة واجه المسلمون مسؤولية التعامل مع الأسرى والغنائم، فنزلت آيات سورة الأنفال لتبين أحكام الغنائم وتوجه المؤمنين إلى تقوى الله وإصلاح ذات البين وطاعة الله ورسوله. لذلك لا ينبغي اختزال بدر في مشهد القتال وحده؛ فهي أيضاً درس في الانضباط وإدارة ما بعد النصر.',
      ],
      lessons: [
        'الشجاعة أن تثبت على الحق بعد فهم الموقف، لا أن تندفع دون تقدير للعواقب.',
        'الشورى تمنح القائد رؤية أوسع وتشعر أفراد الجماعة بمسؤوليتهم.',
        'الدعاء لا يتعارض مع التخطيط؛ بل يجتمعان في التوكل الصحيح.',
        'لا تجعل قلة الإمكانات سبباً لترك العمل، ولا تجعل النجاح سبباً للغرور.',
        'ما بعد الانتصار اختبار أخلاقي أيضاً؛ فالعدل وضبط النفس لا يقلان أهمية عن تحقيق الهدف.',
      ],
      practicalApplication: 'استفد من بدر عند مواجهة تحدٍّ صعب:\n\n• اكتب ما تملكه من إمكانات بدلاً من الانشغال بما ينقصك فقط.\n• استشر أصحاب الخبرة، واستمع إلى الرأي المخالف قبل القرار.\n• قسّم المهمة الكبيرة إلى أدوار واضحة.\n• ادعُ الله بصدق، ثم نفّذ ما تستطيع من أسباب النجاح.\n• إذا حققت نجاحاً، فاشكر الله ولا تظلم من خالفك.\n\n**تأمل:** هل تستسلم لأن المهمة تبدو أكبر من إمكاناتك قبل أن تستنفد الأسباب؟',
      question: SeerahQuestion(
