        correctAnswer: 1,
        explanation: 'وقعت غزوة بدر الكبرى في رمضان من السنة الثانية للهجرة، وكان لها أثر كبير في تاريخ الدولة الإسلامية الناشئة.',
      ),
      relatedStories: ['غزوة أحد', 'غزوة الخندق'],
    ),

    // القصة 4 — الإسراء والمعراج | المصادر: سورة الإسراء 1؛ صحيح مسلم 162؛ سورة النجم 13-18.
    SeerahStory(
