      storyParagraphs: [
        'مرّ النبي ﷺ في مكة بمراحل شديدة من الأذى والتكذيب، وفقد في تلك الفترة زوجته خديجة رضي الله عنها وعمه أبا طالب. وتذكر كتب السيرة ذهابه إلى الطائف ولقاءه أذى أهلها، لكن ينبغي التفريق بين أصل الوقائع وما يروى في بعض تفاصيلها من أخبار متفاوتة الثبوت.',
        'وفي هذه المرحلة أكرم الله نبيه ﷺ برحلة الإسراء والمعراج، وهي من أعظم آيات الله. قال تعالى: {سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى الَّذِي بَارَكْنَا حَوْلَهُ}. فالإسراء انتقاله ليلاً من المسجد الحرام إلى المسجد الأقصى، والمعراج عروجه ﷺ إلى السماوات العلى.',
        'وفي الحديث الصحيح الذي رواه مسلم، أخبر النبي ﷺ أنه أُتي بالبراق، فركبه حتى أتى بيت المقدس، وربطه بالحلقة التي يربط بها الأنبياء، ثم دخل المسجد فصلى ركعتين. وبعد ذلك عُرج به إلى السماء.',
        'استفتح جبريل عليه السلام أبواب السماوات، فالتقى النبي ﷺ بعدد من الأنبياء: آدم في الأولى، وعيسى ويحيى في الثانية، ويوسف في الثالثة، وإدريس في الرابعة، وهارون في الخامسة، وموسى في السادسة، وإبراهيم في السابعة، عليهم الصلاة والسلام. وفي هذه اللقاءات ترحيب ودعاء، وإظهار لوحدة أصل الرسالات التي دعت إلى عبادة الله.',
        'ثم أُري النبي ﷺ سدرة المنتهى والبيت المعمور، وفرض الله عليه الصلوات. وجاء في الحديث أن الصلاة فُرضت أولاً خمسين صلاة في اليوم والليلة، ثم خففها الله إلى خمس صلوات مع بقاء الأجر خمسين. وكان موسى عليه السلام يشير عليه أن يسأل التخفيف، حتى انتهى الأمر إلى خمس صلوات.',
        'وهكذا صارت الصلاة صلة يومية بين العبد وربه، تتكرر في أوقات اليوم لتجدد الإيمان وتضبط السلوك. وهي عبادة عظيمة فُرضت في هذه الرحلة المباركة، فلا ينبغي أن نتعامل معها على أنها عادة نؤديها بلا حضور قلب.',
        'أما تحديد الليلة التي وقعت فيها رحلة الإسراء والمعراج، أو الجزم بأنها كانت في يوم معين من شهر رجب، فليس عليه دليل صحيح صريح يعتمد عليه. الثابت هو أصل الرحلة وما جاء في القرآن والأحاديث الصحيحة من خبرها.',
      ],
      lessons: [
        'قد يمر المؤمن بأوقات شديدة، لكن الشدة لا تعني أن رحمة الله بعيدة عنه.',
        'الإيمان بالغيب يقوم على تصديق خبر الله ورسوله ﷺ، مع تجنب إضافة تفاصيل لا تثبت.',
        'الأنبياء جميعاً دعوا إلى توحيد الله، ورسالاتهم يجمعها أصل واحد.',
        'الصلاة أعظم صلة متكررة بين العبد وربه.',
        'التخفيف عن الأمة مظهر من رحمة الله؛ فالصلاة خمس بأجر خمسين.',
      ],
      practicalApplication: 'اجعل الصلاة محور يومك:\n\n• اضبط يومك حول أوقات الصلاة، لا أن تجعل الصلاة آخر ما تفكر فيه.\n• تعلّم معاني ما تقرأه في الفاتحة والأذكار ليزداد حضور قلبك.\n• إذا قصّرت، فابدأ بالعودة فوراً ولا تسمح لليأس أن يبعدك.\n• علّم أهل بيتك فضل الصلاة بالقدوة والرفق.\n• خصص بعد إحدى الصلوات دقائق للاستغفار والدعاء.\n\n**تأمل:** كيف سيتغير اهتمامك بالصلاة إذا نظرت إليها باعتبارها هدية عظيمة؟',
      question: SeerahQuestion(
        question: 'كم صلاة فُرضت على الأمة في النهاية كل يوم وليلة؟',
        options: ['ثلاث صلوات', 'خمس صلوات', 'عشر صلوات', 'خمسون صلاة'],
        correctAnswer: 1,
        explanation: 'فُرضت الصلاة أولاً خمسين، ثم خففها الله إلى خمس صلوات في العمل، وجعل أجرها أجر خمسين، كما ورد في حديث الإسراء في صحيح مسلم.',
      ),
      relatedStories: ['مكانة الصلاة في الإسلام', 'رحمة النبي ﷺ'],
    ),

    // القصة 5 — صلح الحديبية | المصادر: سورة الفتح 1 و18 و24؛ صحيح البخاري 2731-2732 و4844.
    SeerahStory(
      id: 5, title: 'صلح الحديبية: حكمة صنعت فتحاً', subtitle: 'حين اختار النبي ﷺ السلام مع حفظ الحقوق',
      category: 'السيرة والسياسة الشرعية', location: 'الحديبية — غرب مكة المكرمة', readingMinutes: 8, emoji: '🤝',
      storyParagraphs: [
        'في السنة السادسة للهجرة رأى النبي ﷺ في المنام أنه يدخل المسجد الحرام ويطوف بالبيت، ورؤيا الأنبياء حق. فخرج مع أصحابه قاصدين العمرة، لا يريدون قتالاً، وساقوا الهدي وأحرموا، ليعلم الناس أنهم جاءوا زائرين للبيت الحرام.',
        'لكن قريشاً منعتهم من دخول مكة، ونزل المسلمون بالحديبية. وأرسل النبي ﷺ عثمان بن عفان رضي الله عنه إلى قريش ليبلغهم مقصد المسلمين. وتأخر عثمان، فانتشر بين المسلمين خبر مقتله، فدعاهم النبي ﷺ إلى البيعة تحت الشجرة على الثبات وعدم الفرار، وكانت بيعة الرضوان التي أثنى الله على أهلها في سورة الفتح.',
        'ثم جاءت المفاوضات، وأرسلت قريش سهيل بن عمرو. وانتهى الأمر إلى عقد صلح بين الطرفين، ومن بنوده أن يرجع المسلمون ذلك العام فلا يدخلوا مكة، وأن يعودوا في العام التالي لأداء العمرة، وأن تكون هدنة بين الطرفين مدة معلومة، وأن تُنظم أحوال من ينتقل بين الطرفين وفق شروط الاتفاق.',
        'اشتد وقع بعض الشروط على الصحابة، خصوصاً حين جاء أبو جندل بن سهيل رضي الله عنه مقيداً وقد فرّ من أذى المشركين، فطلب ألا يُعاد إلى مكة. لكن سهيل بن عمرو تمسك بشرط الصلح، فأخبر النبي ﷺ أبا جندل أن يصبر ويحتسب، ووعده بأن الله سيجعل له فرجاً. وكان هذا الموقف مؤلماً للمسلمين، لكنه كشف التزام النبي ﷺ بالعهد الذي قبله.',
        'وكان عمر بن الخطاب رضي الله عنه ممن راجع النبي ﷺ مستفهماً عن سبب قبول الشروط، فأكد له النبي ﷺ أنه رسول الله ولن يضيعه الله. وتذكر رواية البخاري أن عمر راجع أبا بكر أيضاً، فثبته أبو بكر بأن النبي ﷺ رسول الله وأن الله لن يضيعه.',
        'بعد الصلح نزلت سورة الفتح، وافتتحها الله بقوله: {إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا}. ومع أن بعض الصحابة رأوا في الشروط تنازلاً صعباً، أظهرت الأيام أن الهدنة أتاحت فرصة للدعوة وانتشار الإسلام، ثم وقع فتح مكة في السنة الثامنة للهجرة.',
        'صلح الحديبية كان فتحاً مبيناً بنص القرآن. ومن الدقة ألا ننسب كل عبارة متداولة في وصفه إلى النبي ﷺ دون تثبت، بل نعتمد على ما ثبت في القرآن وصحيح السنة.',
      ],
      lessons: [
        'الحكمة لا تعني التنازل عن المبادئ، بل اختيار الوسيلة التي تحقق المصلحة المشروعة.',
        'الوفاء بالعهد قيمة عظيمة حتى عندما يكون تنفيذ بعض بنوده شاقاً.',
        'القائد الحكيم ينظر إلى العواقب البعيدة ولا يحكم على القرار من لحظته الأولى.',
        'الصبر على موقف مؤلم قد يفتح أبواباً لم تكن ظاهرة وقت وقوعه.',
        'السلام المنضبط قد يهيئ للدعوة والإصلاح أكثر من المواجهة المستمرة.',
      ],
      practicalApplication: 'طبّق حكمة الحديبية في خلافاتك:\n\n• قبل رفض اتفاق لا يحقق كل ما تريد، اسأل: هل يحقق مصلحة أكبر ويحفظ الحقوق الأساسية؟\n• لا تعد بما لا تستطيع الوفاء به، وإذا عاهدت فالتزم ما دمت لم تُلزم بمعصية.\n• عند الغضب، أجّل القرار حتى تفهم النتائج القريبة والبعيدة.\n• ميّز بين الثوابت التي لا يصح التفريط فيها والوسائل التي يمكن تغييرها.\n• إذا مررت بتجربة تبدو خسارة، راجع نتائجها بعد وقت قبل الحكم عليها.\n\n**تأمل:** هل هناك خلاف يمكن أن يُحل بالحوار والاتفاق العادل بدلاً من استمرار الخصومة؟',
      question: SeerahQuestion(
        question: 'ما السورة التي افتتحت بذكر الفتح المبين بعد صلح الحديبية؟',
        options: ['سورة النصر', 'سورة الفتح', 'سورة التوبة', 'سورة الأنفال'],
        correctAnswer: 1,
        explanation: 'نزلت سورة الفتح بعد صلح الحديبية، وبدأت بقوله تعالى: {إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا}.',
      ),
      relatedStories: ['بيعة الرضوان', 'فتح مكة'],
    ),

    // القصة 6 — حنين الجذع | المصادر: صحيح البخاري 3583-3584.
    SeerahStory(
      id: 6, title: 'حنين الجذع: آية شهدها الصحابة', subtitle: 'جذع النخلة الذي حنّ إلى رسول الله ﷺ',
      category: 'دلائل النبوة', location: 'المسجد النبوي — المدينة المنورة', readingMinutes: 6, emoji: '🌴',
      storyParagraphs: [
        'كان مسجد النبي ﷺ في المدينة بسيط البناء، وكان سقفه من جريد النخل وأعمدته من جذوعه. وكان النبي ﷺ يخطب الناس مستنداً إلى جذع نخلة، فيسمعونه ويتعلمون منه أمور دينهم.',
        'ومع كثرة الناس واتساع المسجد، صنع له الصحابة منبراً يقف عليه ليكون أظهر للمصلين. فلما جاء يوم الجمعة وصعد النبي ﷺ المنبر وابتعد عن الجذع الذي اعتاد أن يخطب عنده، وقع أمر عجيب سمعه الصحابة.',
        'حنّ الجذع وصاح صوتاً كصوت الصبي، حتى انتبه الناس إلى ما يحدث. فنزل النبي ﷺ من المنبر، وأقبل على الجذع واحتضنه أو مسحه، فسكن صوته. وقد ورد أصل هذه المعجزة في أحاديث صحيحة في البخاري، من رواية ابن عمر وجابر رضي الله عنهما.',
        'وفي رواية جابر رضي الله عنه أن الجذع كان يحنّ لما فقد من سماع الذكر عنده، وأن النبي ﷺ ضمه حتى سكن. وهذه الرواية تبين أن الأمر لم يكن مجرد صوت عابر، بل آية أظهرها الله لنبيه ﷺ أمام أصحابه.',
        'تأمل الصحابة هذا المشهد، فكان تذكيراً لهم بعظمة الله وقدرته، وأنه سبحانه يجعل في مخلوقاته من الآيات ما يشاء. ولا ينبغي أن نضيف إلى القصة أقوالاً أو تفاصيل لا تثبت، أو نجعلها دليلاً على معانٍ لم يرد بها النص.',
        'وبقيت قصة حنين الجذع من دلائل نبوة محمد ﷺ التي نقلها الصحابة، وفيها صورة من رحمته؛ فقد ترك المنبر ونزل إلى الجذع حتى سكن، ولم يتجاهل ما سمعه الناس.',
      ],
      lessons: [
        'قد يُظهر الله آياته لعباده بطرق لا يتوقعونها، ليزداد المؤمن يقيناً بقدرته.',
        'محبة النبي ﷺ وتعظيمه تكون باتباع سنته ومعرفة سيرته والصلاة والسلام عليه.',
        'القائد الرحيم لا يتجاهل ما يلفت انتباه من حوله، بل يتعامل معه برفق.',
        'الذكر والعلم لهما أثر عظيم؛ فقد ارتبط حنين الجذع بما كان يسمعه من ذكر عنده.',
        'ينبغي أن ننقل المعجزات كما ثبتت، دون زيادة قصصية تضعف صدق الرواية.',
      ],
      practicalApplication: 'اجعل محبة النبي ﷺ عملاً يظهر في سلوكك:\n\n• تعلّم سنة صحيحة واحدة واعمل بها باستمرار.\n• أكثر من الصلاة والسلام عليه مع فهم معناها.\n• خصص وقتاً أسبوعياً لقراءة حديث صحيح وشرح معناه.\n• إذا نقلت قصة دينية، فتحقق من مصدرها قبل نشرها.\n• عامل الناس بالرفق، واجعل أخلاق النبي ﷺ قدوة لك.\n\n**تأمل:** ما السنة النبوية التي تستطيع أن تحييها في حياتك اليومية؟',
      question: SeerahQuestion(
        question: 'ماذا حدث للجذع عندما صعد النبي ﷺ المنبر؟',
        options: ['سقط على الأرض', 'حنّ وصاح حتى نزل إليه النبي ﷺ', 'اشتعل بالنار', 'انكسر إلى قطع'],
        correctAnswer: 1,
        explanation: 'ثبت في صحيح البخاري أن الجذع حنّ لما انتقل النبي ﷺ إلى المنبر، فنزل إليه ومسح عليه أو ضمه حتى سكن.',
      ),
      relatedStories: ['بناء المسجد النبوي', 'دلائل نبوة النبي ﷺ'],
    ),

    // القصة 7 — إسلام عمر | المصادر: صحيح البخاري 3865 و3867؛ وتفاصيل الصحيفة في كتب السيرة بأسانيد متفاوتة.
    SeerahStory(
      id: 7, title: 'إسلام عمر: قوة وجّهها الإيمان', subtitle: 'من معاداة الدعوة إلى نصرة الإسلام',
      category: 'الصحابة', location: 'مكة المكرمة', readingMinutes: 7, emoji: '🛡️',
      storyParagraphs: [
        'كان عمر بن الخطاب رضي الله عنه من رجال قريش المعروفين بالقوة والشدة، وقد عادى الإسلام في بدايات الدعوة. وتذكر كتب السيرة روايات مشهورة عن الطريق الذي قاده إلى الإسلام، ومنها قصة ذهابه إلى بيت أخته وسماعه آيات من القرآن، لكن تفاصيل هذه الروايات ليست كلها في درجة واحدة من الثبوت.',
        'والثابت في صحيح البخاري أن عمر رضي الله عنه كان قبل إسلامه قد أوثق أخته وزوجها بسبب إسلامهما، كما روى سعيد بن زيد رضي الله عنه. وهذا يبين شدة موقفه في تلك المرحلة، ويجعل تحوله بعد ذلك إلى الإسلام مثالاً على أن القلوب تتغير بهداية الله.',
        'وتذكر الروايات المشهورة في كتب السيرة أن عمر تأثر بالقرآن حين سمع شيئاً من سورة طه، ثم طلب أن يُدل على النبي ﷺ. ومن الأمانة العلمية أن نذكر أن أصل إسلام عمر ثابت، أما ترتيب المشاهد والحوار الحرفي في القصة المشهورة ففي أسانيده كلام، فلا نجزم بكل تفصيل كأنه حديث صحيح.',
        'أسلم عمر رضي الله عنه في مكة، وكان لإسلامه أثر ظاهر في قوة المسلمين وجرأتهم على إظهار عبادتهم. وقد روى عبد الله بن عمر في صحيح البخاري أن الناس اجتمعوا حول بيت عمر حين علموا بإسلامه، وأن العاص بن وائل أعلن حمايته له، فانصرف الناس عنه.',
        'لم يكن إسلام عمر مجرد انتقال شخص من موقف إلى موقف؛ فقد سخّر بعد إسلامه قوته وشجاعته في نصرة الحق، وصار من كبار أصحاب النبي ﷺ، ثم تولى الخلافة بعد أبي بكر رضي الله عنه، واشتهر بالعدل والحزم والحرص على مصالح المسلمين.',
        'وتعلمنا سيرته ألا نحكم على مستقبل إنسان من موقفه الحالي؛ فقد يهديه الله فيتغير مساره كله. كما نتعلم أن القوة ليست فضيلة وحدها، وإنما قيمتها في الهدف الذي تُستخدم من أجله: فقد تكون أداة ظلم إذا انفصلت عن الحق، وتصبح وسيلة لنصرة المظلوم إذا انضبطت بالإيمان والعدل.',
      ],
      lessons: [
        'الهداية بيد الله، فلا يجوز اليأس من صلاح إنسان مهما كان موقفه اليوم.',
        'القوة الحقيقية ليست في الغلبة على الناس، بل في ضبط النفس وتسخير القدرة للعدل.',
        'القرآن يفتح أبواب الهداية، لكن لا ينبغي نسبة تفاصيل غير ثابتة إلى أحداث سماعه.',
        'التحول الإيجابي يحتاج إلى ترجمة الإيمان إلى مواقف وأعمال.',
        'لا تختزل الإنسان في خطئه السابق؛ فقد يتوب ويصبح من أهل الخير.',
      ],
      practicalApplication: 'استفد من سيرة عمر في حياتك:\n\n• لا تحكم على شخص بأنه لن يتغير؛ ادعُ له بالهداية وخاطبه بالحكمة.\n• اسأل نفسك: أين أستخدم قوتي أو نفوذي؟ في نصرة الحق أم فرض الرأي؟\n• إذا اكتشفت خطأ في موقف سابق، فامتلك الشجاعة لتغييره والاعتذار عنه.\n• اقرأ القرآن بتدبر، وحاول أن تحول آية إلى عمل واضح.\n• اجعل الحزم مصحوباً بالعدل والرحمة حتى لا يتحول إلى قسوة.\n\n**تأمل:** ما الصفة القوية في شخصيتك التي تحتاج إلى توجيه أفضل؟',
      question: SeerahQuestion(
        question: 'بماذا اشتهر عمر بن الخطاب رضي الله عنه في سيرته؟',
        options: ['العدل والحزم', 'التجارة البحرية', 'الشعر فقط', 'الانعزال عن الناس'],
        correctAnswer: 0,
        explanation: 'اشتهر عمر رضي الله عنه بالعدل والحزم وتحمل المسؤولية، وكان من كبار أصحاب النبي ﷺ ثم تولى خلافة المسلمين.',
      ),
      relatedStories: ['إسلام حمزة بن عبد المطلب', 'خلافة عمر بن الخطاب'],
    ),

    // القصة 8 — فتح مكة | المصادر: صحيح البخاري 4287-4288؛ سورة الفتح 24.
    SeerahStory(
      id: 8, title: 'فتح مكة: عودة الحق والتواضع عند النصر', subtitle: 'اليوم الذي دخل فيه النبي ﷺ مكة فاتحاً',
      category: 'الفتوحات', location: 'مكة المكرمة', readingMinutes: 8, emoji: '🕋',
      storyParagraphs: [
        'بعد صلح الحديبية، دخلت خزاعة في حلف النبي ﷺ، ودخلت بنو بكر في حلف قريش. ثم وقع اعتداء من بني بكر على خزاعة بمساندة من قريش، فكان ذلك نقضاً للعهد. وجاء وفد من خزاعة إلى النبي ﷺ يستنصره، فكان لهذا الحدث أثر مباشر في التمهيد لفتح مكة.',
        'في السنة الثامنة للهجرة، خرج النبي ﷺ من المدينة في جيش كبير من المسلمين. وكان هدفه إنهاء الاعتداء واستعادة حرمة العهد، لا سفك الدماء. وحرص على كتمان وجهته حتى لا تتحول مكة إلى ساحة قتال واسع.',
        'لما اقترب الجيش من مكة، اتخذ النبي ﷺ إجراءات تقلل المواجهة، وأعلن الأمان لمن دخل داره أو المسجد الحرام أو دار أبي سفيان، وفق ما ورد في أخبار الفتح. وكان دخول المسلمين إلى مكة حدثاً عظيماً بعد سنوات من الإخراج والأذى والحروب.',
        'دخل النبي ﷺ مكة متواضعاً لله، لا متكبراً بقوة الجيش ولا منتشياً بالنصر. وتذكر كتب السيرة أنه جعل لقادة الجيش جهات للدخول، وأوصاهم ألا يقاتلوا إلا من قاتلهم. ووقعت مناوشات محدودة في بعض الجهات، لكن الفتح تم في معظمه دون معركة عامة.',
        'وكان من أبرز أعماله عند البيت تطهيره من الأصنام. فقد روى البخاري عن عبد الله بن مسعود رضي الله عنه أن حول الكعبة كانت ثلاثمائة وستون نصباً، فجعل النبي ﷺ يطعنها بعود في يده ويقول: {جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقًا}. كما أمر بإزالة ما في الكعبة من مظاهر الشرك.',
        'كان فتح مكة تحولاً كبيراً في تاريخ الدعوة؛ فقد عاد المسلمون إلى البلد الذي أُخرجوا منه، وزالت مظاهر الشرك عن البيت الحرام. وتعامل النبي ﷺ مع أهل مكة بالعفو والأمان في الجملة، ولم يجعل يوم القدرة يوماً للانتقام الشخصي. أما العبارة المشهورة «اذهبوا فأنتم الطلقاء» فتُذكر في كتب السيرة، لكنها لا تثبت بإسناد صحيح على أنها لفظ نبوي ثابت، ولذلك لا نعتمدها كاقتباس قطعي.',
        'وبعد الفتح دخل الناس في دين الله أفواجاً، وبدأت مرحلة جديدة من استقرار الجزيرة وانتشار الإسلام. وتعلمنا الحادثة أن النصر ليس لحظة تشفٍّ، بل مسؤولية في إقامة العدل وإزالة الظلم وحفظ الأنفس.',
      ],
      lessons: [
        'القوة الحقيقية تظهر في ضبط النفس عند القدرة، لا في الانتقام ممن أصبحوا عاجزين.',
        'الوفاء بالعهود أساس العلاقات، ونقض العهد له عواقب خطيرة.',
        'التواضع عند النجاح يحفظ القلب من الغرور ويذكّر الإنسان بأن الفضل لله.',
        'إصلاح العقيدة وإزالة الشرك كان الهدف الأبرز من تطهير البيت الحرام.',
        'العفو لا يعني إلغاء العدل أو ترك الحقوق، بل ترك الانتقام الشخصي مع حفظ الحقوق.',
      ],
      practicalApplication: 'اجعل من فتح مكة درساً في التعامل مع النجاح والخلاف:\n\n• إذا أصبحت في موضع قوة، فلا تستغل ضعف الآخرين للإهانة أو التشفي.\n• أوفِ بوعودك واتفاقاتك، ولا تجعل المصلحة المؤقتة سبباً للخيانة.\n• عندما تنجح، انسب الفضل إلى الله واشكر من ساعدك.\n• إذا سامحت شخصاً، فاجعل عفوك واعياً ومتزناً مع وضع حدود تمنع تكرار الأذى.\n• ابدأ إصلاح نفسك وبيئتك بإزالة ما تعلم أنه خطأ.\n\n**تأمل:** كيف ستتعامل مع شخص أساء إليك إذا أصبحت قادراً على رد الإساءة؟',
      question: SeerahQuestion(
        question: 'كم صنماً كان حول الكعبة عند فتح مكة وفق حديث صحيح البخاري؟',
        options: ['100 صنم', '180 صنماً', '360 صنماً', '500 صنم'],
        correctAnswer: 2,
        explanation: 'روى البخاري عن عبد الله بن مسعود رضي الله عنه أن حول الكعبة يوم الفتح كانت ثلاثمائة وستون نصباً، فجعل النبي ﷺ يطعنها ويقرأ: {جاء الحق وزهق الباطل}.',
      ),
      relatedStories: ['صلح الحديبية', 'بيعة الرضوان'],
    ),

    // القصة 9 — حجة الوداع | المصادر: صحيح مسلم 1218؛ صحيح البخاري 1739؛ سورة المائدة 3.
    SeerahStory(
      id: 9, title: 'حجة الوداع: وصايا جامعة للأمة', subtitle: 'النبي ﷺ يعلّم المسلمين مناسك الحج وحقوق العباد',
      category: 'الحج والعبادات', location: 'مكة المكرمة — منى وعرفة ومزدلفة', readingMinutes: 8, emoji: '🕋',
      storyParagraphs: [
        'في السنة العاشرة للهجرة أعلن النبي ﷺ عزمه على الحج، فتوافد المسلمون من أنحاء الجزيرة ليحجوا معه ويتعلموا منه المناسك عملياً. وعُرفت هذه الحجة بحجة الوداع، لأنها كانت آخر حجة حجها النبي ﷺ، وقد تضمنت توجيهات عظيمة في العبادة وحقوق الناس.',
        'خرج النبي ﷺ من المدينة وأحرم، ثم وصل مكة وأدى أعمال النسك، وعلّم أصحابه صفة الحج. وكان يوجههم إلى أن يأخذوا عنه مناسكهم، حتى لا يقعوا في الخطأ أو يبتدعوا في العبادة ما ليس منها.',
        'وفي يوم عرفة وقف النبي ﷺ بعرفة، وهو أعظم أركان الحج، وخطب الناس وذكّرهم بحرمة الدماء والأموال، وبإبطال أمور من الجاهلية، وبحقوق النساء. وجاء في حديث جابر الطويل في صحيح مسلم وصف حجة النبي ﷺ وخطبته، وفيه قوله ﷺ: «اتقوا الله في النساء»، وبيانه أن المسلمين أخذوهن بأمانة الله.',
        'وأكد النبي ﷺ حرمة الاعتداء على الناس، فشبّه حرمة الدماء والأموال بحرمة اليوم والشهر والبلد. وهذا يرسخ أن المسلم لا يجوز له أن يظلم غيره أو يأكل ماله أو يعتدي على عرضه، وأن العبادة لا تنفصل عن حسن المعاملة.',
        'ومن وصاياه في الحج إبطال الربا الجاهلي، وبيان أن دماء الجاهلية موضوعة، وأن أول دم يضعه من دماء الجاهلية دم ابن ربيعة بن الحارث، وأول ربا يضعه ربا العباس بن عبد المطلب. وبدأ بنفسه وأقاربه في إعلان إبطال تلك الحقوق الجاهلية، ليكون التطبيق واضحاً لا مجرد كلام.',
        'كما بلّغ النبي ﷺ الناس ما أُمر به، وأشهد الله عليهم. ونزل في تلك المرحلة قول الله تعالى: {الْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِي وَرَضِيتُ لَكُمُ الْإِسْلَامَ دِينًا}. وقد وردت أحاديث صحيحة في فضل يوم عرفة وأحكام الحج وتفاصيل خطبته.',
        'ومن المهم أن نتحرى ألفاظ خطبة الوداع؛ فبعض العبارات المشهورة على الألسنة تحتاج إلى تخريج مستقل، ولا يصح جمع كل ما يُتداول في نص واحد ثم نسبته إلى النبي ﷺ دون تمييز.',
        'كانت حجة الوداع مدرسة عملية للأمة: عبادة يتعلمها الناس بالفعل، وحقوق تحفظ المجتمع، ووصايا تبقى نافعة بعد رحيل النبي ﷺ. وأفضل طريقة لإحياء ذكراها هي تعلم المناسك والعمل بما ثبت من توجيهاته في العدل والرحمة وأداء الحقوق.',
      ],
      lessons: [
        'صحة العبادة تحتاج إلى تعلمها من مصادرها الصحيحة، لا الاكتفاء بالعادات.',
        'حرمة الدماء والأموال والأعراض أصل عظيم في الإسلام.',
        'حقوق النساء والأسرة أمانة شرعية يجب أن تؤدى بالمعروف والعدل.',
        'إبطال الظلم يبدأ من الإنسان نفسه وأقرب الناس إليه.',
        'كمال الدين نعمة تستوجب الشكر والتعلم والعمل.',
      ],
      practicalApplication: 'حوّل وصايا حجة الوداع إلى ممارسات يومية:\n\n• راجع حقوق الناس عندك: هل عليك دين؟ هل أخّرت أمانة؟ هل ظلمت أحداً؟\n• تعلّم أحكام عباداتك من مصدر موثوق، وخصوصاً الصلاة والزكاة والحج.\n• عامل زوجتك وأمك وأختك وسائر النساء بالعدل والرحمة وحفظ الكرامة.\n• ابتعد عن المعاملات المالية الظالمة، واسأل أهل العلم فيما يشتبه عليك.\n• إذا نصحت غيرك، فابدأ بإصلاح ما تستطيع من نفسك وأهلك.\n\n**تأمل:** ما الحق الذي يجب أن ترده إلى صاحبه قبل أن تطلب من الآخرين الالتزام بحقوقهم؟',
      question: SeerahQuestion(
        question: 'في أي سنة هجرية كانت حجة الوداع؟',
        options: ['السنة السادسة', 'السنة الثامنة', 'السنة العاشرة', 'السنة الثانية عشرة'],
        correctAnswer: 2,
        explanation: 'أدى النبي ﷺ حجة الوداع في السنة العاشرة للهجرة، وكانت آخر حجة حجها قبل وفاته ﷺ.',
      ),
      relatedStories: ['وفاة النبي ﷺ', 'أحكام الحج ومناسكه'],
    ),

    // القصة 10 — وفاة النبي ﷺ | المصادر: صحيح البخاري 4436 و4452 و3669-3670؛ سورة آل عمران 144.
    SeerahStory(
      id: 10, title: 'وفاة النبي ﷺ: ثبات الأمة بعد الرحيل', subtitle: 'آخر أيام الرسول ﷺ وموقف أبي بكر الصديق',
      category: 'وفاة النبي', location: 'المدينة المنورة — حجرة عائشة رضي الله عنها', readingMinutes: 8, emoji: '🌿',
      storyParagraphs: [
        'بعد عودة النبي ﷺ من حجة الوداع، اشتد عليه المرض في أواخر حياته. ومع ذلك ظل يوجه أصحابه ويحرص على الصلاة وشؤون الأمة. وكان مرضه الأخير شديداً، حتى احتاج إلى أن يصلي جالساً في بعض الأوقات.',
        'ولما اشتد المرض، أمر أبا بكر الصديق رضي الله عنه أن يصلي بالناس. وكان ذلك دليلاً على مكانة أبي بكر وقربه من النبي ﷺ، وعلى أهمية استمرار الجماعة والصلاة حتى في أصعب الظروف. وقد صلى أبو بكر بالناس في تلك الأيام، بينما كان النبي ﷺ يتابعهم من حجرته حين استطاع.',
        'وفي يوم الاثنين، اشتد المرض بالنبي ﷺ في حجرة عائشة رضي الله عنها. وكشفت عائشة في الأحاديث الصحيحة أنه كان يذكر الله ويختار الرفيق الأعلى. ومن آخر ما ثبت عنه قوله: «اللهم الرفيق الأعلى»، فكان آخر اختياره لقاء الله سبحانه.',
        'ثم توفي رسول الله ﷺ، فكان وقع الخبر عظيماً على الصحابة. لم يكن سهلاً عليهم أن يستوعبوا رحيل أحب الناس إليهم، وظهر الحزن والاضطراب في المدينة. وكان عمر بن الخطاب رضي الله عنه شديد التأثر، فأنكر أن يكون النبي ﷺ قد مات في أول الأمر.',
        'وجاء أبو بكر الصديق رضي الله عنه، فدخل على النبي ﷺ وكشف عن وجهه وقبّله، ثم خرج إلى الناس وخاطبهم بكلمات ثبتت في صحيح البخاري: «من كان يعبد محمداً فإن محمداً قد مات، ومن كان يعبد الله فإن الله حي لا يموت». ثم تلا قول الله تعالى: {وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِنْ قَبْلِهِ الرُّسُلُ أَفَإِن مَّاتَ أَوْ قُتِلَ انقَلَبْتُمْ عَلَىٰ أَعْقَابِكُمْ}.',
        'كان لهذه الآية أثر عظيم في نفوس الصحابة؛ فقد أدركوا أن الرسالة لا تنتهي بموت رسول الله ﷺ، وأن العبادة لله وحده، وأن واجبهم أن يثبتوا على الدين ويحفظوا ما تعلموه منه. وروى ابن عباس رضي الله عنهما أن الناس كأنهم لم يكونوا يعلمون أن هذه الآية نزلت حتى تلاها أبو بكر يومئذ.',
        'ثم انشغل الصحابة بتجهيز النبي ﷺ ودفنه، وبترتيب أمر الأمة حتى لا تقع في الفوضى. وكانت وفاته ﷺ يوم الاثنين في السنة الحادية عشرة للهجرة، أما تحديد اليوم من شهر ربيع الأول ففيه خلاف بين أهل العلم، فلا ينبغي الجزم بتاريخ مختلف فيه.',
        'إن أعظم ما نتعلمه من هذا اليوم أن محبة النبي ﷺ لا تعني الغلو فيه، بل تعني الإيمان بأنه رسول الله وخاتم الأنبياء، واتباع سنته، والثبات على التوحيد بعد وفاته. فالمؤمن يحب الرسول ﷺ حباً عظيماً، لكنه يعبد الله وحده، ويواصل طريق الخير الذي دلّ عليه النبي ﷺ.',
      ],
      lessons: [
        'العبادة لله وحده، فلا يرتبط إيمان المسلم ببقاء شخص مهما بلغت محبته ومكانته.',
        'الثبات وقت الصدمة يحتاج إلى العلم والإيمان واستحضار كلام الله.',
        'أبو بكر رضي الله عنه قدّم نموذجاً في ضبط النفس وتذكير الناس بالأصل الذي يجمعهم.',
        'الصلاة والجماعة من أعظم شعائر الإسلام، ولذلك كان النبي ﷺ حريصاً على استمرار الصلاة بالناس.',
        'محبة النبي ﷺ الصادقة تظهر في اتباع سنته والاقتداء بأخلاقه.',
      ],
      practicalApplication: 'اجعل ذكرى وفاة النبي ﷺ دافعاً للثبات والعمل:\n\n• اقرأ كل أسبوع حديثاً صحيحاً من سنته، وتأكد من تطبيق معناه.\n• إذا مررت بفقد، اسمح لنفسك بالحزن، لكن لا تدع الحزن يقطع صلتك بالله وواجباتك.\n• حافظ على الصلاة؛ فهي من أعظم ما يصل العبد بربه.\n• لا تجعل حبك لشخص صالح سبباً في الغلو فيه، فالعبادة حق لله وحده.\n• ساعد من حولك على الثبات وقت الأزمات بالكلمة الطيبة والمعلومة الصحيحة.\n\n**تأمل:** ما القيمة أو العمل الصالح الذي ستواصل القيام به وفاءً لما تعلمته من شخص تحبه؟',
      question: SeerahQuestion(
        question: 'ما الآية التي تلاها أبو بكر رضي الله عنه عندما توفي النبي ﷺ؟',
        options: ['إن مع العسر يسراً', 'وما محمد إلا رسول قد خلت من قبله الرسل', 'اليوم أكملت لكم دينكم', 'قل هو الله أحد'],
        correctAnswer: 1,
        explanation: 'تلا أبو بكر رضي الله عنه الآية 144 من سورة آل عمران، فذكّر الصحابة بأن محمداً ﷺ رسول قد مضى قبله رسل، وأن العبادة لله الحي الذي لا يموت.',
      ),
      relatedStories: ['حجة الوداع', 'بيعة أبي بكر الصديق رضي الله عنه'],
    ),
