    // القصة 11 — غزوة أُحد
    // المصادر: القرآن الكريم، آل عمران 3:152–153؛ صحيح البخاري، حديث البراء في الرماة يوم أُحد (4067).
    SeerahStory(
      id: 11,
      title: 'أُحد: حين علّمت الطاعة الأمة',
      subtitle: 'درس في الثبات والانضباط بعد بداية النصر',
      category: 'الغزوات',
      location: 'جبل أُحد — المدينة المنورة',
      readingMinutes: 6,
      emoji: '🏔️',
      storyParagraphs: [
        'بعد انتصار المسلمين في بدر، خرجت قريش في العام التالي تريد الثأر. والتقى الجيشان عند جبل أُحد في السنة الثالثة للهجرة. وكانت المعركة اختباراً صعباً للمسلمين، لا في الشجاعة وحدها، بل في الالتزام بأمر القيادة وقت اشتداد الأحداث.',
        'جعل النبي ﷺ على الجبل خمسين من الرماة، وأمّر عليهم عبد الله بن جبير رضي الله عنه. وأوصاهم ألا يتركوا مواقعهم، سواء رأوا المسلمين ينتصرون أو يتعرضون للضغط؛ لأن حماية ظهر الجيش كانت مرتبطة ببقائهم في مكانهم.',
        'في بداية القتال مال النصر للمسلمين، فتراجع المشركون، ورأى بعض الرماة ما بدا لهم من انتهاء المعركة والغنائم. فنزل أكثرهم من مواقعهم، مع أن قائدهم ذكّرهم بأمر رسول الله ﷺ. وبقي عبد الله بن جبير مع عدد قليل ممن ثبتوا.',
        'لاحظ خالد بن الوليد، وكان يومئذ في صف المشركين، خلوّ جانب الجبل، فالتفّ بالخيل وهاجم المسلمين من الخلف. فتغير سير المعركة، واضطربت الصفوف، وأصيب المسلمون بخسائر كبيرة، واستُشهد نحو سبعين من الصحابة رضي الله عنهم.',
        'وأصيب النبي ﷺ في وجهه وكُسرت رباعيته، وانتشرت شائعة مقتله، فاشتد البلاء على المسلمين. ومع ذلك ثبت معه عدد من أصحابه، واستعاد المسلمون تماسكهم، وانتهت المعركة دون أن تتمكن قريش من القضاء على جماعة المسلمين في المدينة.',
        'لم يترك القرآن أحداث أُحد بلا بيان؛ فقد وضّح أن ما وقع كان مرتبطاً بالفشل والتنازع ومخالفة الأمر بعد أن أراهم الله ما يحبون، كما في سورة آل عمران (152). لم تكن أُحد نهاية الدعوة، بل صارت درساً تربوياً في الطاعة والصبر ومراجعة الأخطاء.',
      ],
      lessons: [
        'الالتزام بالتوجيهات الواضحة واجب حتى عندما تبدو الظروف وكأنها تغيرت',
        'قد يتغير مسار العمل كله بسبب قرار متعجل من بعض أفراده',
        'الخطأ لا يعني نهاية الطريق؛ المهم الاعتراف به والتعلم منه',
        'الثبات وقت الاضطراب يحتاج إلى إيمان وانضباط معاً',
        'القرآن يعلّمنا أن نراجع أسباب الإخفاق بدل الاكتفاء بالحزن عليه',
      ],
      practicalApplication: 'تطبيق درس أُحد في حياتك:\n\n• حدّد المسؤوليات والتعليمات المهمة في دراستك أو عملك، ولا تتركها لمجرد أن النتيجة تبدو قريبة.\n• عندما تخطئ، لا تبحث عن مبررات؛ اسأل: ما السبب؟ وكيف أمنع تكراره؟\n• لا تجعل المكسب العاجل يجعلك تفرّط في هدف أكبر أو أمانة تحملتها.',
      question: SeerahQuestion(
        question: 'ما السبب المباشر الذي مكّن فرسان قريش من الالتفاف على المسلمين في أُحد؟',
        options: ['نزول أكثر الرماة من مواقعهم', 'نقص الطعام', 'غياب النبي ﷺ عن المعركة', 'انسحاب أهل المدينة'],
        correctAnswer: 0,
        explanation: 'ترك أكثر الرماة مواقعهم التي أمرهم النبي ﷺ بالبقاء فيها، فانكشف ظهر المسلمين واستطاع فرسان قريش الالتفاف عليهم.',
      ),
      relatedStories: ['غزوة بدر', 'غزوة الخندق'],
    ),

    // القصة 12 — غزوة الخندق
    // المصادر: صحيح البخاري، أحاديث حفر الخندق والصخرة (2835، 4101)؛ القرآن الكريم، الأحزاب 33:9–27. نسبة اقتراح الخندق لسلمان مشهورة في السيرة، وإسنادها محل بحث.
    SeerahStory(
      id: 12,
      title: 'الخندق: فكرة صنعت فرقاً',
      subtitle: 'الشورى والعمل الجماعي في وقت الخطر',
      category: 'الغزوات',
      location: 'المدينة المنورة',
      readingMinutes: 6,
      emoji: '⛏️',
      storyParagraphs: [
        'في السنة الخامسة للهجرة تجمعت قبائل وأحزاب من قريش وغيرها لمهاجمة المدينة. كان الخطر كبيراً؛ فالمدينة مهددة من خارجها، وأهلها يواجهون حصاراً وضغطاً شديدين، بينما كان المسلمون أقل عدداً وعدة من جموع الأحزاب.',
        'استشار النبي ﷺ أصحابه في كيفية حماية المدينة. وتذكر كتب السيرة أن سلمان الفارسي رضي الله عنه أشار بحفر خندق في الجهة المكشوفة، وهي وسيلة دفاع عرفها الفرس. وهذه النسبة مشهورة في كتب السيرة، لكن تفاصيل إسنادها ليست في قوة أحاديث الصحيحين؛ لذلك لا نجعلها أساس القصة وحدها.',
        'أخذ المسلمون بالأسباب وشرعوا في الحفر، وشاركهم النبي ﷺ بنفسه في العمل وحمل التراب. وتروي أحاديث صحيحة أن المهاجرين والأنصار كانوا يحفرون وينقلون التراب على ظهورهم، وكان النبي ﷺ يدعو لهم ويذكرهم بأن الخير الحقيقي هو خير الآخرة.',
        'واجه الحافرون الجوع والتعب، واعترضتهم صخرة شديدة. وفي حديث جابر رضي الله عنه في صحيح البخاري أنه أخبر النبي ﷺ بها، فنزل إليها وضربها حتى تفتتت. وتصف الرواية كذلك شدة الجوع التي كان النبي ﷺ وأصحابه يعانونها أثناء الحفر.',
        'وصلت جموع الأحزاب فوجدت الخندق عائقاً أمام اقتحام المدينة، وامتد الحصار أياماً عصيبة. ووصف القرآن خوف المسلمين وشدة الموقف في سورة الأحزاب: «إذ جاءوكم من فوقكم ومن أسفل منكم...». ثم صرف الله الأحزاب، فانفضّ جمعهم وانتهى الحصار.',
        'كانت غزوة الخندق مثالاً واضحاً على اجتماع التوكل مع التخطيط، وعلى أن القائد لا يكتفي بإصدار الأوامر، بل يشارك الناس العمل ويتحمل معهم المشقة. كما أظهرت قيمة الشورى والاستفادة من الخبرات النافعة.',
      ],
      lessons: [
        'التوكل الصحيح لا يمنع التخطيط والأخذ بالأسباب',
        'الشورى تفتح أبواباً للحلول قد لا تخطر على فرد واحد',
        'القيادة الناجحة تشارك الفريق في العمل وتتحمل المشقة',
        'الخبرة النافعة تُقبل ممن يملكها ما دامت لا تخالف الشرع',
        'الأزمات تحتاج إلى صبر وتعاون وثبات، لا إلى اليأس والارتباك',
      ],
      practicalApplication: 'من درس الخندق:\n\n• إذا واجهت مشكلة كبيرة، اجمع أهل الخبرة واسمع أكثر من رأي قبل اتخاذ القرار.\n• حوّل الخوف إلى خطة عملية، وقسّم المهمة الصعبة إلى خطوات يمكن تنفيذها.\n• شارك من تعمل معهم في الأعباء، ولا تطلب منهم ما لا تستعد أن تفعله بنفسك.',
      question: SeerahQuestion(
        question: 'ما المبدأ العملي الأبرز الذي ظهر في حفر الخندق؟',
        options: ['ترك التخطيط وانتظار النصر', 'الشورى والأخذ بالأسباب والعمل الجماعي', 'الاعتماد على كثرة العدد', 'تجنب مشاركة القائد في العمل'],
        correctAnswer: 1,
        explanation: 'أخذ المسلمون بالأسباب، وتشاوروا، وعملوا معاً، وشاركهم النبي ﷺ في الحفر؛ فاجتمع التخطيط والتعاون والتوكل.',
      ),
      relatedStories: ['غزوة أُحد', 'حجة الوداع'],
    ),

    // القصة 13 — بيعة الرضوان
    // المصادر: القرآن الكريم، الفتح 48:18؛ صحيح البخاري، حديث بيعة الرضوان وبيعة النبي ﷺ عن عثمان (3698 وما في معناه).
    SeerahStory(
      id: 13,
      title: 'بيعة الرضوان تحت الشجرة',
      subtitle: 'وفاء الصحابة وثباتهم عند الشدة',
      category: 'المواقف الإيمانية',
      location: 'الحديبية — قرب مكة',
      readingMinutes: 5,
      emoji: '🌳',
      storyParagraphs: [
        'في السنة السادسة للهجرة خرج النبي ﷺ وأصحابه يريدون العمرة، لا القتال. فمنعتهم قريش من دخول مكة، ونزل المسلمون بالحديبية، وبدأت المفاوضات للوصول إلى اتفاق يحقن الدماء ويتيح للناس فرصة الأمن.',
        'أرسل النبي ﷺ عثمان بن عفان رضي الله عنه إلى مكة ليبلغ قريشاً أن المسلمين لم يأتوا لحرب، وأن مقصدهم زيارة البيت الحرام. وتأخر عثمان في العودة، فانتشر بين المسلمين خبر مقتله، فكان ذلك أمراً عظيماً؛ لأن قتل رسول قريش للمسلمين اعتداء لا يمكن السكوت عنه.',
        'دعا النبي ﷺ أصحابه إلى البيعة، فبايعوه تحت شجرة على الثبات وألا يفروا. وتسمى هذه بيعة الرضوان، وقد أثنى الله على أهلها في سورة الفتح: «لقد رضي الله عن المؤمنين إذ يبايعونك تحت الشجرة فعلم ما في قلوبهم فأنزل السكينة عليهم وأثابهم فتحاً قريباً».',
        'لم يكن عثمان رضي الله عنه حاضراً حين تمت البيعة؛ لأنه كان في مكة مبعوثاً من النبي ﷺ. فضرب له النبي ﷺ بيده، فكانت يده عن عثمان، كما ثبت في صحيح البخاري. وهذا يبين مكانة عثمان وحرص النبي ﷺ على ألا يفوته فضل البيعة بسبب المهمة التي كُلّف بها.',
        'ثم تبيّن أن خبر قتل عثمان لم يكن صحيحاً، وعادت المفاوضات إلى مسارها، وانتهى الأمر بصلح الحديبية. وقد بدا لبعض الصحابة أن شروط الصلح شديدة، لكن الله سمّى ما ترتب عليه فتحاً مبيناً؛ إذ أتاح الهدوء وانتشار الدعوة ودخول الناس في الإسلام.',
        'تظل بيعة الرضوان شاهداً على صدق الصحابة وثباتهم، وعلى أن الوفاء لا يظهر في أوقات الراحة فقط، بل يظهر حين يشتد الخطر ويحتاج الموقف إلى تضحية وصبر.',
      ],
      lessons: [
        'الوفاء بالعهد يظهر عند الشدائد لا عند سهولة الأمور فقط',
        'قد يكون العمل الذي لا يراه الناس سبباً في فوات حضور مناسبة عظيمة، لكن النية والطاعة لهما قدرهما',
        'رضا الله أعظم من المكاسب العاجلة',
        'ليس كل ما يبدو تأخراً أو تنازلاً يكون خسارة في العاقبة',
        'الشورى والثبات يساعدان الجماعة على تجاوز الأزمات',
      ],
      practicalApplication: 'تأمل بيعة الرضوان:\n\n• كن وفياً بوعودك، خصوصاً عندما يصبح تنفيذها صعباً.\n• لا تحكم على النتائج من بدايتها؛ فقد تظهر الحكمة بعد وقت.\n• قدّم المصلحة العامة والحق على المكسب الشخصي السريع.',
      question: SeerahQuestion(
        question: 'لماذا لم يكن عثمان بن عفان رضي الله عنه حاضراً عند البيعة تحت الشجرة؟',
        options: ['لأنه رجع إلى المدينة', 'لأن النبي ﷺ أرسله إلى مكة رسولاً', 'لأنه كان مريضاً', 'لأنه تأخر عن الجيش'],
        correctAnswer: 1,
        explanation: 'كان عثمان رضي الله عنه في مكة مبعوثاً من النبي ﷺ، فضرب له النبي ﷺ بيده عند البيعة كما ورد في صحيح البخاري.',
      ),
      relatedStories: ['صلح الحديبية', 'فتح مكة'],
    ),

    // القصة 14 — إسلام خالد بن الوليد
    // المصادر: صحيح البخاري، حديث مؤتة ووصف خالد بأنه سيف من سيوف الله (4262)؛ تفاصيل إسلام خالد تُراجع في كتب السيرة.
    SeerahStory(
      id: 14,
      title: 'خالد بن الوليد: من خصومة إلى نصرة',
      subtitle: 'حين تحولت القوة إلى خدمة الحق',
      category: 'الصحابة',
      location: 'المدينة المنورة',
      readingMinutes: 5,
      emoji: '⚔️',
      storyParagraphs: [
        'كان خالد بن الوليد رضي الله عنه من فرسان قريش المعروفين بالشجاعة وحسن التدبير العسكري. وشارك في صف قريش يوم أُحد، وكان التفاف الفرسان على المسلمين من الأسباب العسكرية التي قلبت سير المعركة في ذلك اليوم.',
        'لكن المواقف تتغير، والإنسان قد ينتقل من موقف إلى آخر حين يتبين له الحق. وبعد صلح الحديبية أخذ خالد يفكر في الإسلام، ورأى أن الأمر لم يعد كما كان يتصوره، وأن دعوة النبي ﷺ تزداد انتشاراً وقوة.',
        'تذكر كتب السيرة أن خالداً خرج إلى المدينة في السنة الثامنة للهجرة، والتقى في الطريق بعمرو بن العاص وعثمان بن طلحة، فقدموا معاً وأسلموا. وتذكر روايات السيرة حواراً بين خالد والنبي ﷺ عند قدومه، ومعانيه الاعتراف بأن الله هداه بعد أن كان بعيداً عن الإسلام.',
        'فرح النبي ﷺ بإسلام خالد، ثم صار خالد من قادة المسلمين. وفي مؤتة، بعد استشهاد القادة الثلاثة الذين عيّنهم النبي ﷺ، أخذ خالد الراية، فحفظ الله به جيش المسلمين من أن يُستأصل، وثبت في الصحيح أن النبي ﷺ وصفه يومئذ بأنه سيف من سيوف الله.',
        'لم تكن قيمة خالد في مهارته القتالية وحدها، بل في توجيه قدرته بعد إسلامه إلى نصرة الدين، وفي استعداده لتغيير موقفه عندما ظهر له الحق. فالقوة قد تكون خطراً إذا وُجهت للباطل، وقد تصبح نعمة عظيمة إذا استُعملت في الخير والعدل.',
      ],
      lessons: [
        'لا تجعل مواقفك القديمة تمنعك من الرجوع إلى الحق',
        'الموهبة والقوة أمانة، وقيمتهما في الوجهة التي تُستخدمان فيها',
        'الهداية قد تغيّر مسار حياة الإنسان بالكامل',
        'الشجاعة الحقيقية تشمل شجاعة الاعتراف بالخطأ وتغيير الطريق',
        'الإخلاص والعمل الصالح أهم من الشهرة والإنجاز الشخصي',
      ],
      practicalApplication: 'من سيرة خالد:\n\n• إذا ظهر لك أنك أخطأت، فامتلك شجاعة تصحيح موقفك.\n• استخدم مهاراتك في خدمة الناس والحق، لا في إيذائهم أو التكبر عليهم.\n• لا تحكم على إنسان من ماضيه وحده؛ فباب التغيير والهداية مفتوح.',
      question: SeerahQuestion(
        question: 'في أي غزوة أخذ خالد بن الوليد الراية بعد استشهاد القادة الثلاثة؟',
        options: ['بدر', 'أُحد', 'مؤتة', 'حنين'],
        correctAnswer: 2,
        explanation: 'في غزوة مؤتة أخذ خالد الراية بعد استشهاد زيد بن حارثة وجعفر بن أبي طالب وعبد الله بن رواحة رضي الله عنهم، وثبت في الحديث وصفه بسيف من سيوف الله.',
      ),
      relatedStories: ['غزوة أُحد', 'فتح مكة'],
    ),

    // القصة 15 — انشقاق القمر
    // المصادر: القرآن الكريم، القمر 54:1–2؛ صحيح البخاري وصحيح مسلم، أحاديث انشقاق القمر عن ابن مسعود وغيره.
    SeerahStory(
      id: 15,
      title: 'انشقاق القمر: آية ومعنى',
      subtitle: 'معجزة أيد الله بها رسوله ﷺ',
      category: 'المعجزات',
      location: 'مكة المكرمة',
      readingMinutes: 4,
      emoji: '🌙',
      storyParagraphs: [
        'كان أهل مكة يطلبون من النبي ﷺ آيات تدل على صدق رسالته، مع أن القرآن نفسه آية باقية تهدي من يطلب الحق. ومن الآيات التي وقعت في العهد المكي انشقاق القمر، وقد ذكر القرآن ذلك في مطلع سورة القمر: «اقتربت الساعة وانشق القمر».',
        'وجاءت أحاديث صحيحة عن عدد من الصحابة تصف أن القمر انشق فرقتين، وأن النبي ﷺ أشار إلى الآية ودعا الناس إلى الشهادة. ومن ذلك حديث عبد الله بن مسعود رضي الله عنه في صحيح البخاري وصحيح مسلم.',
        'لم يكن موقف المكذبين أن يبحثوا بإنصاف عن دلالة الآية؛ بل وصف بعضهم ما رأوه بأنه سحر، كما ورد في سياق سورة القمر: «وإن يروا آية يعرضوا ويقولوا سحر مستمر». فالآية تعرض الحدث وتكشف أيضاً موقف من أعرض عن الحق بعد ظهوره.',
        'المعجزة في العقيدة الإسلامية أمر خارق للعادة يجريه الله تأييداً لنبيه، وليست تجربة علمية يُطلب من الناس إعادة إجرائها. لذلك لا يصح ربط الإيمان بانشقاق القمر بادعاءات حديثة عن شقوق على سطح القمر أو صور تزعم إثبات الحادثة؛ فهذه الادعاءات لا تثبتها المصادر العلمية الموثوقة، والإيمان بالخبر يقوم على ثبوت النص.',
        'وتعلمنا القصة أن وضوح الدليل وحده لا يضمن قبول الإنسان له إذا استولى عليه الكبر أو العناد. كما تذكرنا بأن القرآن يدعو إلى التفكر والإنصاف، لا إلى تعليق الإيمان على قصص غير موثقة أو ادعاءات لا دليل عليها.',
      ],
      lessons: [
        'المعجزات آيات من الله، وثبوتها يكون بالنصوص الصحيحة',
        'الإنسان يحتاج إلى الصدق والتواضع حتى ينتفع بالدليل',
        'لا يجوز تقوية الدين بادعاءات علمية غير موثقة',
        'القرآن يجمع بين ذكر الآية وبيان مواقف الناس منها',
      ],
      practicalApplication: 'تأمل في القصة:\n\n• تحرّ الدليل قبل نشر أي معلومة دينية أو علمية.\n• إذا ظهر لك الحق، فلا تجعل الكبر أو ضغط الآخرين يمنعك من قبوله.\n• اجعل القرآن والسنة الصحيحة أصل معرفتك بالدين، ولا تبنِ يقينك على مقاطع مجهولة المصدر.',
      question: SeerahQuestion(
        question: 'في أي سورة ورد ذكر انشقاق القمر؟',
        options: ['سورة الرحمن', 'سورة القمر', 'سورة النجم', 'سورة الإسراء'],
        correctAnswer: 1,
        explanation: 'ورد في أول سورة القمر قوله تعالى: «اقتربت الساعة وانشق القمر»، وجاءت أحاديث صحيحة تؤكد وقوع هذه الآية في زمن النبي ﷺ.',
      ),
      relatedStories: ['الإسراء والمعراج', 'حنين الجذع'],
    ),

    // القصة 16 — أذى قريش للنبي ﷺ
    // المصدر: صحيح البخاري وصحيح مسلم، حديث وضع سلى الجزور على ظهر النبي ﷺ وهو ساجد وإزالة فاطمة له.
    SeerahStory(
      id: 16,
      title: 'حلم النبي ﷺ أمام أذى قريش',
      subtitle: 'ثبات ورحمة من غير روايات مختلقة',
      category: 'الأخلاق',
      location: 'المسجد الحرام — مكة المكرمة',
      readingMinutes: 4,
      emoji: '💚',
      storyParagraphs: [
        'تعرض النبي ﷺ في مكة لأذى شديد من بعض المشركين، ولم يكن أذاهم مجرد كلمات؛ بل وصل إلى الاعتداء عليه وهو يصلي عند الكعبة. ومع ذلك واصل عبادته ودعوته، ولم يصرفه الأذى عن تبليغ رسالة الله.',
        'يروي عبد الله بن مسعود رضي الله عنه في الصحيحين أن النبي ﷺ كان يصلي عند البيت، فجاء عقبة بن أبي معيط فوضع سلى جزور على ظهره الشريف وهو ساجد. والسلى هو ما يخرج من بطن الناقة أو الشاة، وكان ذلك اعتداءً قبيحاً متعمداً.',
        'لم يستطع النبي ﷺ أن يرفع ما وُضع على ظهره من شدة ثقله، حتى جاءت فاطمة رضي الله عنها فأزالته عنه، وأخذت تسب المعتدين. وتكشف هذه الحادثة مقدار ما تحمله النبي ﷺ في سبيل دعوته، كما تكشف شجاعة فاطمة ووفاءها لأبيها.',
        'لا يصح أن نضيف إلى هذه الحادثة قصة بصقة تحولت إلى عطر، أو ننسب إليها دعاءً بعينه من غير سند ثابت. فالعبرة لا تحتاج إلى زيادة غير موثقة؛ إذ يكفي ما ثبت من أذى النبي ﷺ وصبره، ومن دفاع أهله عنه.',
        'وكان النبي ﷺ مثالاً في الحلم والرحمة، لكنه لم يكن يقر الظلم أو يطلب من الناس ترك حماية المظلوم. فالصبر على الأذى في سبيل الحق خلق عظيم، مع الأخذ بالأسباب المشروعة لمنع الاعتداء وحفظ الكرامة.',
      ],
      lessons: [
        'الثبات على الحق يحتاج إلى صبر حين يشتد الأذى',
        'لا يجوز اختلاق القصص أو الأحاديث حتى لو كان مقصدها مدح النبي ﷺ',
        'الوفاء للأسرة ومساندة المظلوم من الأخلاق الكريمة',
        'الحلم لا يعني قبول الظلم أو تعطيل وسائل الحماية المشروعة',
      ],
      practicalApplication: 'تعلّم من الموقف:\n\n• لا تجعل إساءة الآخرين تدفعك إلى التخلي عن قيمك.\n• قف بجانب من يتعرض للظلم، وساعده بطريقة حكيمة وآمنة.\n• قبل أن تنشر قصة مؤثرة عن النبي ﷺ، تحقق من مصدرها وصحة نسبتها.',
      question: SeerahQuestion(
        question: 'من التي أزالت سلى الجزور عن ظهر النبي ﷺ وهو ساجد؟',
        options: ['عائشة رضي الله عنها', 'فاطمة رضي الله عنها', 'أم سلمة رضي الله عنها', 'أسماء بنت أبي بكر رضي الله عنها'],
        correctAnswer: 1,
        explanation: 'جاء في الحديث أن فاطمة رضي الله عنها أقبلت فألقته عن ظهر النبي ﷺ، وذلك بعد أن وضعه عقبة بن أبي معيط عليه وهو ساجد.',
      ),
      relatedStories: ['الهجرة إلى المدينة', 'فتح مكة'],
    ),

    // القصة 17 — غزوة تبوك
    // المصادر: القرآن الكريم، التوبة 9:38–92؛ أحاديث فضائل عثمان وتجهيزه جيش العسرة، مع ترك الأعداد المختلف في ثبوتها.
    SeerahStory(
      id: 17,
      title: 'غزوة العسرة: البذل وقت الضيق',
      subtitle: 'تبوك واختبار الصدق والاستعداد',
      category: 'الغزوات',
      location: 'تبوك — شمال الجزيرة العربية',
      readingMinutes: 5,
      emoji: '🏜️',
      storyParagraphs: [
        'في السنة التاسعة للهجرة دعا النبي ﷺ المسلمين إلى الخروج نحو تبوك، وكانت الرحلة بعيدة في حر شديد، وجاءت في وقت نضجت فيه الثمار ومال الناس إلى الظلال والراحة. لذلك سميت هذه الغزوة بغزوة العسرة، وذكر القرآن حال المؤمنين والمنافقين عند الاستنفار لها في سورة التوبة.',
        'كان تجهيز الجيش يحتاج إلى أموال ودواب ومؤن، ولم تكن الإمكانات متوفرة للجميع. فاستجاب الصحابة بحسب طاقتهم، وبذل أهل اليسار من أموالهم، وكان عثمان بن عفان رضي الله عنه من أبرز من جهز جيش العسرة وأنفق فيه.',
        'وتذكر روايات في فضائل عثمان أنه جاء بمال كثير وجهز جانباً كبيراً من احتياجات الجيش، وجاء في الحديث أن النبي ﷺ قال في شأن عمله في ذلك اليوم كلاماً عظيماً في فضله. أما الأرقام التفصيلية المتداولة مثل عدد محدد من الإبل والخيول فتختلف رواياتها، فلا ينبغي الجزم بها دون تحرير مصدرها.',
        'خرج المسلمون في مشقة، وبلغوا تبوك، ولم يقع قتال مع جيش الروم؛ إذ لم يلتق الجيشان في معركة. لكن الغزوة لم تكن بلا أثر: فقد أظهرت استعداد المسلمين، وعقد النبي ﷺ اتفاقات مع بعض أهل المنطقة، وعاد الجيش بعد أن حقق مقاصد الحملة دون معركة فاصلة.',
        'وتكشف غزوة العسرة أن البذل لا يقتصر على المال؛ فمن الناس من يجهز، ومنهم من يخدم، ومنهم من يصبر على السفر، ومنهم من يثبت على الطاعة رغم المشقة. وقد خلد القرآن صدق الذين جاءوا إلى النبي ﷺ يطلبون ما يحملهم عليه فلم يجدوا، فرجعوا وأعينهم تفيض من الدمع حزناً ألا يجدوا ما ينفقون.',
      ],
      lessons: [
        'الصدق يظهر عندما تكون الطاعة مكلفة وليست سهلة',
        'كل إنسان يستطيع أن يساهم بحسب قدرته، ولو لم يكن غنياً',
        'الإنفاق في وجوه الخير من أعظم صور نصرة المجتمع',
        'عدم وقوع قتال لا يعني أن الجهد أو الاستعداد كان بلا فائدة',
        'ينبغي التثبت من الأرقام والتفاصيل التاريخية قبل نشرها',
      ],
      practicalApplication: 'من غزوة العسرة:\n\n• خصص جزءاً من وقتك أو مالك لخدمة عمل نافع بحسب استطاعتك.\n• لا تجعل المشقة وحدها سبباً للتراجع عن واجب تستطيع أداءه.\n• قدّر مساهمة الآخرين حتى لو اختلفت عن مساهمتك؛ فلكل شخص قدرة ودور.',
      question: SeerahQuestion(
        question: 'لماذا سميت غزوة تبوك بغزوة العسرة؟',
        options: ['لأنها وقعت في الشتاء', 'لشدة الحر وبعد الطريق وقلة المؤن', 'لأن المسلمين حوصروا داخل المدينة', 'لأنها انتهت بهزيمة المسلمين'],
        correctAnswer: 1,
        explanation: 'كانت الرحلة إلى تبوك شاقة بسبب الحر وبعد المسافة وقلة الظهر والزاد، ولذلك عرفت بغزوة العسرة.',
      ),
      relatedStories: ['المتخلفون عن تبوك', 'بيعة الرضوان'],
    ),

    // القصة 18 — الثلاثة الذين خُلّفوا
    // المصادر: القرآن الكريم، التوبة 9:118؛ صحيح البخاري، حديث كعب بن مالك في تخلفه عن تبوك ومحنة الخمسين ليلة (4418).
    SeerahStory(
      id: 18,
      title: 'كعب بن مالك: خمسون ليلة من الصدق',
      subtitle: 'اعتراف صريح وتوبة قبلها الله',
      category: 'المواقف الإيمانية',
      location: 'المدينة المنورة',
      readingMinutes: 6,
      emoji: '🚶',
      storyParagraphs: [
        'تخلف كعب بن مالك رضي الله عنه عن غزوة تبوك من غير عذر، وكان قادراً على الخروج. وكذلك تخلف مرارة بن الربيع وهلال بن أمية رضي الله عنهما. ولم يكونوا من المنافقين الذين اعتادوا اختلاق الأعذار، لكنهم وقعوا في التسويف حتى فات وقت الخروج.',
        'لما عاد النبي ﷺ إلى المدينة جاءه المتخلفون يعتذرون، فكان بعضهم يحلف ويذكر أعذاراً غير صحيحة. أما كعب فقرر ألا يكذب، وقال للنبي ﷺ إنه لم يكن له عذر، وإنه كان في حال قدرة ويسار حين تخلف. فأمره النبي ﷺ أن ينتظر قضاء الله فيه.',
        'وأمر النبي ﷺ المسلمين ألا يكلموا الثلاثة. فمرت عليهم خمسون ليلة في هجر اجتماعي شديد، حتى ضاقت عليهم الأرض بما رحبت، كما وصف القرآن حالهم في سورة التوبة. ولم يكن ذلك ظلماً أو انتقاماً، بل كان تأديباً بأمر النبي ﷺ حتى يتبين صدق توبتهم.',
        'اشتدت المحنة على الثلاثة، وابتعد الناس عن مجالستهم، وبلغ الأمر أن أُمروا باعتزال زوجاتهم مدة من تلك المحنة. ومع ذلك ثبتوا ولم يرجعوا إلى الكذب لتخفيف الموقف. وكان كعب يشعر أن الصدق، وإن كان مؤلماً في لحظته، هو الطريق الوحيد للنجاة.',
        'ثم أنزل الله توبته عليهم في قوله تعالى: «وعلى الثلاثة الذين خُلّفوا حتى إذا ضاقت عليهم الأرض بما رحبت وضاقت عليهم أنفسهم وظنوا أن لا ملجأ من الله إلا إليه ثم تاب عليهم ليتوبوا إن الله هو التواب الرحيم» (التوبة: 118). فاستبشر المسلمون، وذهب من يبشر كعباً بقبول توبته.',
        'وتعلمنا القصة أن الصدق لا يعني أن الإنسان لن يواجه نتيجة خطئه، لكنه يمنحه طريقاً صحيحاً للإصلاح. كما تعلمنا أن التوبة ليست كلمات فقط؛ بل ندم واعتراف وترك للخطأ وصبر على تبعاته.',
      ],
      lessons: [
        'الصدق مع الله ومع الناس خير من اختلاق الأعذار',
        'التسويف قد يجعل الإنسان يفوّت واجباً كان يستطيع أداءه',
        'التوبة الصادقة تحتاج إلى اعتراف وندم وعزم على الإصلاح',
        'قد تكون التربية الحازمة سبباً في إصلاح الإنسان لا إهانته',
        'رحمة الله واسعة، فلا ييأس المذنب من الرجوع إليه',
      ],
      practicalApplication: 'طبّق درس كعب:\n\n• إذا أخطأت، اعترف بالخطأ بوضوح ولا تضف إليه كذباً جديداً.\n• لا تؤجل عملاً واجباً حتى يفوت وقته.\n• إذا ترتبت على خطئك نتائج، تحملها وحاول إصلاح ما أفسدته.\n• اجعل الصدق عادة حتى في المواقف التي تخشى فيها اللوم.',
      question: SeerahQuestion(
        question: 'كم ليلة استمرت مقاطعة كعب بن مالك وصاحبيه؟',
        options: ['ثلاثون ليلة', 'أربعون ليلة', 'خمسون ليلة', 'ستون ليلة'],
        correctAnswer: 2,
        explanation: 'استمرت المحنة خمسين ليلة، ثم نزل القرآن بقبول توبتهم في سورة التوبة، الآية 118.',
      ),
      relatedStories: ['غزوة العسرة', 'باب التوبة مفتوح'],
    ),

    // القصة 19 — طعام جابر يوم الخندق
    // المصدر: صحيح البخاري، حديث جابر في طعام الخندق (4101–4102).
    SeerahStory(
      id: 19,
      title: 'طعام قليل وبركة عظيمة',
      subtitle: 'قصة جابر بن عبد الله يوم الخندق',
      category: 'المعجزات',
      location: 'المدينة المنورة — الخندق',
      readingMinutes: 5,
      emoji: '🍞',
      storyParagraphs: [
        'كان المسلمون يحفرون الخندق حول المدينة، وقد أصابهم جوع وتعب شديدان. ورأى جابر بن عبد الله رضي الله عنه ما بالنبي ﷺ من الجوع، فعاد إلى بيته وسأل زوجته عما عندهما من طعام.',
        'لم يكن عندهما إلا مقدار قليل: صاع من شعير، وبهيمة صغيرة. فذبحاها وأعدا الطعام، وأراد جابر أن يدعو النبي ﷺ ومعه نفر قليل حتى يكفي الطعام الموجود.',
        'ذهب جابر إلى النبي ﷺ ودعاه سراً، لكن النبي ﷺ نادى أهل الخندق ودعاهم إلى الطعام. فقلق جابر؛ لأن الطعام القليل لن يكفي هذا الجمع في الحساب المعتاد. غير أن النبي ﷺ وجّهه إلى ألا يرفع القدر عن النار وألا يخبزوا العجين قبل أن يأتي.',
        'جاء النبي ﷺ إلى البيت، ودعا بالبركة، ثم جعل الطعام يُقدّم للناس. فأكل أهل الخندق، وكانوا جماعة كبيرة، حتى شبعوا، وبقي الطعام على حاله. وقد روى جابر هذه الحادثة في صحيح البخاري، وفي بعض ألفاظ الرواية أن عددهم كان ألفاً.',
        'هذه معجزة من معجزات النبي ﷺ أكرمه الله بها، وفيها إظهار لقدرة الله على خرق العادة. وهي كذلك تبرز كرم جابر وزوجته؛ فقد قدما ما يملكان مع أنه قليل، ولم يمنعهما خوف النقص من إكرام رسول الله ﷺ.',
        'ولا تعني القصة أن الإنسان يترك الحساب والتخطيط في حياته اليومية، بل تعني أن البركة بيد الله، وأن المسلم يبذل ما يستطيع، ويحسن الظن بالله، ولا يحتقر المعروف القليل إذا صدقت النية.',
      ],
      lessons: [
        'الله قادر على أن يبارك في القليل حتى يكفي جمعاً كبيراً',
        'الكرم لا يتوقف على كثرة المال أو الطعام',
        'ملاحظة حاجة الآخرين والسعي إلى مساعدتهم خلق عظيم',
        'المعجزة تزيد المؤمن يقيناً بقدرة الله وصدق رسوله ﷺ',
        'الأخذ بالأسباب لا يتعارض مع حسن الظن بالله',
      ],
      practicalApplication: 'من موقف جابر:\n\n• لا تحتقر المساعدة الصغيرة؛ فقد تكون نافعة جداً لمن يحتاجها.\n• شارك ما تستطيع مع الآخرين دون إسراف أو تضييع لحقوق من تعول.\n• انتبه لمن حولك؛ فقد يحتاج أحدهم إلى دعم لا يطلبه صراحة.',
      question: SeerahQuestion(
        question: 'في أي مناسبة وقعت قصة طعام جابر بن عبد الله؟',
        options: ['غزوة بدر', 'حفر الخندق', 'فتح مكة', 'غزوة حنين'],
        correctAnswer: 1,
        explanation: 'وقعت القصة أثناء حفر الخندق، حين رأى جابر ما بالنبي ﷺ وأصحابه من الجوع، فدعاه إلى طعام قليل فبارك الله فيه.',
      ),
      relatedStories: ['غزوة الخندق', 'حنين الجذع'],
    ),

    // القصة 20 — قاتل المئة نفس
    // المصدر: صحيح مسلم، كتاب التوبة، حديث الرجل الذي قتل مئة نفس وقبول توبته (2766a–c).
    SeerahStory(
      id: 20,
      title: 'باب التوبة مفتوح',
      subtitle: 'رحمة الله تشمل من صدق في الرجوع إليه',
      category: 'الرحمة والمغفرة',
      location: 'خبر عن أمة سابقة',
      readingMinutes: 5,
      emoji: '🚪',
      storyParagraphs: [
        'روى النبي ﷺ قصة رجل من الأمم السابقة قتل تسعاً وتسعين نفساً، ثم بدأ يسأل عن طريق التوبة. كان يعلم فداحة ما ارتكبه، لكنه أراد أن يعرف هل بقي له سبيل إلى رحمة الله أم أن ذنبه أغلق الباب أمامه.',
        'دُلّ الرجل على راهب فسأله: هل لي من توبة؟ فأجابه بأنه لا توبة له، فغضب الرجل وقتله، فأكمل به المئة. ثم لم يترك السؤال، بل بحث عن أعلم أهل الأرض، فدُلّ على عالم، وسأله عن الأمر نفسه.',
        'أجابه العالم بأن باب التوبة مفتوح، وسأله: «ومن يحول بينك وبين التوبة؟» ثم نصحه أن يترك أرضه التي اعتاد فيها الشر، وأن يذهب إلى أرض يسكنها قوم صالحون يعبدون الله، فيعيش بينهم ويشاركهم العبادة.',
        'خرج الرجل قاصداً التوبة وتغيير حياته، لكنه مات في الطريق قبل أن يصل. فاختصمت فيه ملائكة الرحمة وملائكة العذاب: هؤلاء نظروا إلى قصده وإقباله على الله، وأولئك نظروا إلى ما سبق منه من جرائم. فأمر الله أن تقاس المسافة بين الأرضين، فكان أقرب إلى أرض الصالحين، فقبضته ملائكة الرحمة.',
        'وردت القصة في صحيح مسلم، وفيها بيان عظيم لسعة رحمة الله، كما أنها لا تستهين بحقوق الضحايا ولا تجعل التوبة مجرد دعوى باللسان. فالرجل صدق في طلب التغيير، وبدأ بالفعل بمفارقة البيئة التي كانت تعينه على الشر، وسار إلى صحبة صالحة.',
        'وتعلّمنا القصة أن التوبة الصادقة تجمع بين الندم وترك الذنب والعزم على عدم العودة، وأن من وسائل الثبات الابتعاد عن أسباب المعصية ومجالسة أهل الخير. فلا يجوز للإنسان أن ييأس من رحمة الله، ولا أن يتخذ سعة الرحمة ذريعة للإصرار على الظلم.',
      ],
      lessons: [
        'لا يجوز اليأس من رحمة الله مهما عظم الذنب',
        'العلم النافع يفتح للناس أبواب التوبة ولا يغلقها بغير علم',
        'من صدق في التغيير بدأ بترك بيئة المعصية وأسبابها',
        'صحبة الصالحين تعين على الثبات والاستقامة',
        'التوبة لا تعني الاستهانة بحقوق الناس أو تبرير الاعتداء عليهم',
      ],
      practicalApplication: 'خطوات عملية للتوبة:\n\n• أوقف الذنب فوراً، واندَم عليه، واعزم بصدق ألا تعود إليه.\n• إذا تعلّق الذنب بحق إنسان، فاسعَ إلى رد الحق أو طلب المسامحة بالطريقة المناسبة.\n• ابتعد عن الأماكن والعلاقات والعادات التي تعيدك إلى الخطأ.\n• اختر صحبة صالحة تساعدك على الاستمرار، ولا تؤجل التوبة.',
      question: SeerahQuestion(
        question: 'بماذا نصح العالم الرجل الذي قتل مئة نفس؟',
        options: ['أن يعتزل الناس في مكانه', 'أن يعود إلى الراهب', 'أن يذهب إلى أرض فيها قوم صالحون', 'أن يؤجل التوبة'],
        correctAnswer: 2,
        explanation: 'نصحه العالم أن يترك أرض السوء ويتوجه إلى قرية فيها قوم صالحون ليعبد الله معهم، فبدأ الرجل بالفعل في طريق التغيير.',
      ),
      relatedStories: ['كعب بن مالك: خمسون ليلة من الصدق', 'رحمة الله الواسعة'],
    ),

    SeerahStory(
      id: 21,
      title: 'البكاؤون في غزوة تبوك',
      subtitle: 'حزنوا لأنهم لم يجدوا ما يحملهم إلى الخير',
      category: 'المواقف الإيمانية',
      location: 'المدينة المنورة',
      readingMinutes: 4,
      emoji: '😢',
      storyParagraphs: [
        'في السنة التاسعة للهجرة، استعد النبي ﷺ والمسلمون للخروج إلى غزوة تبوك، وكانت الرحلة بعيدة والظروف شاقة.',
        'جاء أناس من فقراء المسلمين إلى رسول الله ﷺ، يطلبون أن يوفر لهم ما يركبونه حتى يخرجوا مع الجيش.',
        'لم يكن عند النبي ﷺ ما يحملهم عليه، فأخبرهم أنه لا يجد ما يحملهم عليه.',
        'رجعوا من عنده وعيونهم تفيض بالدمع، لا لأنهم فقدوا متاعاً من الدنيا، بل حزناً لأنهم لم يجدوا وسيلة يشاركون بها في هذا العمل.',
        'ذكر القرآن موقفهم في سورة التوبة، فقال تعالى: {وَلَا عَلَى الَّذِينَ إِذَا مَا أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَا أَجِدُ مَا أَحْمِلُكُمْ عَلَيْهِ تَوَلَّوا وَّأَعْيُنُهُمْ تَفِيضُ مِنَ الدَّمْعِ حَزَنًا أَلَّا يَجِدُوا مَا يُنفِقُونَ} [التوبة: 92].',
        'اشتهر هؤلاء في كتب السيرة باسم «البكّائين»، وقيل إنهم سبعة، لكن أسماءهم وعددهم وردت فيها أقوال مختلفة؛ لذلك لا نجزم بتفصيل لم يثبت.',
        'والآية لا تمدح مجرد البكاء، بل تكشف صدق رغبتهم وعذرهم؛ فقد بذلوا ما يستطيعون، ولم يكن في وسعهم ما يجهزهم للخروج.',
      ],
      lessons: [
        'صدق النية يظهر في الحرص على الخير عند القدرة والعجز',
        'من عجز عن العمل الصالح لعذر صادق لا يُلام على عجزه',
        'لا تحتقر العمل القليل الذي تستطيع تقديمه',
        'الله يعلم صدق القلوب وما تخفيه من رغبات',
      ],
      practicalApplication: 'جرّب اليوم أن تحوّل حبك للخير إلى عمل ممكن:\n\n• إن عجزت عن عمل كبير، فابحث عن باب صغير تستطيع القيام به.\n• لا تحكم على الناس من ظاهر ظروفهم؛ فقد يكون لهم عذر لا تعرفه.\n• اسأل نفسك: ما العمل النافع الذي أستطيع فعله بإمكانياتي الحالية؟',
      question: SeerahQuestion(
        question: 'لماذا تولّى البكّاؤون وعيونهم تفيض من الدمع؟',
        options: [
          'خوفاً من السفر',
          'حزناً لأنهم لم يجدوا ما يحملهم ويجهزهم للخروج',
          'غضباً من المسلمين',
          'لأنهم لم يريدوا الخروج'
        ],
        correctAnswer: 1,
        explanation: 'ذكر القرآن أنهم حزنوا لأنهم لم يجدوا ما ينفقون، ولم تتوفر لهم وسيلة يحملهم بها النبي ﷺ.',
      ),
      relatedStories: ['غزوة تبوك', 'الإخلاص والنية'],
    ),

    // القصة 22 - قصة أصحاب الأخدود
    SeerahStory(
      id: 22,
      title: 'الغلام والراهب والملك',
      subtitle: 'ثبات الإيمان في قصة أصحاب الأخدود',
      category: 'قصص القرآن',
      location: 'لم يحدد الحديث موضع القصة',
      readingMinutes: 6,
      emoji: '🔥',
      storyParagraphs: [
        'روى النبي ﷺ قصة ملك كان له ساحر، فلما كبر الساحر طلب من الملك أن يرسل إليه غلاماً يعلمه السحر.',
        'كان الغلام يمر في طريقه براهب، فيجلس إليه ويسمع منه. فوجد في كلام الراهب ما يوافق الحق، وبدأ يتعلم منه التوحيد.',
        'وفي يوم اعترضت دابة عظيمة طريق الناس، فأخذ الغلام حجراً ودعا الله أن يبين له أي الطريقين أحب إليه، فرماها فقتلها ومر الناس. فعلم أن أمر الراهب حق.',
        'صار الغلام يدعو الله، فكان الله يجري على يديه شفاء بعض المرضى، وكان يؤكد للناس أنه لا يشفي أحداً من عند نفسه، وإنما الله هو الشافي.',
        'آمن جليس للملك كان قد فقد بصره، فشفاه الله بدعاء الغلام. فلما علم الملك بإيمانه غضب، وبدأ يعذب المؤمنين ليتركوا دينهم.',
        'ثبت الراهب وجليس الملك والغلام على الإيمان، فقتل الملك الراهب وجليسَه، وحاول التخلص من الغلام مرات فلم يقدر الله له ذلك.',
        'أخبر الغلام الملك أنه لن يستطيع قتله حتى يجمع الناس ويقول: «باسم الله رب الغلام»، ثم يرميه بسهم من كنانته. فعل الملك ذلك أمام الناس، فمات الغلام، وقال الناس: «آمنا برب الغلام».',
        'عندها أمر الملك بحفر أخاديد وإشعال النار فيها، وألقى المؤمنين فيها إن لم يرجعوا عن دينهم. وثبتوا على إيمانهم، وورد في الحديث ذكر امرأة معها طفلها شجّعها طفلها على الثبات.',
        'هذه القصة ثابتة في صحيح مسلم من حديث صهيب رضي الله عنه، وهي التي تُعرف بقصة أصحاب الأخدود، وفيها عبرة عظيمة في الثبات على التوحيد.',
      ],
      lessons: [
        'الهداية من الله، وعلى الإنسان أن يطلب الحق ويتبعه',
        'لا تنسب النفع والشفاء استقلالاً إلى مخلوق؛ فالله هو الشافي',
        'الثبات على الحق يحتاج إلى علم ويقين وصبر',
        'قد يكون موقف الصادق سبباً في هداية أناس كثيرين',
      ],
      practicalApplication: 'في حياتك:\n\n• تعلّم دينك من مصادر موثوقة وأهل علم معروفين.\n• لا تجعل رضا الناس مقدماً على طاعة الله.\n• إذا تعرضت لضغط بسبب تمسكك بالحق، فاطلب العون من الله وخذ بالأسباب المشروعة.\n• تذكر أن الدعوة تكون بالحكمة والرحمة، لا بالتعدي على أحد.',
      question: SeerahQuestion(
        question: 'ماذا قال الناس بعد مقتل الغلام؟',
        options: [
          'آمنا برب الغلام',
          'آمنا بالملك',
          'تركوا المدينة',
          'طلبوا من الساحر العودة'
        ],
        correctAnswer: 0,
        explanation: 'لما قتل الملك الغلام بالطريقة التي دلّه عليها، أعلن الناس إيمانهم برب الغلام، لا بالملك.',
      ),
      relatedStories: ['أصحاب الأخدود', 'الثبات على الإيمان'],
    ),

    // القصة 23 - قصة يونس عليه السلام
    SeerahStory(
      id: 23,
      title: 'يونس عليه السلام ودعاء الكرب',
      subtitle: 'التسبيح والاعتراف بالخطأ والرجوع إلى الله',
      category: 'قصص الأنبياء',
