      readingMinutes: 5,
      emoji: '🐋',
      storyParagraphs: [
        'أرسل الله يونس عليه السلام إلى قومه يدعوهم إلى توحيد الله، فخرج مغاضباً قبل أن يأذن الله له بالانصراف، فكان ذلك موضع عتابه.',
        'ركب سفينة، فلما اضطربت بهم وخافوا الغرق اقترعوا ليخففوا الحمل، فوقعت القرعة على يونس عليه السلام، فأُلقي في البحر.',
        'فابتلعه الحوت بأمر الله، فصار في ظلمات البحر وبطن الحوت والليل، ولم يكن له ملجأ إلا الله سبحانه.',
        'نادى ربه بهذا الدعاء العظيم: {لَا إِلَهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ} [الأنبياء: 87].',
        'استجاب الله له ونجّاه من الغم، قال تعالى: {فَاسْتَجَبْنَا لَهُ وَنَجَّيْنَاهُ مِنَ الْغَمِّ وَكَذَٰلِكَ نُنجِي الْمُؤْمِنِينَ} [الأنبياء: 88].',
        'قذف الحوت يونس إلى الساحل، وكان مريضاً ضعيفاً، فأنبت الله عليه شجرة من يقطين تظلله وتعينه.',
        'ثم عاد إلى قومه، وكانوا قد آمنوا، فانتفعوا بإيمانهم ومُتّعوا إلى حين، كما أخبر القرآن في سورة الصافات.',
        'تعلّمنا القصة أن العبد مهما ضاقت به الأسباب لا يقطع رجاءه من الله، وأن التوبة والرجوع إليه من أعظم أبواب النجاة.',
      ],
      lessons: [
        'لا يتعجل الداعية أو المصلح في ترك واجبه',
        'التوحيد وتنزيه الله والاعتراف بالتقصير من معاني دعاء يونس',
        'الفرج بيد الله، وقد يأتي من حيث لا يحتسب الإنسان',
        'رحمة الله واسعة، وهو يقبل رجوع عباده إليه',
      ],
      practicalApplication: 'عند الشدة:\n\n• أكثر من دعاء يونس عليه السلام مع فهم معناه.\n• راجع تصرفاتك واعترف بخطئك دون تبرير.\n• لا تيأس من رحمة الله، واستمر في الأخذ بالأسباب.\n• إذا كنت مسؤولاً عن عمل أو دعوة، فلا تتعجل تركه بسبب صعوبة الطريق.',
      question: SeerahQuestion(
        question: 'ما الدعاء الذي دعا به يونس عليه السلام في الظلمات؟',
        options: [
          'رب اشرح لي صدري',
          'لا إله إلا أنت سبحانك إني كنت من الظالمين',
          'رب زدني علماً',
          'حسبي الله ونعم الوكيل'
        ],
        correctAnswer: 1,
        explanation: 'هذا هو الدعاء الذي ذكره الله في سورة الأنبياء، وأخبر أنه استجاب ليونس ونجّاه من الغم.',
      ),
      relatedStories: ['قصة أيوب عليه السلام', 'التوبة والاستغفار'],
    ),


