        'وفي صحيح البخاري أن النبي ﷺ قال لبلال إنه سمع دف نعليه في الجنة، لما أخبره بلال بعمل كان يرجو به الخير، وهو أنه ما تطهر طهوراً في ساعة من ليل أو نهار إلا صلى بذلك الطهور ما كتب له.',
        'لم تكن منزلة بلال بسبب لون أو نسب أو مال، بل بإيمانه وصدقه وعبادته، فصار مثالاً على أن الكرامة عند الله بالتقوى.',
        'أما تفاصيل التعذيب الدقيقة المتداولة في بعض القصص، فتُذكر في كتب السيرة بدرجات متفاوتة، فلا ينبغي عرض كل جزئية منها على أنها حديث صحيح.',
      ],
      lessons: [
