        'مر بهم رسول الله ﷺ وهم يعذبون، فكان يواسيهم ويقول: «صبراً آل ياسر، فإن موعدكم الجنة»؛ وهي كلمة تذكرها كتب السيرة في سياق تعذيبهم.',
        'ثبتت سمية رضي الله عنها على إيمانها، وقُتلت بسبب ذلك، فاشتهرت في كتب السيرة بأنها أول شهيدة في الإسلام.',
        'أما تفاصيل كيفية قتلها، فتُروى في كتب السيرة بألفاظ وتفاصيل ليست كلها ثابتة بإسناد صحيح؛ لذلك نكتفي بأصل استشهادها وثباتها ولا نجزم بالتفاصيل غير المحققة.',
        'كانت قصتها شاهداً على أن الإيمان لا يرتبط بالقوة أو المكانة الاجتماعية، وأن المرأة المسلمة كان لها حضور مبكر في تحمل أعباء الدعوة.',
