        'مواساة المبتلى وتثبيته من أخلاق المسلم',
        'لا بد من التثبت في نقل تفاصيل السيرة والروايات',
      ],
      practicalApplication: 'تأمل في معنى الثبات:\n\n• تمسك بدينك مع حسن الخلق والرفق بالناس.\n• لا تسخر من شخص بسبب ضعفه أو فقره.\n• ساند من يتعرض للظلم، ولا تتركه وحيداً.\n• انقل القصص الدينية بأمانة، ولا تضف إليها تفاصيل غير ثابتة.',
      question: SeerahQuestion(
        question: 'بماذا اشتهرت سمية بنت خياط رضي الله عنها؟',
        options: [
          'أول مؤذنة في الإسلام',
