        correctAnswer: 1,
        explanation: 'اشتهرت سمية رضي الله عنها في كتب السيرة بأنها أول شهيدة في الإسلام، بعد ثباتها على دينها.',
      ),
      relatedStories: ['بلال بن رباح', 'عمار بن ياسر'],
    ),
