        'اتجه النبي ﷺ وأبو بكر إلى غار ثور، ومكثا فيه مدة، بينما كان المشركون يبحثون عنهما في كل اتجاه.',
        'وصل بعض المطاردين إلى موضع قريب من الغار، فخاف أبو بكر على رسول الله ﷺ، فقال له النبي ﷺ: «لا تحزن إن الله معنا».',
        'خلّد القرآن هذا الموقف في قوله تعالى: {إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ اللَّهُ إِذْ أَخْرَجَهُ الَّذِينَ كَفَرُوا ثَانِيَ اثْنَيْنِ إِذْ هُمَا فِي الْغَارِ إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا} [التوبة: 40].',
        'كان أبو بكر صاحب النبي ﷺ في هذه الرحلة، وقد ظهر في الموقف معنى الصحبة والوفاء، مع الأخذ بالأسباب والتخطيط للهجرة.',
        'أما القصة المشهورة عن دخول أبي بكر الغار قبله وسد الثقوب ثم تعرضه للدغ حية، فقد ذكرها بعض أهل السير، لكن أهل العلم حكموا بضعف سندها؛ فلا نقدمها كأنها واقعة ثابتة.',
        'وكذلك فإن حفظ الله لنبيه لم يكن معناه ترك الأسباب، فقد أعد النبي ﷺ للرحلة، واستعان بدليل للطريق، واتخذ وسائل الحيطة.',
