        'لا تجعل الخوف يقطع رجاءك في معية الله ونصره',
        'التثبت من الروايات جزء من الأمانة في نقل السيرة',
      ],
      practicalApplication: 'عندما تواجه أمراً صعباً:\n\n• خطط وخذ بالأسباب المتاحة.\n• استعن بالله ولا تتعلق بالأسباب وحدها.\n• كن وفياً لأصحابك وقت الشدة.\n• اقرأ الآية 40 من سورة التوبة وتأمل معانيها.',
      question: SeerahQuestion(
