        ],
        correctAnswer: 0,
        explanation: 'قال تعالى: {لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا}، وهي العبارة التي واسى بها النبي ﷺ صاحبه أبا بكر.',
      ),
      relatedStories: ['الهجرة النبوية', 'فضل أبي بكر الصديق'],
    ),

