      title: 'الأخوة التي صنعت مجتمعاً',
      subtitle: 'سعد بن الربيع وعبد الرحمن بن عوف نموذجاً للإيثار والعمل',
      category: 'المجتمع الإسلامي',
      location: 'المدينة المنورة',
      readingMinutes: 6,
      emoji: '🤝',
      storyParagraphs: [
        'بعد هجرة النبي ﷺ وأصحابه إلى المدينة، وجد المهاجرون أنفسهم بعيدين عن بيوتهم وأموالهم التي تركوها في مكة. وكانوا بحاجة إلى مجتمع يستقبلهم ويعينهم على بداية حياة جديدة، فعمل النبي ﷺ على تقوية الروابط بين المسلمين، ومن ذلك المؤاخاة بين المهاجرين والأنصار.',
        'ومن أشهر أمثلة هذه المؤاخاة ما رواه البخاري عن عبد الرحمن بن عوف رضي الله عنه: آخى النبي ﷺ بينه وبين سعد بن الربيع الأنصاري رضي الله عنه. وكان سعد من أهل السعة، فعرض على عبد الرحمن أن يقاسمه ماله، وذكر له أنه يملك زوجتين، وعرض أن يطلق إحداهما حتى يتزوجها عبد الرحمن بعد انتهاء عدتها إن أراد.',
        'كان عرض سعد مثالاً عظيماً على الإيثار، لكنه لم يكن ضغطاً على أخيه ولا منّة عليه؛ بل عرض مساعدة صادقة في وقت الحاجة. فأجابه عبد الرحمن بن عوف بدعاء جميل: «بارك الله لك في أهلك ومالك»، ثم قال: «أين سوقكم؟». فدلوه على سوق بني قينقاع.',
        'ذهب عبد الرحمن إلى السوق وبدأ يتاجر بما تيسر له. وتذكر الرواية أنه رجع ومعه شيء من الأقط والسمن، ثم واصل العمل حتى تزوج. ولما رأى النبي ﷺ عليه أثر طيب الزواج سأله، فذكر أنه تزوج امرأة من الأنصار، فسأله عن الصداق، وأرشده إلى إقامة وليمة ولو بشاة.',
        'تكشف القصة عن صورتين متكاملتين من الخير: سعد يعرض العون بسخاء، وعبد الرحمن يقبل المعروف بالدعاء والشكر، ثم يسعى إلى الكسب الحلال ولا يجعل المساعدة بديلاً عن العمل. ولم تكن الأخوة شعاراً يقال، بل مواقف عملية تحفظ كرامة الإنسان وتبني مجتمعاً متراحماً.',
        'والرواية الصحيحة تثبت قصة سعد وعبد الرحمن بهذا المعنى، أما العبارات المطولة المتداولة على ألسنة جميع الأنصار والمهاجرين في هذا الموقف فلا حاجة إلى نسبتها إليهم دون تثبت.',
      ],
      lessons: [
        'الإيثار الحقيقي أن تعين المحتاج بكرامة ومن غير منّة.',
        'شكر المعروف يكون بالدعاء لصاحبه وحفظ فضله.',
        'طلب الرزق الحلال والسعي في العمل من أسباب العفة والاستقلال.',
        'المجتمع القوي يجمع بين التكافل وإتاحة الفرصة للإنسان ليعتمد على نفسه.',
        'المؤاخاة ليست كلمات عاطفية فقط؛ بل مسؤولية ومساندة عند الحاجة.',
      ],
      practicalApplication: 'طبّق معنى المؤاخاة في حياتك:\n\n• ساعد من يمر بضائقة بما تستطيع، من غير إحراج أو تذكير بالفضل.\n• إذا تلقيت مساعدة، فاشكر صاحبها وادع له، وابذل جهدك لتحسين وضعك.\n• دلّ من يبحث عن عمل على فرصة نافعة إن استطعت.\n• لا تجعل المال سبباً للتكبر، ولا تجعل الحاجة سبباً لليأس.\n\n**تأمل:** كيف تستطيع أن تجمع هذا الأسبوع بين مساعدة شخص محتاج واتخاذ خطوة عملية للاعتماد على نفسك؟',
      question: SeerahQuestion(
        question: 'ماذا طلب عبد الرحمن بن عوف من سعد بن الربيع بعد عرضه المساعدة؟',
        options: [
          'أن يعطيه نصف ماله',
          'أن يدله على السوق',
          'أن يختار له زوجة',
          'أن يسافر معه إلى مكة'
        ],
        correctAnswer: 1,
        explanation: 'شكر عبد الرحمن سعداً ودعا له بالبركة، ثم طلب أن يدله على السوق ليعمل ويتكسب.',
      ),
      relatedStories: ['الهجرة النبوية', 'بناء المسجد النبوي', 'عبد الرحمن بن عوف'],
    ),

    // القصة 32 — أبو هريرة وحفظ الحديث | المصدر: صحيح البخاري، حديث 119 و3648؛ وصحيح مسلم، فضائل الصحابة.
    SeerahStory(
      id: 32,
      title: 'أبو هريرة وأمانة حفظ العلم',
      subtitle: 'كيف جعل ملازمة النبي ﷺ طريقاً للتعلم والرواية',
      category: 'الصحابة وطلب العلم',
      location: 'المدينة المنورة',
      readingMinutes: 6,
      emoji: '📚',
      storyParagraphs: [
        'كان أبو هريرة رضي الله عنه من أكثر الصحابة ملازمة للنبي ﷺ بعد إسلامه، واشتهر بحفظ الحديث وروايته. وقد قدم المدينة وأسلم عام خيبر في السنة السابعة للهجرة على المشهور، ولازم رسول الله ﷺ، وكان من أهل الصفة الذين أقاموا في المسجد النبوي واحتاجوا إلى الطعام والمعونة.',
        'شرح أبو هريرة سبب كثرة روايته، فقال إن إخوانه من المهاجرين كانت تشغلهم التجارة في الأسواق، وإن إخوانه من الأنصار كانت تشغلهم أعمال أموالهم، أما هو فكان يلزم رسول الله ﷺ، ويحضر ما لا يحضره كثير من الناس. وهذا يبين أن اختلاف أحوال الصحابة وأعمالهم كان سبباً في تنوع ما حفظوه ونقلوه.',
        'ومن المواقف التي رواها أبو هريرة أنه قال للنبي ﷺ إنه يسمع منه أحاديث كثيرة ثم ينساها. فقال له رسول الله ﷺ: «ابسط رداءك». فبسطه، ثم غرف النبي ﷺ بيده فيه، وقال له أن يضمه، ففعل. ويذكر أبو هريرة أنه بعد ذلك لم ينس شيئاً مما سمعه في هذا السياق. وهذه كرامة أكرم الله بها أبا هريرة، كما وردت في صحيح البخاري.',
        'لم يكن حفظ أبي هريرة مجرد موهبة شخصية؛ فقد اجتمع له الحرص على التعلم، وكثرة الملازمة، والدعاء النبوي، ثم تحمل مسؤولية تبليغ ما سمعه. وقد صار من أكثر الصحابة رواية للحديث، مع التنبيه إلى أن الأعداد الإجمالية للأحاديث تختلف باختلاف طرق العد والتكرار في كتب الحديث.',
        'وتعلمنا سيرته أن العلم يحتاج إلى صحبة أهل العلم، والانتباه، والمراجعة، والصبر. كما تعلمنا أن الفقر أو قلة الإمكانات لا تمنع الإنسان من تحصيل العلم إذا صدقت رغبته وبذل أسبابه.',
      ],
      lessons: [
        'ملازمة المعلم والحرص على مجالسه من أعظم أسباب التعلم.',
        'على طالب العلم أن يسأل بأدب عندما يجد صعوبة في الحفظ.',
        'الحفظ نعمة تستحق الشكر، ويجب أن يصحبه فهم وعمل.',
        'نقل العلم أمانة، فلا ينسب إلى النبي ﷺ إلا ما ثبت.',
        'اختلاف ظروف الناس قد يفتح لكل واحد منهم باباً مختلفاً لخدمة العلم.',
      ],
      practicalApplication: 'اجعل لك خطة صغيرة لطلب العلم:\n\n• اختر درساً موثوقاً أو باباً من كتاب نافع.\n• دوّن الفوائد الأساسية بكلماتك.\n• راجع ما تعلمته في اليوم نفسه ثم في نهاية الأسبوع.\n• اسأل أهل العلم عما يشكل عليك، ولا تنشر حديثاً قبل التحقق من صحته.\n\n**تأمل:** ما المعلومة النافعة التي تستطيع أن تتعلمها وتحفظها وتعمل بها هذا الأسبوع؟',
      question: SeerahQuestion(
        question: 'ماذا طلب النبي ﷺ من أبي هريرة عندما شكا كثرة النسيان؟',
        options: [
          'أن يكتب كل حديث فوراً',
          'أن يبسط رداءه ثم يضمه',
          'أن يترك مجالس العلم',
          'أن يسافر لطلب العلم'
        ],
        correctAnswer: 1,
        explanation: 'في الحديث الصحيح أمره النبي ﷺ أن يبسط رداءه، ثم غرف فيه بيده وأمره أن يضمه.',
      ),
      relatedStories: ['أهل الصفة', 'المؤاخاة بين المهاجرين والأنصار'],
    ),

    // القصة 33 — النملة والنبي من الأنبياء السابقين | المصدر: صحيح البخاري 3019؛ صحيح مسلم 2241.
    SeerahStory(
      id: 33,
      title: 'قرية النمل والرحمة بالمخلوقات',
      subtitle: 'قصة نبي من الأنبياء السابقين يرويها النبي ﷺ',
      category: 'الرحمة بالحيوان',
      location: 'من أخبار الأمم السابقة',
      readingMinutes: 5,
      emoji: '🐜',
      storyParagraphs: [
        'روى النبي ﷺ لأصحابه قصة نبي من الأنبياء السابقين، قرصته نملة، فأمر بإحراق قرية النمل. فأوحى الله إليه معاتباً: «أفي أن قرصتك نملة أهلكت أمة من الأمم تسبح؟». والحديث ثابت في صحيح البخاري وصحيح مسلم.',
        'من المهم أن نفهم القصة كما وردت: الذي وقع له الموقف نبي من الأنبياء السابقين، وليس النبي محمداً ﷺ، ولم يذكر الحديث اسم ذلك النبي ولا زمانه. لذلك لا يصح أن نحول القصة إلى حادثة وقعت مع رسول الله ﷺ أو نضيف إليها حواراً لم يرد في الرواية.',
        'وجه العتاب في الحديث أن الأذى صدر من نملة واحدة، لكن العقوبة امتدت إلى جماعة كاملة من المخلوقات التي تسبح الله. وفي ذلك تنبيه إلى خطورة التعميم في العقوبة، وإلى أن وجود أذى من فرد لا يبيح الاعتداء على غيره ممن لم يشارك فيه.',
        'كما يلفت الحديث النظر إلى أن المخلوقات التي قد لا نلتفت إليها لها حياة وتسبيح لا نحيط بحقيقتهما. والإنسان مأمور ألا يفسد أو يؤذي بلا حق، وأن يراعي ما يستطيع من الرحمة والرفق، مع دفع الضرر بقدر الحاجة ومن غير تجاوز.',
        'وتنسجم هذه المعاني مع هدي الإسلام في الرفق بالحيوان، والنهي عن العبث به أو تعذيبه. فالرحمة ليست محصورة في التعامل مع البشر، بل تشمل المخلوقات كلها، مع مراعاة ما يحتاج إليه الإنسان من حماية نفسه وممتلكاته من الضرر.',
      ],
      lessons: [
        'لا يجوز أن تتجاوز العقوبة من أخطأ إلى من لم يشارك في الخطأ.',
        'المخلوقات كلها أمم لها شأنها، والله أعلم بحالها وتسبيحها.',
        'الرحمة والرفق من الأخلاق التي يربي عليها الإسلام.',
        'ينبغي التثبت من تفاصيل القصص وعدم نسبتها إلى غير أصحابها.',
        'دفع الضرر يكون بقدر الحاجة، لا بالإفساد والتعدي.',
      ],
      practicalApplication: 'اجعل الرفق عادة يومية:\n\n• لا تؤذِ حيواناً لمجرد العبث أو الغضب.\n• إذا وجدت حيواناً يحتاج إلى الماء أو الطعام، فأحسن إليه إن استطعت.\n• عالج المشكلات دون تعميم العقوبة على الأبرياء.\n• علّم الأطفال احترام المخلوقات وعدم إيذائها.\n\n**تأمل:** هل هناك موقف غضبت فيه من شخص فكدت تعمم غضبك على غيره؟ كيف تتصرف بعدل في المرة القادمة؟',
      question: SeerahQuestion(
        question: 'من الذي وقعت له قصة النملة كما وردت في الحديث؟',
        options: [
          'النبي محمد ﷺ',
          'أحد الصحابة',
          'نبي من الأنبياء السابقين',
          'أحد ملوك قريش'
        ],
        correctAnswer: 2,
        explanation: 'نص الحديث يقول إن نملة قرصت نبياً من الأنبياء، ولم يسمه؛ فهي ليست قصة وقعت للنبي محمد ﷺ.',
      ),
      relatedStories: ['الرحمة بالحيوان', 'المرأة التي سقت الكلب'],
    ),

    // القصة 34 — المرأة التي سقت الكلب | المصدر: صحيح البخاري 3321؛ صحيح مسلم 2245، وأحاديث في أجر الإحسان إلى الحيوان.
    SeerahStory(
      id: 34,
      title: 'رحمة صغيرة وأجر عظيم',
      subtitle: 'امرأة سقت كلباً فغفر الله لها',
