      readingMinutes: 5,
      emoji: '🐕',
      storyParagraphs: [
        'أخبر النبي ﷺ عن امرأة بغي من بني إسرائيل مرت بكلب عند بئر، وكان الكلب يلهث من شدة العطش حتى أوشك أن يهلك. فرأت حاجته ورق قلبها له، مع أن حالها لم يكن مما يتوقع الناس معه عملاً عظيماً.',
        'نزعت خفها، وربطته بخمارها، ثم استقت من البئر وسقت الكلب. فكان هذا العمل سبباً لمغفرة الله لها، كما ورد في صحيح البخاري. وفي روايات صحيحة أخرى ورد أصل القصة بلفظ رجل، والمقصود أن الله رحم صاحب الإحسان إلى الحيوان وغفر له.',
        'تعجب الصحابة من عظم الأجر، فسألوا النبي ﷺ: أإن لنا في البهائم أجراً؟ فأخبرهم أن الإحسان إلى كل كائن حي فيه أجر. وفي بعض ألفاظ الحديث: «في كل كبد رطبة أجر». وهذا يفتح باباً واسعاً للأعمال الصالحة التي قد يراها الإنسان صغيرة، لكنها عظيمة عند الله إذا صدقت فيها النية.',
        'لا تعني القصة أن عملاً واحداً يجعل الإنسان يستغني عن التوبة والفرائض، ولا أنها تبيح الإصرار على المعصية؛ وإنما تدل على سعة رحمة الله، وعلى أن معروفاً صادقاً قد يكون سبباً لمغفرة عظيمة. والله سبحانه يقبل التوبة ويضاعف الأجر لمن يشاء.',
        'والقصة تربي المسلم على ألا يحتقر عملاً صالحاً، وألا يحصر الرحمة في من يعرفهم أو يشبهونه. فقد يكون المحتاج إلى الإحسان إنساناً ضعيفاً أو حيواناً لا يستطيع أن يطلب المساعدة بلسانه.',
      ],
      lessons: [
        'الرحمة بالحيوان عمل صالح يؤجر عليه المسلم.',
        'لا تحتقر معروفاً؛ فقد يكون سبباً لمغفرة الله.',
        'رحمة الله واسعة، وباب التوبة مفتوح لمن رجع إليه.',
        'الإحسان الحقيقي يظهر عند رؤية حاجة مخلوق ضعيف.',
        'النية الصادقة ترفع قيمة الأعمال الصغيرة.',
      ],
      practicalApplication: 'ابحث عن فرصة للرحمة:\n\n• ضع ماءً نظيفاً للطيور أو الحيوانات في مكان مناسب وآمن.\n• لا تعذب حيواناً ولا تحبسه دون طعام أو رعاية.\n• ساعد إنساناً محتاجاً ولو بمساعدة بسيطة.\n• إذا أخطأت، فبادر بالتوبة ولا تيأس من رحمة الله.\n\n**تأمل:** ما المعروف الصغير الذي تستطيع فعله اليوم ولا يحتاج منك إلا دقائق؟',
      question: SeerahQuestion(
        question: 'ما العمل الذي كان سبباً في مغفرة الله للمرأة في الحديث؟',
        options: [
