          'سقي كلب شديد العطش',
          'بناء بئر كبيرة',
          'إطعام أهل قرية'
        ],
        correctAnswer: 1,
        explanation: 'سقت المرأة كلباً كاد يهلك من العطش، فغفر الله لها بسبب هذا الإحسان.',
      ),
      relatedStories: ['الرحمة بالحيوان', 'قصة النملة والنبي السابق'],
    ),

    // القصة 35 — خدمة النبي ﷺ لأهله | المصدر: صحيح البخاري 676 و5363؛ الأدب المفرد 539 مع اختلاف طرقه.
    SeerahStory(
      id: 35,
      title: 'التواضع يبدأ من البيت',
      subtitle: 'النبي ﷺ يعين أهله ويخدمهم',
      category: 'أخلاق النبي ﷺ',
      location: 'المدينة المنورة',
      readingMinutes: 5,
      emoji: '🏡',
      storyParagraphs: [
        'قد يظن بعض الناس أن عظمة الإنسان تظهر في أن يخدمه الجميع، لكن بيت النبي ﷺ يقدم صورة مختلفة تماماً. فقد سُئلت عائشة رضي الله عنها: ما كان النبي ﷺ يصنع في بيته؟ فقالت: «كان يكون في مهنة أهله»؛ أي في خدمة أهله، فإذا حضرت الصلاة خرج إلى الصلاة. وهذا الحديث في صحيح البخاري.',
        'تصف لنا أم المؤمنين بهذا الجواب جانباً من الحياة اليومية للنبي ﷺ، بعيداً عن مشاهد القيادة العامة وتعليم الناس وإدارة شؤون الأمة. فقد كان يعين أهل بيته، ولا يرى أن مكانته تمنعه من المشاركة في أعمال المنزل.',
        'وتذكر روايات في كتب السنة أنه ﷺ كان يخصف نعله ويعمل ما يعمل الرجل في بيته، وجاء ذلك في الأدب المفرد وغيره. والمقصود أن خدمة الإنسان لنفسه وأهله ليست نقصاً في قدره، بل قد تكون من حسن العشرة والتواضع والرحمة.',
        'وكان النبي ﷺ إذا حضرت الصلاة لم تشغله أعمال البيت عنها، فجمع بين حسن المعاملة والقيام بحق الله. وهكذا نتعلم أن العبادة والأخلاق ليستا مجالين منفصلين؛ فالمسلم يعبد الله في صلاته، ويظهر أثر عبادته في رحمته وتعاونه داخل بيته.',
        'كما أن البيت هو المكان الذي تظهر فيه حقيقة الأخلاق؛ فقد يستطيع الإنسان أن يتجمل أمام الناس، لكن حسن العشرة والصبر والمشاركة اليومية تكشف صدق تواضعه. ومن هدي النبي ﷺ أن يكون المرء عوناً لأهله، لا عبئاً عليهم.',
      ],
      lessons: [
        'مساعدة الأهل من حسن الخلق والاقتداء بالنبي ﷺ.',
        'التواضع لا يتعارض مع المكانة أو المسؤولية.',
        'البيت أول مكان ينبغي أن تظهر فيه الرحمة وحسن المعاملة.',
        'القيام بحقوق الأسرة لا ينبغي أن يلهي عن الصلاة والواجبات.',
        'الأخلاق الحقيقية تظهر في التعامل اليومي لا في الكلام وحده.',
      ],
      practicalApplication: 'ابدأ من بيتك:\n\n• شارك في عمل منزلي دون انتظار طلب أو مقابل.\n• تحدث مع أهلك بلطف، خاصة وقت التعب والضغط.\n• لا تعتبر المساعدة إهانة أو انتقاصاً من مكانتك.\n• نظّم وقتك حتى تؤدي مسؤولياتك وتحافظ على الصلاة.\n\n**تأمل:** ما العمل الذي يمكنك أن تتولاه في بيتك بانتظام لتخفف عن أهلك؟',
      question: SeerahQuestion(
        question: 'كيف وصفت عائشة رضي الله عنها حال النبي ﷺ في بيته؟',
        options: [
          'كان يترك كل أعمال البيت لأهله',
          'كان يكون في مهنة أهله ويعينهم',
          'كان لا يدخل بيته إلا للنوم',
          'كان يمنع أهله من طلب المساعدة'
        ],
        correctAnswer: 1,
        explanation: 'قالت عائشة رضي الله عنها إنه كان في مهنة أهله، أي في خدمتهم، فإذا حضرت الصلاة خرج إليها.',
      ),
      relatedStories: ['أخلاق النبي ﷺ', 'الرحمة في حياة النبي ﷺ'],
    ),

    // القصة 36 — العدل في تطبيق الأحكام | المصدر: صحيح البخاري 3475 و6788؛ صحيح مسلم 1688.
    SeerahStory(
      id: 36,
      title: 'العدل لا يعرف المحاباة',
      subtitle: 'موقف النبي ﷺ من الشفاعة في حد من حدود الله',
      category: 'العدل والأمانة',
      location: 'المدينة المنورة',
      readingMinutes: 6,
      emoji: '⚖️',
      storyParagraphs: [
        'في عهد النبي ﷺ وقعت امرأة من بني مخزوم في السرقة، وكانت من بيت ذي مكانة في قريش. فاهتم بعض الناس بأمرها وخشوا أن تقام عليها العقوبة، فبحثوا عمن يستطيع أن يشفع لها عند رسول الله ﷺ.',
        'اختاروا أسامة بن زيد رضي الله عنهما، وكان محبوباً عند النبي ﷺ، فكلمه في شأنها. فأنكر النبي ﷺ أن تكون المحبة أو المكانة سبباً لتعطيل حكم شرعي، وقال له: «أتشفع في حد من حدود الله؟».',
        'ثم خطب النبي ﷺ في الناس، وبيّن أن الأمم السابقة ضلت حين كانت تترك صاحب المكانة إذا سرق، وتقيم العقوبة على الضعيف إذا سرق. وذكر أن العدل لا يصح أن يتغير بحسب النسب أو المال أو القرب من أصحاب السلطة.',
        'وقال ﷺ في خطبته: «وايم الله، لو أن فاطمة بنت محمد سرقت لقطعت يدها». والمقصود بيان أن أحكام الله لا تُعطّل لمجاملة أحد، لا أن أحداً فوق المحاسبة أو أن الناس يتولون تنفيذ العقوبات بأنفسهم؛ فالأحكام القضائية لها شروطها وإجراءاتها وسلطتها المختصة.',
        'كان هذا الموقف درساً عملياً في المساواة أمام الحق، وفي أن المحبة لا تعني المحاباة. فأسامة رضي الله عنه كان عزيزاً على النبي ﷺ، ومع ذلك لم يقبل أن تتحول منزلته إلى وسيلة لتعطيل العدل.',
      ],
      lessons: [
        'العدل واجب مع القريب والبعيد، والغني والفقير.',
        'لا يجوز أن تكون المكانة الاجتماعية سبباً للتمييز في الحقوق.',
        'المحبة الصادقة لا تعني الموافقة على الخطأ أو تبريره.',
        'الشفاعة لا تكون لإبطال حق أو تعطيل حكم شرعي ثابت.',
        'تنفيذ الأحكام من اختصاص الجهات القضائية والسلطات المخولة، لا الأفراد.',
      ],
      practicalApplication: 'تدرّب على العدل في المواقف اليومية:\n\n• لا تكِل بمكيالين بين أصدقائك وأقاربك.\n• إذا أخطأ شخص تحبه، فانصحه ولا تبرر خطأه.\n• أعطِ كل ذي حق حقه، حتى لو لم يكن قريباً منك.\n• لا تنشر اتهاماً ولا تحكم في قضية قبل التثبت وسماع الأطراف.\n\n**تأمل:** هل سبق أن دافعت عن شخص لمجرد أنك تحبه رغم معرفتك بخطئه؟ ما التصرف الأعدل؟',
      question: SeerahQuestion(
        question: 'ما المبدأ الذي أكده النبي ﷺ في قصة المرأة المخزومية؟',
        options: [
          'أن المكانة الاجتماعية تعفي من المحاسبة',
          'أن العدل يطبق دون محاباة أو تمييز',
          'أن الشفاعة تلغي كل حكم',
          'أن القريب أولى بالحق من غيره'
        ],
        correctAnswer: 1,
        explanation: 'أكد النبي ﷺ أن العدل لا يتغير بسبب النسب أو المكانة، وضرب مثالاً بابنته فاطمة رضي الله عنها.',
      ),
      relatedStories: ['العدل في الإسلام', 'أخلاق النبي ﷺ'],
    ),

    // القصة 37 — راية خيبر لعلي بن أبي طالب | المصدر: صحيح البخاري 3701 و4210؛ صحيح مسلم 2406.
SeerahStory(
  id: 37,
  title: 'راية خيبر',
  subtitle: 'فضل علي بن أبي طالب رضي الله عنه وأهمية الدعوة بالحكمة',
  category: 'الصحابة',
  location: 'خيبر',
  readingMinutes: 6,
  emoji: '🚩',
  storyParagraphs: [
    'في غزوة خيبر، أعلن النبي ﷺ أنه سيعطي الراية في اليوم التالي لرجل يحب الله ورسوله ويحبه الله ورسوله، ويكون الفتح على يديه. فبات الصحابة يتطلعون إلى معرفة من ينال هذا الفضل العظيم.',
    'فلما أصبحوا، سأل النبي ﷺ عن علي بن أبي طالب رضي الله عنه، فقيل له إنه يشتكي عينيه. فأرسل إليه، فأُتي به، فبصق النبي ﷺ في عينيه ودعا له، فبرأ حتى كأن لم يكن به وجع، ثم أعطاه الراية. وهذه التفاصيل ثابتة في صحيح البخاري وصحيح مسلم.',
    'لم تكن وصية النبي ﷺ لعلي أن يبدأ بالقتال دون بيان؛ بل قال له أن يتقدم برفق حتى ينزل بساحتهم، ثم يدعوهم إلى الإسلام ويخبرهم بما يجب عليهم من حق الله. وأكد له أن هداية رجل واحد خير من أن تكون له أنفس نفائس الدنيا.',
    'تكشف هذه الوصية أن المقصد ليس مجرد الغلبة، بل هداية الناس وإقامة الحق. كما تعلمنا أن الشجاعة لا تنفصل عن الحكمة، وأن القائد المسلم يجمع بين الثبات وحسن التوجيه والحرص على مصلحة الناس.',
    'ولا يصح أن نضيف إلى الرواية الصحيحة تفاصيل مشهورة لا تثبت فيها، مثل أن أبا بكر ثم عمر حملا الراية قبله ولم يفتح لهما، أو قصة اقتلاع باب الحصن وجعله جسراً؛ فحديث الراية الصحيح يثبت فضل علي وتسليم الراية له وشفاء عينيه والدعوة إلى الإسلام.',
  ],
  lessons: [
    'الفضل الحقيقي منحة من الله، وليس مجالاً للتنافس على السمعة.',
    'الدعوة إلى الحق تكون بالحكمة والرفق ووضوح المقصد.',
    'هداية إنسان واحد خير من متاع الدنيا النفيس.',
    'الشجاعة تحتاج إلى علم وتوجيه، لا إلى اندفاع غير محسوب.',
    'الأمانة العلمية تقتضي التمييز بين الحديث الصحيح والتفاصيل غير الثابتة.',
  ],
  practicalApplication: 'استفد من وصية النبي ﷺ:\n\n• إذا نصحت أحداً، فابدأ بالرفق والشرح الواضح.\n• لا تجعل الفوز في النقاش أهم من وصول الحق.\n• اطلب من الله العافية والتوفيق قبل مواجهة الصعوبات.\n• تحرّ الدقة قبل نقل القصص الدينية، ولا تضف إليها ما لم يثبت.\n\n**تأمل:** كيف تستطيع أن تدعو شخصاً إلى أمر نافع دون قسوة أو تعالٍ؟',
  question: SeerahQuestion(
    question: 'ما الوصية التي أكدها النبي ﷺ لعلي حين أعطاه الراية؟',
    options: [
      'أن يبدأ القتال فوراً دون كلام',
      'أن يدعو القوم إلى الإسلام ويبين لهم حق الله',
      'أن يعود إلى المدينة مباشرة',
      'أن يطلب منهم المال أولاً'
    ],
    correctAnswer: 1,
    explanation: 'أمره النبي ﷺ أن يتقدم برفق، ثم يدعوهم إلى الإسلام ويبين لهم ما يجب عليهم من حق الله.',
  ),
  relatedStories: ['غزوة خيبر', 'فضائل علي بن أبي طالب', 'الدعوة بالحكمة'],
),

// القصة 38 — معاذ بن جبل في اليمن | المصدر: صحيح البخاري 1395 و4347؛ صحيح مسلم 19.
SeerahStory(
  id: 38,
  title: 'معاذ بن جبل ومهمة التعليم',
  subtitle: 'رسول النبي ﷺ إلى اليمن',
  category: 'الصحابة وطلب العلم',
  location: 'المدينة المنورة واليمن',
  readingMinutes: 6,
  emoji: '📖',
  storyParagraphs: [
    'كان معاذ بن جبل رضي الله عنه من شباب الصحابة الذين عُرفوا بالعلم والفقه. واختاره النبي ﷺ ليبعثه إلى اليمن معلماً وداعياً، فكانت المهمة تحتاج إلى علم وصبر وحسن تعامل مع الناس.',
    'وقبل أن يرسله، أوصاه النبي ﷺ بأصول الدعوة وترتيب الأولويات. فقال له إنه سيأتي قوماً من أهل الكتاب، وأمره أن يبدأ دعوتهم بشهادة أن لا إله إلا الله وأن محمداً رسول الله. فإذا استجابوا، يبين لهم فرض الصلوات الخمس، ثم يبين لهم فرض الزكاة التي تؤخذ من أغنيائهم وترد على فقرائهم.',
    'وفي الوصية نفسها حذره النبي ﷺ من أخذ كرائم أموال الناس بغير حق، وأمره أن يتقي دعوة المظلوم؛ فليس بينها وبين الله حجاب. وهذا يبين أن الدعوة ليست كلمات تقال فقط، بل معها عدل في التعامل، وحفظ لأموال الناس، ومراعاة لأحوال الفقراء.',
    'وتظهر في هذه الوصية حكمة التعليم النبوي؛ إذ يبدأ الداعية بأصل الإيمان، ثم ينتقل إلى أعظم الفرائض، ويشرح للناس ما يلزمهم بالتدرج والوضوح. كما يظهر أن من يتولى شؤون الناس يجب أن يكون أميناً، فلا يستغل منصبه ولا يظلم أحداً.',
    'وتشتهر رواية الحوار الذي يسأل فيه النبي ﷺ معاذاً: «بم تقضي؟» فيجيب بالكتاب والسنة والاجتهاد، لكن أهل الحديث تكلموا في إسنادها، وضعفها عدد من المحققين؛ لذلك لم نعتمدها هنا على أنها حديث صحيح. واكتفينا بما ثبت في الصحيحين من بعث معاذ ووصية النبي ﷺ له.',
  ],
  lessons: [
    'العلم والدعوة مسؤولية تحتاج إلى إعداد وأمانة.',
    'ابدأ في التعليم بالأصول الكبرى ثم انتقل إلى التفاصيل.',
    'الرفق بالناس وحفظ أموالهم من أخلاق الداعية والمسؤول.',
    'حقوق الفقراء جزء أساسي من نظام التكافل في الإسلام.',
    'لا يجوز نسبة حديث إلى النبي ﷺ لمجرد شهرته إذا كان إسناده ضعيفاً.',
  ],
  practicalApplication: 'اجعل وصية معاذ منهجاً في التعامل:\n\n• إذا علمت غيرك، فابدأ بالأساسيات ولا تربكه بالتفاصيل دفعة واحدة.\n• كن أميناً في المال والعمل، ولا تستغل ثقة الناس.\n• أعطِ الفقير حقه، ولا تؤخر ما تستطيع من المساعدة.\n• إذا لم تعرف جواب سؤال، فقل لا أعلم وابحث عن مصدر موثوق.\n\n**تأمل:** ما المسؤولية التي اؤتمنت عليها، وكيف تستطيع أداءها بمزيد من العدل والأمانة؟',
  question: SeerahQuestion(
    question: 'بماذا أمر النبي ﷺ معاذاً أن يبدأ دعوته لأهل اليمن؟',
    options: [
      'بجمع الزكاة أولاً',
      'بدعوتهم إلى شهادة أن لا إله إلا الله وأن محمداً رسول الله',
      'بتعليمهم أحكام التجارة أولاً',
      'بإلزامهم بكل الأحكام دفعة واحدة'
    ],
    correctAnswer: 1,
    explanation: 'أمره النبي ﷺ أن يبدأ بدعوتهم إلى التوحيد والشهادة، ثم يبين لهم الصلاة والزكاة بعد ذلك.',
  ),
  relatedStories: ['معاذ بن جبل', 'الدعوة إلى الإسلام', 'الزكاة والتكافل'],
),

// القصة 39 — عبد الرحمن بن عوف | المصدر: صحيح البخاري 2048 و3780 و5155؛ صحيح مسلم 1427.
SeerahStory(
  id: 39,
  title: 'عبد الرحمن بن عوف: كسب وإنفاق',
  subtitle: 'من بداية متواضعة إلى سعة الرزق',
  category: 'الصحابة',
  location: 'المدينة المنورة',
  readingMinutes: 6,
  emoji: '💼',
  storyParagraphs: [
    'لما هاجر عبد الرحمن بن عوف رضي الله عنه إلى المدينة، آخى النبي ﷺ بينه وبين سعد بن الربيع الأنصاري. وكان سعد ذا مال، فعرض على عبد الرحمن أن يقاسمه ماله، لكن عبد الرحمن شكره ودعا له بالبركة، ثم طلب أن يدله على السوق.',
    'ذهب عبد الرحمن إلى سوق بني قينقاع وبدأ يتاجر. وتذكر الرواية أنه عاد بشيء من الأقط والسمن، ثم واصل الذهاب إلى السوق والعمل. وفي ذلك صورة من عفة النفس والاعتماد على الكسب الحلال، مع عدم إنكار فضل أخيه الأنصاري الذي عرض عليه المساعدة.',
    'ثم تزوج عبد الرحمن امرأة من الأنصار. ورأى النبي ﷺ عليه أثر الصفرة، فسأله عن ذلك، فأخبره أنه تزوج. فسأله عن الصداق، فقال إنه نواة من ذهب أو وزن نواة من ذهب، فأمره النبي ﷺ أن يقيم وليمة ولو بشاة. وهذا ثابت في صحيح البخاري وصحيح مسلم.',
    'وتذكر كتب الحديث والسيرة مواقف كثيرة من إنفاق عبد الرحمن بن عوف في وجوه الخير، وكان من كبار أغنياء الصحابة وأهل البذل. لكن ينبغي ألا ننسب إليه عبارات مشهورة مثل «ما نفعني مال قط ما نفعني مال عبد الرحمن» أو قصة دخوله الجنة حبواً على أنها أحاديث صحيحة؛ فهذه الألفاظ لا تثبت بإسناد صحيح يعتمد عليه.',
    'لم يكن المال في حياة عبد الرحمن غاية مستقلة، بل وسيلة للكسب الحلال والإنفاق. وتعلمنا قصته أن الغنى ليس مذموماً في ذاته، وإنما العبرة بمصدر المال وكيفية التصرف فيه، وأن المسلم يستطيع أن يكون ناجحاً في عمله وكريماً في عطائه في الوقت نفسه.',
  ],
  lessons: [
    'السعي في الرزق الحلال مع التوكل على الله من الأخلاق المحمودة.',
    'عفة النفس لا تعني رفض كل مساعدة، بل تعني ألا يتخذ الإنسان سؤال الناس عادة.',
    'شكر من أحسن إليك والدعاء له من الوفاء.',
    'المال نعمة ومسؤولية، ويكون خيراً حين ينفق في وجوهه المشروعة.',
    'ينبغي التثبت من الأحاديث والعبارات المشهورة قبل نسبتها إلى النبي ﷺ.',
  ],
  practicalApplication: 'وازن بين العمل والعطاء:\n\n• ابحث عن وسيلة كسب حلال تناسب قدراتك.\n• تعلم مهارة تساعدك على الاستقلال المالي.\n• اشكر من يساعدك ولا تنسَ فضله.\n• خصص جزءاً من مالك للصدقة ومساعدة المحتاجين بحسب استطاعتك.\n• لا تجعل المال مقياساً لقيمة الإنسان أو سبباً للتكبر.\n\n**تأمل:** كيف تستطيع أن تطور مصدر رزقك وتخصص في الوقت نفسه نصيباً ثابتاً للخير؟',
  question: SeerahQuestion(
    question: 'ماذا طلب عبد الرحمن بن عوف من سعد بن الربيع بعد المؤاخاة؟',
    options: [
      'أن يعطيه نصف ماله',
      'أن يدله على السوق',
      'أن يشتري له بيتاً',
      'أن يسافر معه'
    ],
    correctAnswer: 1,
    explanation: 'شكر عبد الرحمن سعداً ودعا له، ثم طلب أن يدله على السوق ليعمل ويتكسب.',
  ),
  relatedStories: ['المؤاخاة بين المهاجرين والأنصار', 'الإنفاق في سبيل الله'],
),

// القصة 40 — أويس القرني | المصدر: صحيح مسلم 2542، كتاب فضائل الصحابة، باب فضائل أويس القرني.
SeerahStory(
  id: 40,
  title: 'أويس القرني: منزلة الإخلاص وبر الوالدة',
  subtitle: 'تابعي صالح أخبر النبي ﷺ بفضله',
  category: 'التابعون',
  location: 'اليمن ثم الكوفة',
  readingMinutes: 6,
  emoji: '🌿',
  storyParagraphs: [
    'أويس بن عامر القرني رجل من أهل اليمن، لم يلق النبي ﷺ، ولذلك فهو من التابعين وليس من الصحابة. ومع ذلك أخبر النبي ﷺ أصحابه بفضله، وذكر أن من خير التابعين رجلاً يقال له أويس، له والدة، وكان به بياض، وأرشد من لقيه أن يطلب منه الاستغفار.',
    'وفي صحيح مسلم أن عمر بن الخطاب رضي الله عنه كان يسأل الوفود القادمة من اليمن عن أويس، حتى لقيه. فسأله عن اسمه ونسبه، وعن العلامة التي أخبر بها النبي ﷺ، وعن والدته، فوافقه أويس على ما سأله عنه.',
    'قال عمر لأويس إن النبي ﷺ أخبر بقدومه ووصف حاله، وأوصى بطلب استغفاره. فطلب منه عمر أن يستغفر له، فاستغفر أويس. ثم سأله عمر إن كان يكتب له إلى عامل الكوفة، فاختار أويس أن يكون في عامة الناس وألا يشتهر بين الناس.',
    'وتبين الرواية أن أويساً كان باراً بوالدته، وأن هذه الخصلة كانت من أبرز ما ذُكر في فضله. كما تبين أن الصلاح لا يشترط أن يكون صاحبه مشهوراً أو صاحب منصب؛ فقد يرفع الله عبداً بإخلاصه وبره وعبادته وإن لم يعرفه كثير من الناس.',
    'أما التفاصيل التي تذكر أنه استشهد في صفين أو تحدد تاريخ وفاته، ففيها اختلاف بين أهل الأخبار، ولا يثبت ذلك في الحديث الصحيح الذي وردت فيه فضائله؛ لذلك لا نجزم بها في هذه القصة.',
  ],
  lessons: [
    'بر الوالدين من أعظم أبواب الخير ورفعة المنزلة.',
    'قد يكون الإنسان عظيماً عند الله وإن لم يكن مشهوراً بين الناس.',
    'الفضل الحقيقي بالإيمان والعمل الصالح، لا بالمظهر أو المكانة.',
    'يجوز طلب الدعاء من المسلم الصالح الحي، مع تعلق القلب بالله وحده.',
    'ينبغي الوقوف عند ما ثبت، وعدم الجزم بتفاصيل تاريخية مختلف فيها.',
  ],
  practicalApplication: 'اقتدِ بمعاني قصة أويس:\n\n• اجعل لوالديك نصيباً ثابتاً من وقتك وخدمتك ودعائك.\n• لا تجعل طلب الشهرة هدفاً من أعمال الخير.\n• لا تحكم على الناس بمظاهرهم أو شهرتهم.\n• اطلب من الله الإخلاص والقبول، ولا تتعلق بالأشخاص.\n\n**تأمل:** ما العمل الذي تستطيع أن تفعله لوالديك اليوم دون أن تنتظر شكراً أو مدحاً؟',
  question: SeerahQuestion(
    question: 'ما أبرز صفة ذُكرت في فضل أويس القرني؟',
    options: [
      'كثرة ماله وتجارته',
      'بره بوالدته',
      'قيادته للجيوش',
      'كونه من كبار قريش'
    ],
    correctAnswer: 1,
    explanation: 'ذكر النبي ﷺ أن لأويس والدة، وأثنى على بره بها، وأرشد عمر ومن معه إلى طلب استغفاره.',
  ),
  relatedStories: ['بر الوالدين', 'فضل التابعين', 'الإخلاص في العمل'],
),

// القصة 41 — البراء بن مالك | المصدر: سنن الترمذي 3854، وحسنه الترمذي وصححه الألباني.
    SeerahStory(
      id: 41,
      title: 'البراء بن مالك: منزلة الإخلاص',
      subtitle: 'رجل لا يُلتفت إليه في أعين الناس، وله قدر عند الله',
      category: 'الصحابة',
      location: 'من أخبار الصحابة',
      readingMinutes: 6,
      emoji: '🤲',
      storyParagraphs: [
        'كان البراء بن مالك رضي الله عنه من أصحاب النبي ﷺ، وكان أخاً لأنس بن مالك رضي الله عنه. ولم تكن منزلته عند الله مرتبطة بمظهر أو مال أو جاه؛ فقد روى أنس أن النبي ﷺ قال: «كم من أشعث أغبر ذي طمرين لا يؤبه له، لو أقسم على الله لأبره، منهم البراء بن مالك». رواه الترمذي، وقال: حديث حسن غريب من هذا الوجه، وصححه الألباني.',
        'تلفت هذه الكلمة النبوية النظر إلى ميزان مختلف عن مقاييس الناس؛ فقد يرى الناس إنساناً بسيط الثياب قليل الشهرة، بينما يكون عند الله عظيم الإيمان والصدق. وذكر النبي ﷺ البراء في هذا السياق منقبة ظاهرة له، لا دعوة إلى ترك النظافة أو إهمال المظهر، بل تحذير من احتقار الناس بسبب فقرهم أو هيئتهم.',
        'ولا يتحدث هذا الحديث عن كثرة المال أو الشهرة أو المنصب، بل يلفت إلى أن العبد قد يكون خامل الذكر عند الناس، لكنه عظيم المنزلة عند الله بإيمانه وإخلاصه. وذكر البراء باسمه في الحديث منقبة ثابتة له، ويكفي ذلك لإبراز فضله دون الحاجة إلى إضافة أعداد أو مشاهد من أخبار المعارك لا يثبتها هذا النص.',
        'ومعنى أن الله يبر قسم عبده الصالح ليس أن الإنسان يملك أن يُلزم الله بما يريد، أو أن كل ما يتمناه يتحقق حتماً؛ فالله يفعل ما يشاء بحكمة. وإنما الحديث في فضل عبد بلغ من الصدق والإخلاص منزلة عظيمة، فيكرمه الله ويجيب دعاءه بما تقتضيه حكمته.',
        'إن منزلة البراء تعلمنا أن قيمة الإنسان ليست فيما يراه الناس من ثيابه أو شهرته، وإنما بما يعلمه الله من قلبه وعمله. كما تعلمنا أن الدعاء عبادة عظيمة، وأن الصالح لا يغتر بمدح الناس، بل يظل محتاجاً إلى رحمة الله وتوفيقه.',
      ],
      lessons: [
        'الميزان الحقيقي للتفاضل هو التقوى والعمل الصالح، لا المال ولا المظهر.',
        'لا يجوز احتقار إنسان لفقره أو بساطة ثيابه.',
        'الدعاء والتضرع إلى الله من أعظم أسباب الثبات والرجاء.',
        'الشجاعة المحمودة تقترن بالإخلاص وطلب مرضاة الله.',
        'ينبغي التثبت من الأخبار وعدم تحويل الروايات المشهورة إلى حقائق قطعية.',
      ],
      practicalApplication: 'طبّق المعاني دي في حياتك:\n\n• لا تحكم على الناس من ملابسهم أو دخلهم أو شهرتهم.\n• إذا احتجت إلى أمر، فابدأ بالدعاء مع بذل الأسباب المشروعة.\n• اجعل لك عملاً صالحاً خفياً لا يعرفه الناس.\n• إذا مدحك أحد، فتذكر أن العبرة بقبول العمل عند الله.\n\n**تأمل:** هل سبق أن قللت من شأن شخص بسبب مظهره؟ وكيف ستغيّر نظرتك بعد اليوم؟',
      question: SeerahQuestion(
        question: 'من الصحابي الذي ذكره النبي ﷺ في حديث «كم من أشعث أغبر...»؟',
        options: ['أبو هريرة', 'البراء بن مالك', 'عبد الله بن عمر', 'سعد بن أبي وقاص'],
        correctAnswer: 1,
        explanation: 'ذكر النبي ﷺ البراء بن مالك ضمن من تنطبق عليهم هذه المنقبة، كما ورد في سنن الترمذي حديث 3854.',
      ),
      relatedStories: ['أنس بن مالك رضي الله عنه', 'الإخلاص والتواضع'],
    ),

// القصة 42 — جليبيب رضي الله عنه | المصدر: صحيح مسلم 2472.
    SeerahStory(
      id: 42,
      title: 'جليبيب: عظيم القدر عند الله',
      subtitle: 'النبي ﷺ يتفقده بين الشهداء',
      category: 'الصحابة',
      location: 'المدينة المنورة',
      readingMinutes: 6,
      emoji: '🌿',
      storyParagraphs: [
        'كان جليبيب رضي الله عنه صحابياً من أصحاب النبي ﷺ. ولا يذكر حديث صحيح مسلم نسبه أو ماله أو مكانته الاجتماعية؛ لكنه يبرز بوضوح كيف كان النبي ﷺ يتفقده ويهتم بأمره. فالمعيار الذي يرفع الإنسان هو إيمانه وصدقه وعمله، لا ما يملكه من مال أو جاه.',
        'وفي غزوة من الغزوات، وبعد أن انتهى القتال، أخذ النبي ﷺ يسأل أصحابه: «هل تفقدون من أحد؟». فذكروا له أسماء بعض الرجال، ثم أعاد السؤال، حتى قالوا إنهم لا يفتقدون أحداً. فقال لهم: «لكني أفقد جليبيباً، فاطلبوه». انظر إلى هذا الوفاء النبوي؛ فالنبي ﷺ لم ينس رجلاً قد لا يلتفت إليه كثير من الناس.',
        'بحث الصحابة عنه بين القتلى، فوجدوه إلى جانب سبعة من المشركين قد قتلهم، ثم قُتل هو رضي الله عنه. فلما وقف عليه النبي ﷺ قال: «قتل سبعة ثم قتلوه، هذا مني وأنا منه» وكررها. ثم حمله على ساعديه، ولم يكن له فراش إلا ساعدا رسول الله ﷺ، حتى حُفر له ووُضع في قبره.',
        'هذه الرواية ثابتة في صحيح مسلم، وهي وحدها كافية لتبين عظيم منزلة جليبيب عند رسول الله ﷺ. أما التفاصيل المشهورة عن زواجه والفتاة الأنصارية، فلا نخلطها بهذه الرواية الصحيحة ولا ننسبها إلى صحيح مسلم؛ إذ تحتاج إلى تخريج مستقل وبيان درجتها.',
        'لقد كان جليبيب حاضراً في قلب النبي ﷺ، فافتقده حين لم يذكره الناس، وكرّمه بعد موته بكلمات عظيمة. وفي ذلك رسالة لكل إنسان يشعر أنه منسي أو قليل الشأن: قد يكون لك عند الله وعند أهل الصلاح قدر لا تعرفه، فلا تجعل نظرة الناس هي مقياس قيمتك.',
      ],
      lessons: [
        'لا تقاس قيمة الإنسان بمظهره أو مكانته الاجتماعية.',
        'القائد الرحيم يتفقد أفراده ولا ينسى الضعفاء أو المغمورين.',
        'الوفاء يظهر في السؤال عن الغائب وتكريم صاحبه.',
        'الشهادة في سبيل الله منزلة عظيمة، ولا تعني أن نطلب القتال بغير حق أو حكمة.',
        'ينبغي أن نفرق بين الحديث الصحيح والتفاصيل التي تحتاج إلى تخريج.',
      ],
      practicalApplication: 'اقتدِ بالمعاني النبوية:\n\n• اسأل عن الشخص الذي لا يسأل عنه الآخرون.\n• لا تسخر من إنسان بسبب شكله أو فقره أو قلة علاقاته.\n• احفظ لأصحاب الفضل حقهم، واذكر محاسنهم.\n• لا تجعل شهرة الإنسان معياراً للحكم على صلاحه.\n\n**تأمل:** من الشخص الذي يمكنك أن تتفقده اليوم، وربما يشعر أن الجميع نسوه؟',
      question: SeerahQuestion(
        question: 'ماذا قال النبي ﷺ عندما وجد جليبيباً بعد المعركة؟',
        options: ['هذا مني وأنا منه', 'هو أولنا إسلاماً', 'هو قائد الجيش', 'هو أغنانا'],
        correctAnswer: 0,
        explanation: 'قال النبي ﷺ: «قتل سبعة ثم قتلوه، هذا مني وأنا منه»، كما في صحيح مسلم، حديث 2472.',
      ),
      relatedStories: ['رحمة النبي ﷺ بأصحابه', 'فضل الشهادة'],
    ),

// القصة 43 — أصحاب السبت | المصدر: القرآن الكريم، سورة الأعراف 163-166؛ سورة البقرة 65.
    SeerahStory(
      id: 43,
      title: 'أصحاب السبت: حين لا تنفع الحيلة',
      subtitle: 'اختبار الطاعة أمام شهوة المكسب',
      category: 'قصص القرآن',
      location: 'قرية على ساحل البحر',
      readingMinutes: 6,
      emoji: '🐟',
      storyParagraphs: [
        'قصّ القرآن خبر قرية من بني إسرائيل كانت حاضرة البحر، وابتلاها الله بحكم يتعلق بالصيد يوم السبت. وكانت الحيتان تأتيهم يوم سبتهم ظاهرة قريبة، وفي غير يوم السبت لا تأتيهم على الصورة نفسها. قال الله تعالى: {إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ لَا تَأْتِيهِمْ}.',
        'كان ذلك اختباراً واضحاً: هل يلتزمون أمر الله حين تتاح لهم فرصة المكسب، أم يبحثون عن طريق يلتفون به على النهي؟ وتذكر كتب التفسير صوراً لكيفية احتيال بعضهم على الصيد، مثل نصب الشباك أو اتخاذ الحياض قبل السبت، ثم أخذ السمك بعده. لكن هذه التفاصيل ليست كلها مذكورة في نص الآيات، ولذلك ينبغي عرضها على أنها من أقوال المفسرين لا على أنها نص قرآني.',
        'ويذكر القرآن أن أهل القرية صاروا فرقاً: فريقاً اعتدى وخالف، وفريقاً نهى عن السوء، وفريقاً قال للناهين: لماذا تعظون قوماً سيهلكهم الله أو يعذبهم؟ فأجاب الناهون أنهم يفعلون ذلك عذراً إلى ربهم، ولعل المخالفين يتقون ويرجعون.',
        'ثم بيّن الله عاقبة الموقف فقال: {فَلَمَّا نَسُوا مَا ذُكِّرُوا بِهِ أَنجَيْنَا الَّذِينَ يَنْهَوْنَ عَنِ السُّوءِ وَأَخَذْنَا الَّذِينَ ظَلَمُوا بِعَذَابٍ بَئِيسٍ بِمَا كَانُوا يَفْسُقُونَ}. وقال في شأن المعتدين: {كُونُوا قِرَدَةً خَاسِئِينَ}. فالقرآن ذكر مسخهم قردة، ولم يذكر في هذه الآيات أنهم مُسخوا خنازير.',
        'أما مصير الفرقة التي لم تعتد ولم تنهَ، فقد وقع فيه كلام للمفسرين؛ والآيات نصّت بوضوح على نجاة الذين كانوا ينهون عن السوء، وعلى أخذ الذين ظلموا بالعذاب. لذلك لا نجزم بتفاصيل لم يحسمها النص.',
        'تعلّمنا القصة أن التحايل على أمر الله لا يحوّل الحرام إلى حلال، وأن الطاعة ليست مجرد تغيير شكل الفعل مع الإبقاء على حقيقته. كما تذكرنا بأهمية النصح بالحكمة، وألا نيأس من دعوة الناس إلى الخير ما دام في ذلك رجاء للهداية وإقامة الحجة.',
      ],
      lessons: [
        'التحايل على المحرمات لا يغيّر حكمها ولا يبرئ الذمة.',
        'الالتزام بأمر الله يظهر عند وجود المصلحة والشهوة، لا عند غياب الإغراء فقط.',
        'الأمر بالمعروف والنهي عن المنكر يكون بعلم وحكمة وصبر.',
        'القرآن يثبت نجاة الذين نهوا عن السوء وعقوبة المعتدين.',
        'ينبغي التفريق بين نص القرآن والتفاصيل التي تذكرها كتب التفسير.',
      ],
      practicalApplication: 'حوّل القصة إلى سلوك يومي:\n\n• لا تبحث عن حيلة لتبرير خطأ تعرف أنه خطأ.\n• راجع طريقة كسبك للمال: هل فيها غش أو التفاف على حقوق الناس؟\n• إذا نصحت أحداً، فاختر الوقت والأسلوب المناسبين.\n• لا تسكت عن الخطأ لمجرد أن النصيحة قد لا تغيّر صاحبه فوراً، مع مراعاة القدرة والحكمة.\n\n**تأمل:** هل هناك أمر تعرف أنه غير صحيح وتحاول تبريره لنفسك بحيلة؟',
      question: SeerahQuestion(
        question: 'ما العاقبة التي ذكرها القرآن للمعتدين من أصحاب السبت؟',
        options: ['مُسخوا قردة خاسئين', 'غرقوا في البحر', 'ابتلعتهم الأرض', 'أُرسل عليهم الطوفان'],
        correctAnswer: 0,
        explanation: 'قال الله تعالى: {كُونُوا قِرَدَةً خَاسِئِينَ} في سورة الأعراف، الآية 166.',
      ),
      relatedStories: ['قصص بني إسرائيل', 'الأمر بالمعروف والنهي عن المنكر'],
    ),

// القصة 44 — موسى والخضر | المصادر: سورة الكهف 60-82؛ صحيح البخاري 3401؛ صحيح مسلم 2380.
    SeerahStory(
      id: 44,
      title: 'رحلة مع العبد الصالح',
      subtitle: 'موسى عليه السلام يتعلم التواضع والصبر',
      category: 'قصص القرآن',
      location: 'مجمع البحرين',
      readingMinutes: 8,
      emoji: '🌊',
      storyParagraphs: [
        'يروي القرآن قصة رحلة موسى عليه السلام لطلب العلم من عبد صالح آتاه الله رحمة وعلماً من عنده. وفي الحديث الصحيح أن موسى خطب في بني إسرائيل، فسُئل عن أعلم الناس فقال: أنا، ولم يردّ العلم إلى الله، فعاتبه الله وأخبره أن عبداً عند مجمع البحرين لديه علم لم يعلمه موسى. والحديث يبين أن العالم مهما بلغ علمه لا يحيط بكل شيء.',
        'أمر الله موسى أن يحمل حوتاً في مكتل، وأن المكان الذي يفقد فيه الحوت هو موضع لقاء ذلك العبد. فانطلق موسى ومعه فتاه يوشع بن نون، حتى وصلا إلى صخرة، فاستراحا، واضطرب الحوت وخرج إلى البحر، واتخذ طريقه فيه. ثم واصلا السير، فلما طلب موسى الطعام أخبره فتاه أنه نسي أن يذكر له أمر الحوت، فعرف موسى أن تلك هي العلامة التي يبحث عنها.',
        'رجعا يتتبعان آثارهما حتى وجدا العبد الصالح، الذي سماه الحديث الخضر. طلب موسى أن يصحبه ليتعلم مما علمه الله، فبيّن له الخضر أنه لن يستطيع الصبر على أمور لا يعرف باطنها، فوعده موسى بالصبر، واشترط الخضر ألا يسأله عن شيء حتى يبيّن له تفسيره.',
        'ركبا سفينة لمساكين يعملون في البحر، فخرق الخضر السفينة، فاستنكر موسى ذلك؛ لأن ظاهر الفعل إضرار بأناس أحسنوا إليهما. ثم لقيا غلاماً فقتله الخضر، فاشتد إنكار موسى؛ لأن ظاهر الأمر قتل نفس بغير حق. وبعد ذلك وصلا إلى قرية رفض أهلها ضيافتهما، فوجدا جداراً مائلاً فأقامه الخضر دون أجر، فتعجب موسى من عدم أخذ مقابل على العمل.',
        'عندها أعلن الخضر انتهاء الصحبة، وشرح لموسى الحكمة التي أطلعه الله عليها: كانت السفينة لمساكين يعملون في البحر، وكان أمامهم ملك يأخذ كل سفينة صالحة غصباً، فأراد أن يعيبها لتبقى لأصحابها. وأما الغلام فكان سيُرهق أبويه المؤمنين طغياناً وكفراً، فأراد الله أن يبدلهما خيراً منه. وأما الجدار فكان لغلامين يتيمين تحته كنز لهما، وكان أبوهما صالحاً، فأراد الله أن يبلغا أشدهما ويستخرجا كنزهما رحمة من ربك.',
        'وختم الخضر بقوله: {وَمَا فَعَلْتُهُ عَنْ أَمْرِي}. فهذه التصرفات لم تكن اجتهاداً بشرياً يبيح لأحد أن يقتل أو يتلف أموال الناس بحجة أن وراء الأمر حكمة خفية؛ بل كانت أموراً خاصة أطلع الله عليها عبداً من عباده. والدرس لنا هو التواضع في طلب العلم، والصبر على التعلم، والإيمان بأن علم الله أوسع من علم البشر.',
      ],
      lessons: [
        'لا ينبغي للإنسان أن يغتر بعلمه، بل يقول: الله أعلم.',
        'التواضع شرط مهم في طلب العلم والاستفادة من المعلم.',
        'قد تخفى علينا بعض الحكم، لكن لا يجوز أن نتجاوز الشرع بحجة الحكمة الخفية.',
        'الصبر وحسن السؤال يساعدان على فهم العلم.',
        'علم الله كامل، وعلم الإنسان محدود مهما اتسع.',
      ],
      practicalApplication: 'تعلّم من رحلة موسى عليه السلام:\n\n• إذا لم تعرف جواباً، فقل: لا أعلم، وابحث عنه.\n• لا تقاطع من يشرح لك؛ انتظر حتى يكتمل البيان ثم اسأل بأدب.\n• لا تتعجل الحكم على كل موقف من زاوية واحدة.\n• لا تستخدم القصة لتبرير ظلم أو أذى؛ فالخضر صرّح أنه لم يفعل ذلك عن رأيه.\n\n**تأمل:** ما الموضوع الذي تحتاج فيه إلى مزيد من التواضع والصبر قبل إصدار حكم؟',
      question: SeerahQuestion(
        question: 'ما العلامة التي جعلها الله لموسى ليعرف موضع لقاء العبد الصالح؟',
        options: ['فقدان الحوت', 'ظهور جبل عظيم', 'سماع صوت من البحر', 'رؤية طائر أبيض'],
        correctAnswer: 0,
        explanation: 'أُمر موسى أن يتخذ الحوت علامة، فحيث يفقده يكون موضع اللقاء، كما في حديث البخاري وقصة سورة الكهف.',
      ),
      relatedStories: ['قصص موسى عليه السلام', 'التواضع في طلب العلم'],
    ),

// القصة 45 — مريم عليها السلام | المصادر: سورة آل عمران 35-47؛ سورة مريم 16-36؛ صحيح البخاري 3432.
    SeerahStory(
      id: 45,
      title: 'مريم الصدّيقة الطاهرة',
      subtitle: 'أم عيسى عليه السلام وآية من آيات الله',
      category: 'قصص القرآن',
      location: 'بيت المقدس',
      readingMinutes: 7,
      emoji: '🌸',
      storyParagraphs: [
        'بدأت قصة مريم عليها السلام بدعاء أمها امرأة عمران، إذ نذرت ما في بطنها محرراً لله، فلما وضعتها أنثى قالت: {رَبِّ إِنِّي وَضَعْتُهَا أُنثَىٰ}. فسمتها مريم، وسألت الله أن يعيذها وذريتها من الشيطان الرجيم. فتقبلها الله بقبول حسن وأنبتها نباتاً حسناً، وجعل زكريا عليه السلام كافلاً لها.',
        'وكان زكريا كلما دخل عليها المحراب وجد عندها رزقاً، فسألها: {يَا مَرْيَمُ أَنَّىٰ لَكِ هَٰذَا}. فقالت: {هُوَ مِنْ عِندِ اللَّهِ إِنَّ اللَّهَ يَرْزُقُ مَن يَشَاءُ بِغَيْرِ حِسَابٍ}. وهكذا نشأت مريم في عبادة الله والطاعة، واصطفاها الله وطهرها، وبشرتها الملائكة بعيسى عليه السلام.',
        'أرسل الله إليها روحه، فتمثل لها بشراً سوياً. فاستعاذت بالرحمن منه، فطمأنها أنه رسول ربها ليهب لها غلاماً زكياً. تعجبت مريم؛ إذ لم يمسسها بشر ولم تكن بغياً، فأخبرها أن ذلك على الله يسير، وأن عيسى سيكون آية للناس ورحمة من الله.',
        'حملت مريم بعيسى، واعتزلت أهلها في مكان بعيد. ولما جاءها المخاض إلى جذع النخلة اشتد عليها الألم والهم، فناداها من تحتها ألا تحزن، وأرشدها إلى أن تهز جذع النخلة فيتساقط عليها رطباً جنياً، وأن تأكل وتشرب وتقر عيناً. وفي ذلك تذكير بأن التوكل على الله لا يمنع من الأخذ بالأسباب الممكنة.',
        'ثم عادت إلى قومها تحمل عيسى، فاستنكروا ما رأوا، فأشارت إليه، فتعجبوا كيف يكلمون طفلاً في المهد. فتكلم عيسى بإذن الله قائلاً: {إِنِّي عَبْدُ اللَّهِ آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا}. فكانت معجزته في الكلام إعلاناً لعبوديته لله ونبوته، وبرهاناً على قدرة الله.',
        'وقد أثنى القرآن على مريم ووصفها بالصدّيقة، وأثبت النبي ﷺ فضلها؛ ففي صحيح البخاري أنه قال: «خير نسائها مريم بنت عمران». والقصة لا تجعل مريم إلهاً ولا تجعل عيسى ابن الله، بل تؤكد أن عيسى عبد الله ورسوله، وأن ولادته من غير أب آية من آيات قدرة الخالق سبحانه.',
      ],
      lessons: [
        'الإخلاص والعبادة يرفعان منزلة الإنسان عند الله.',
        'قد يأتي الفرج من حيث لا يحتسب الإنسان، مع ضرورة الأخذ بالأسباب.',
        'العفة والثبات على الحق من أعظم صفات المؤمن.',
        'قد يبتلي الله عباده الصالحين بما يحتاج إلى صبر ويقين.',
        'عيسى عليه السلام عبد الله ورسوله، وولادته آية من آيات الله.',
      ],
      practicalApplication: 'اقتدِ بمعاني قصة مريم:\n\n• اجعل لك وقتاً ثابتاً للعبادة والدعاء.\n• لا تيأس عند الشدة؛ اطلب العون من الله وخذ بالأسباب.\n• حافظ على عفتك وصدقك حتى لو أساء الناس فهم موقفك.\n• لا تجعل كلام الناس يبعدك عن الحق إذا كنت على بينة.\n\n**تأمل:** كيف تجمع بين التوكل على الله والعمل بالأسباب عندما تمر بضيق؟',
      question: SeerahQuestion(
        question: 'بماذا تكلم عيسى عليه السلام وهو في المهد؟',
        options: ['إنه عبد الله آتاه الكتاب وجعله نبياً', 'إنه ملك من الملائكة', 'إنه ابن الله', 'إنه لا يعرف الكلام'],
        correctAnswer: 0,
        explanation: 'قال عيسى عليه السلام: {إِنِّي عَبْدُ اللَّهِ آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا}، كما في سورة مريم.',
      ),
      relatedStories: ['عيسى عليه السلام', 'زكريا ويحيى عليهما السلام'],
    ),

// القصة 46 — إبراهيم عليه السلام | المصادر: سورة الأنبياء 51-70؛ سورة الصافات 99-113؛ سورة البقرة 124-129؛ صحيح البخاري 3358 و3364.
    SeerahStory(
      id: 46,
      title: 'إبراهيم خليل الرحمن',
      subtitle: 'التوحيد والتوكل والابتلاء',
      category: 'قصص القرآن',
      location: 'بلاد الرافدين وفلسطين ومكة',
      readingMinutes: 9,
      emoji: '🕋',
      storyParagraphs: [
        'نشأ إبراهيم عليه السلام في قوم يعبدون الأصنام، فدعا أباه وقومه إلى عبادة الله وحده، وبيّن لهم أن الأصنام لا تسمع ولا تبصر ولا تنفع ولا تضر. وكان يخاطب أباه بأدب ورحمة، فيقول: {يَا أَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِي عَنكَ شَيْئًا}. لكن أباه لم يقبل دعوته، وهدده إن لم ينتهِ عن نقد آلهتهم.',
        'ولما خرج قومه، نظر إبراهيم إلى أصنامهم التي يعبدونها من دون الله، فحطمها وجعل كبيرها باقياً، ليقيم عليهم الحجة ويسألهم أن يرجعوا إلى أصنامهم إن كانت تنطق. فلما عادوا وسألوه عمن فعل ذلك، قال لهم: {بَلْ فَعَلَهُ كَبِيرُهُمْ هَٰذَا فَاسْأَلُوهُمْ إِن كَانُوا يَنطِقُونَ}. فعادوا إلى أنفسهم وأقروا أن الأصنام لا تنطق، لكنهم لم يثبتوا على مقتضى هذا الاعتراف.',
        'قرروا إحراق إبراهيم نصرة لآلهتهم، فألقوه في النار، فجعلها الله برداً وسلاماً عليه. قال تعالى: {قُلْنَا يَا نَارُ كُونِي بَرْدًا وَسَلَامًا عَلَىٰ إِبْرَاهِيمَ}. لم تكن النجاة بقوة بشرية، بل بقدرة الله الذي يحفظ من يشاء، ويجعل الأسباب على غير ما اعتاده الناس.',
        'ثم هاجر إبراهيم في سبيل الله، ورزقه الله إسماعيل من هاجر. وجاء في الحديث الصحيح أن إبراهيم ذهب بهاجر وإسماعيل وهما صغيران إلى وادٍ غير ذي زرع عند موضع البيت، وترك عندهما جراباً فيه تمر وسقاء فيه ماء، ثم انصرف امتثالاً لأمر الله. فلما سألته هاجر: آلله أمرك بهذا؟ قال: نعم، فقالت متوكلة: إذن لا يضيعنا.',
        'نفد الماء، وأخذت هاجر تبحث عن الماء لابنها، فسعت بين الصفا والمروة سبع مرات، ثم أرسل الله جبريل فضرب الأرض فنبع ماء زمزم. وفي الحديث أن أم إسماعيل جعلت تحوط الماء وتغرف منه، فكان ذلك سبباً في حياة الوادي وابتداء عمران مكة. وهذا أصل السعي بين الصفا والمروة الذي يتذكر فيه المسلمون سعي هاجر وصبرها.',
        'ولما كبر إسماعيل وبلغ السعي مع أبيه، رأى إبراهيم في المنام أنه يذبحه، ورؤيا الأنبياء وحي. فصارح ابنه، فكان جواب إسماعيل: {يَا أَبَتِ افْعَلْ مَا تُؤْمَرُ سَتَجِدُنِي إِن شَاءَ اللَّهُ مِنَ الصَّابِرِينَ}. فلما أسلما وتله للجبين، ناداه الله أنه قد صدق الرؤيا وفداه بذبح عظيم. ثم رفع إبراهيم وإسماعيل قواعد البيت، ودعوا الله أن يتقبل منهما.',
        'وتتكرر في حياة إبراهيم معاني التوحيد والتسليم والثقة بالله: دعا أباه وقومه بالحكمة، وصبر على الأذى، وهاجر، وتوكل في وادٍ لا زرع فيه، وامتثل أمر الله في أعز ما يملك. ولم تكن هذه المواقف دعوة إلى إيذاء النفس أو الأبناء؛ فهي واقعة نبوية خاصة بوحي من الله، وليست أمراً يشرع لأحد أن يقلدها من تلقاء نفسه.',
      ],
      lessons: [
        'التوحيد أساس دعوة جميع الأنبياء.',
        'يمكن الجمع بين الثبات على العقيدة وحسن الخطاب مع الوالدين.',
        'التوكل الصادق لا يمنع الحركة والعمل، كما فعلت هاجر في طلب الماء.',
        'الابتلاء يكشف صدق التسليم لله، ويحتاج إلى يقين وصبر.',
        'لا يجوز إسقاط الوقائع الخاصة بالأنبياء على الناس من غير دليل شرعي.',
      ],
      practicalApplication: 'استفد من مواقف إبراهيم وهاجر وإسماعيل:\n\n• راجع ما يتعلق بالتوحيد في عبادتك، ولا تجعل بينك وبين الله شريكاً.\n• إذا نصحت والديك أو أهلك، فاجمع بين وضوح الحق ولين الكلام.\n• عند الشدة، ادع الله ثم تحرك بالأسباب المتاحة ولا تستسلم.\n• إذا كُلّفت بمسؤولية، فكن صادقاً في أدائها واطلب من الله القبول.\n\n**تأمل:** ما الأمر الذي تحتاج أن تتوكل فيه على الله مع اتخاذ خطوة عملية؟',
      question: SeerahQuestion(
        question: 'ماذا قالت هاجر عندما علمت أن إبراهيم تركها وابنها بأمر الله؟',
        options: ['إذن لا يضيعنا', 'لن أتحرك من مكاني', 'سأعود إلى قومك', 'لا أريد الماء'],
        correctAnswer: 0,
        explanation: 'لما قالت له: آلله أمرك بهذا؟ وأجابها بنعم، قالت: إذن لا يضيعنا، كما ورد في حديث البخاري عن قصة هاجر وإسماعيل.',
      ),
      relatedStories: ['إسماعيل وزمزم', 'بناء الكعبة', 'التوكل على الله'],
    ),

// القصة 47 — لوط عليه السلام | المصدر: القرآن الكريم، سورة الأعراف 80-84؛ سورة هود 77-83؛ سورة الحجر 57-77؛ سورة الشعراء 160-175.
    SeerahStory(
      id: 47,
      title: 'لوط عليه السلام: الثبات أمام فساد القوم',
      subtitle: 'دعوة إلى الطهارة وترك الفاحشة',
      category: 'قصص القرآن',
      location: 'قرى قوم لوط',
      readingMinutes: 7,
      emoji: '⚠️',
      storyParagraphs: [
        'أرسل الله لوطاً عليه السلام إلى قوم وقعوا في فاحشة عظيمة، وجاهروا بها، وتركوا ما أحل الله لهم. فدعاهم نبيهم إلى تقوى الله وإلى ترك الفاحشة، وقال لهم: {أَتَأْتُونَ الْفَاحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ الْعَالَمِينَ}. وبيّن القرآن أنهم كانوا يأتون الرجال شهوة من دون النساء، ويتجاوزون حدود الله.',
        'لم يقابل القوم النصيحة بالتوبة، بل استكبروا وهددوا بإخراج لوط وأهله من قريتهم، وقالوا: {أَخْرِجُوا آلَ لُوطٍ مِّن قَرْيَتِكُم إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ}. وهكذا صاروا يعيبون الطهارة ويجعلون الاستقامة سبباً للطرد، بدلاً من أن يراجعوا أنفسهم ويستجيبوا لنبيهم.',
        'وجاءت رسل الله إلى لوط في صورة ضيوف، فضاق بهم لوط وخاف عليهم من اعتداء قومه. وجاءه قومه يسرعون إليه يريدون ضيوفه، فذكّرهم بالله ودعاهم إلى الطريق الحلال، لكنهم أصروا على ما هم فيه. عندها أخبرته الملائكة أنهم رسل ربه، وأن القوم لن يصلوا إليه بسوء.',
        'أُمر لوط أن يسري بأهله في جزء من الليل، وألا يلتفت منهم أحد، إلا امرأته التي جاء في القرآن أنها من الغابرين. فلما جاء أمر الله، جعل الله عالي القرية سافلها، وأمطر عليهم حجارة من سجيل منضود. ونجّى الله لوطاً ومن آمن معه، وكانت عاقبة المكذبين عبرة لمن يأتي بعدهم.',
        'لا يذكر القرآن أسماء المدن المعاصرة أو الإحداثيات الجغرافية الدقيقة لهذه القرى، فلا ينبغي الجزم بتحديدات جغرافية لا يقوم عليها نص. كما لا حاجة إلى إضافة أوصاف للعذاب لم يذكرها القرآن، مثل القول إن الحجارة كانت من نار؛ فالقرآن وصفها بأنها من سجيل.',
        'تعلّمنا القصة أن كثرة المخالفين لا تجعل الباطل حقاً، وأن المؤمن قد يواجه ضغطاً اجتماعياً شديداً بسبب تمسكه بالحق. كما تبيّن أن الإصلاح يبدأ بالدعوة والإنذار، وأن الإصرار على الظلم والفساد له عاقبة، وأن النجاة تكون بالإيمان والطاعة.',
      ],
      lessons: [
        'الثبات على الحق واجب ولو خالف الإنسان أكثر من حوله.',
        'الحياء والطهارة والاستقامة قيم لا يصح الاستهزاء بها.',
        'لا يجوز تبرير الفاحشة أو الاعتداء بحجة انتشار الفعل بين الناس.',
        'الأنبياء دعوا أقوامهم إلى التوبة قبل نزول العذاب.',
        'ينبغي الالتزام بما ورد في القرآن وعدم إضافة تفاصيل غيبية بلا دليل.',
      ],
      practicalApplication: 'استفد من القصة:\n\n• ابتعد عن كل طريق يقود إلى الفاحشة أو الاعتداء على الآخرين.\n• لا تجعل ضغط الأصدقاء أو المجتمع يغيّر مبادئك.\n• إذا رأيت خطأ، فأنكره بالعلم والحكمة والوسيلة المشروعة.\n• احمِ نفسك وأسرتك من البيئات التي تطبع مع السلوك المؤذي.\n\n**تأمل:** كيف تحافظ على مبادئك عندما يستهزئ بها من حولك؟',
      question: SeerahQuestion(
        question: 'كيف كانت عاقبة قوم لوط كما وصفها القرآن؟',
        options: ['قُلبت قراهم وأُمطروا بحجارة من سجيل', 'غرقوا في البحر', 'أهلكتهم ريح صرصر', 'أخذتهم الصيحة فقط'],
        correctAnswer: 0,
        explanation: 'ذكر القرآن أن الله جعل عالي قراهم سافلها وأمطر عليهم حجارة من سجيل، ونجّى لوطاً ومن آمن معه.',
      ),
      relatedStories: ['قصص الأنبياء', 'الثبات على الحق'],
    ),

// القصة 48 — صالح وناقة الله | المصادر: سورة الأعراف 73-79؛ سورة هود 61-68؛ سورة الشمس 11-15؛ سورة القمر 23-31.
    SeerahStory(
      id: 48,
      title: 'ناقة الله: آية لقوم ثمود',
      subtitle: 'حين قابل قوم صالح النعمة بالتكذيب',
      category: 'قصص القرآن',
      location: 'ديار ثمود والحِجر',
      readingMinutes: 7,
      emoji: '🐪',
      storyParagraphs: [
        'أرسل الله صالحاً عليه السلام إلى ثمود، وكانوا قوماً أقوياء يسكنون في أرض نحتوا فيها من الجبال بيوتاً. دعاهم صالح إلى عبادة الله وحده، وذكّرهم بنعمته عليهم، لكن كثيراً منهم كذبوه واستكبروا عن دعوته.',
        'طلبوا منه آية تدل على صدقه، فجعل الله لهم الناقة آية ظاهرة، وقال صالح: {هَٰذِهِ نَاقَةُ اللَّهِ لَكُمْ آيَةً}. وأمرهم أن يتركوها تأكل في أرض الله وألا يمسوها بسوء، وحذّرهم من أن يصيبهم عذاب قريب إن اعتدوا عليها. ولا يذكر القرآن أن الناقة خرجت من صخرة، أو يحدد لونها أو حجمها أو كونها حاملاً؛ لذلك لا نجزم بهذه التفاصيل.',
        'وجعل الله للماء قسمة بينهم وبين الناقة، فقال تعالى: {لَهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَعْلُومٍ}. فكان لكل طرف نصيبه في اليوم المقرر. ومع وضوح الآية، لم يرضَ المعاندون بأمر الله، وتآمروا على الناقة وعقروها، ونسب القرآن الفعل إلى القوم، وذكر أن أشقاهم انبعث لعقرها.',
        'بعد عقر الناقة قال صالح لقومه: {تَمَتَّعُوا فِي دَارِكُمْ ثَلَاثَةَ أَيَّامٍ ذَٰلِكَ وَعْدٌ غَيْرُ مَكْذُوبٍ}. ثم جاءهم العذاب، فأخذتهم الرجفة والصيحة، فأصبحوا في ديارهم جاثمين. ونجّى الله صالحاً والذين آمنوا معه برحمته.',
        'ولا يثبت في نص القرآن تقسيم ألوان وجوههم إلى أصفر ثم أحمر ثم أسود في الأيام الثلاثة، كما لا يذكر القرآن اسم قاتل الناقة. قد ترد هذه التفاصيل في بعض كتب التفسير والأخبار، لكن القصة الأساسية لا تحتاج إليها؛ فالعبرة واضحة في تكذيب الآية، والاعتداء على الناقة، ثم نزول العذاب بعد الإنذار.',
        'تذكرنا ناقة صالح بأن النعمة والآية قد تكونان اختباراً للطاعة، وأن رؤية الدليل لا تنفع من يصر على العناد. كما تعلمنا احترام المخلوقات وعدم الاعتداء عليها، وأن الظلم الجماعي لا يبرره أن يقوم بالفعل شخص واحد إذا رضي به القوم وشاركوا في الجريمة أو سكتوا عنها مع القدرة على الإنكار.',
      ],
      lessons: [
        'الآيات الواضحة لا تنفع من يعاند الحق ولا يريد الهداية.',
        'الاعتداء على خلق الله ظلم، ويجب اجتنابه.',
        'تقسيم الحقوق والموارد بعدل يمنع الظلم والخصومة.',
        'الإنذار قبل العقوبة من سنن الله في إرسال الرسل.',
        'ينبغي عدم الجزم بأسماء أو تفاصيل لم يثبتها القرآن أو السنة الصحيحة.',
      ],
      practicalApplication: 'طبّق الدروس:\n\n• لا تظلم إنساناً أو حيواناً لمجرد قدرتك عليه.\n• احترم حقوق الآخرين في الماء والمال والممتلكات والوقت.\n• إذا ظهر لك الحق، فلا تؤجّل الاستجابة له بسبب العناد.\n• لا تشارك في أذى جماعي، ولا تبرره بقولك إن غيرك بدأه.\n\n**تأمل:** هل تحافظ على حقوق الآخرين حتى عندما لا يستطيعون المطالبة بها؟',
      question: SeerahQuestion(
        question: 'ما الأمر الذي نهى صالح قومه عنه تجاه الناقة؟',
        options: ['أن يمسوها بسوء', 'أن يطعموها', 'أن يتركوها في الأرض', 'أن يشربوا الماء'],
        correctAnswer: 0,
        explanation: 'قال صالح: {فَذَرُوهَا تَأْكُلْ فِي أَرْضِ اللَّهِ وَلَا تَمَسُّوهَا بِسُوءٍ}، فكان الاعتداء عليها سبباً في نزول العذاب.',
      ),
      relatedStories: ['ثمود وصالح عليه السلام', 'العدل والرفق بالحيوان'],
    ),

// القصة 49 — هود عليه السلام وقوم عاد | المصادر: سورة هود 50-60؛ سورة الأحقاف 21-26؛ سورة الحاقة 6-8.
    SeerahStory(
      id: 49,
      title: 'هود عليه السلام: القوة لا تمنع العذاب',
      subtitle: 'قوم عاد حين اغتروا بشدتهم',
      category: 'قصص القرآن',
      location: 'الأحقاف',
      readingMinutes: 7,
      emoji: '🌪️',
      storyParagraphs: [
        'أرسل الله هوداً عليه السلام إلى قوم عاد، وكانوا أصحاب قوة وبأس، وقد بنوا وشيدوا واغتر بعضهم بما عنده من قدرة. فدعاهم هود إلى عبادة الله وحده، وترك الشرك، وذكّرهم أن القوة والمال لا يجعلان الإنسان مستقلاً عن ربه.',
        'قال لهم: {يَا قَوْمِ اعْبُدُوا اللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُ}. لكنهم كذبوه واتهموه بالسفاهة، وأصروا على عبادة ما كان يعبد آباؤهم. فبيّن لهم هود أنه رسول من رب العالمين، وأنه لا يريد منهم أجراً، وإنما يبلغهم ما أُرسل به.',
        'وفي سورة الأحقاف يذكر الله أن هوداً أنذر قومه في الأحقاف، وأنهم لما رأوا عارضاً مقبلاً في السماء قالوا: {هَٰذَا عَارِضٌ مُّمْطِرُنَا}. لكن هوداً بيّن لهم أن الأمر ليس مطراً يحمل الخير كما ظنوا، بل هو ما استعجلوه: ريح فيها عذاب أليم، تدمر كل شيء بأمر ربها.',
        'ووصف القرآن الريح بأنها صرصر عاتية، وسخرها الله عليهم سبع ليال وثمانية أيام حسوماً، فترى القوم صرعى كأنهم أعجاز نخل خاوية. ولم تنفعهم قوتهم ولا ما بنوه، ونجّى الله هوداً والذين آمنوا معه برحمته.',
        'لا يحدد القرآن في هذه الآيات موقع الأحقاف بحدود جغرافية معاصرة قاطعة، لذلك نكتفي بالاسم القرآني ولا نجزم بقول إن المكان هو دولة بعينها. كما أن قصة وفد الاستسقاء والسحابة السوداء بتفاصيلها ليست في نص الآيات المذكورة، فلا نعرضها على أنها جزء ثابت من القرآن.',
        'إن قصة عاد تذكّر الإنسان أن القوة نعمة ومسؤولية وليست سبباً للتكبر. فالمباني والقدرات والتقدم لا تحمي مجتمعاً يظلم ويكذب ويستكبر عن الحق. والنجاة ليست بكثرة العدد، بل بالإيمان والعمل الصالح والرجوع إلى الله.',
      ],
      lessons: [
        'لا تغتر بالقوة أو المال أو التقدم؛ فكل ذلك من نعم الله.',
        'الاستكبار عن الحق يحجب الإنسان عن الهداية.',
        'الأنبياء دعوا أقوامهم إلى التوحيد دون طلب أجر منهم.',
        'قد تأتي العاقبة من أمر يظنه الناس خيراً إذا كان إنذاراً من الله.',
        'النجاة تكون بالإيمان والطاعة لا بالمظاهر والقوة المادية وحدها.',
      ],
      practicalApplication: 'استفد من قصة عاد:\n\n• استخدم قوتك أو منصبك في نصرة الضعيف لا في ظلمه.\n• لا تجعل النجاح المادي سبباً للغرور أو الاستهزاء بالآخرين.\n• إذا نصحك شخص أمين، فاستمع إلى حجته قبل أن ترفض كلامه.\n• اشكر الله على النعم واستعملها في الخير.\n\n**تأمل:** هل هناك نعمة في حياتك تحولت إلى سبب للغرور بدلاً من الشكر؟',
      question: SeerahQuestion(
        question: 'كم استمرت الريح التي أُرسلت على قوم عاد كما ورد في القرآن؟',
        options: ['سبع ليال وثمانية أيام', 'ثلاثة أيام', 'أربعين يوماً', 'ليلة واحدة'],
        correctAnswer: 0,
        explanation: 'قال الله تعالى: {سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَانِيَةَ أَيَّامٍ حُسُومًا} في سورة الحاقة.',
      ),
      relatedStories: ['عذاب الأمم المكذبة', 'الشكر والتواضع'],
    ),

// القصة 50 — شعيب عليه السلام | المصادر: سورة الأعراف 85-93؛ سورة هود 84-95؛ سورة الشعراء 176-191.
    SeerahStory(
      id: 50,
      title: 'شعيب عليه السلام: الأمانة في المعاملات',
      subtitle: 'دعوة أهل مدين إلى التوحيد والعدل',
      category: 'قصص القرآن',
      location: 'مدين',
      readingMinutes: 7,
      emoji: '⚖️',
      storyParagraphs: [
        'أرسل الله شعيباً عليه السلام إلى أهل مدين، فدعاهم إلى عبادة الله وحده، وترك الشرك والفساد. وكان من أبرز ما ابتلوا به التطفيف في الكيل والميزان، وبخس الناس حقوقهم، والإفساد في الأرض. فجمع شعيب في دعوته بين إصلاح العقيدة وإصلاح المعاملات؛ لأن الإيمان لا ينفصل عن العدل في البيع والشراء.',
        'قال لهم: {أَوْفُوا الْكَيْلَ وَالْمِيزَانَ بِالْقِسْطِ وَلَا تَبْخَسُوا النَّاسَ أَشْيَاءَهُمْ وَلَا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ}. كما نهاهم عن قطع الطريق والصد عن سبيل الله، وذكّرهم أن ما يبقى لهم من الحلال خير من المكاسب التي تأتي بالغش والظلم، إن كانوا مؤمنين.',
        'لكن الملأ من قومه استكبروا، وسخروا من دعوته، واحتجوا بأنهم لا يريدون ترك ما اعتادوا عليه في عبادة الآباء والتصرف في أموالهم. وهددوه ومن آمن معه بالإخراج من القرية أو الإكراه على العودة إلى ملتهم. فثبت شعيب على الحق، وبيّن أنه لا يريد أن يخالفهم إلى ما ينهاهم عنه، وأنه لا يطلب إلا الإصلاح ما استطاع، وأن توفيقه من الله.',
        'ولما أصروا على التكذيب، جاءت عاقبتهم كما أخبر القرآن. فقد ذكر القرآن في سورة الأعراف أن الذين كذبوا شعيباً أخذتهم الرجفة فأصبحوا في دارهم جاثمين، وذكر في سورة الشعراء عذاب يوم الظلة لأصحاب الأيكة. وقد بحث المفسرون في العلاقة بين أهل مدين وأصحاب الأيكة، لذلك لا ندمج تفاصيل العذابين في وصف واحد من غير بيان.',
        'ولا يصح أن نقول إن السحابة أمطرت ناراً؛ فالقرآن وصف عذاب يوم الظلة ولم يذكر هذا التعبير. كما أن وصف شعيب بأنه خطيب الأنبياء مشهور في بعض كتب التفسير والآثار، لكن القصة هنا تركز على ما ثبت في القرآن من دعوته وموقف قومه وعاقبتهم.',
        'تعلّمنا قصة شعيب أن العبادة ليست شعائر منفصلة عن الأخلاق؛ فمن يعبد الله حقاً لا يغش الناس ولا يأكل أموالهم بالباطل. كما تؤكد أن الإصلاح الاقتصادي جزء من الإصلاح الأخلاقي، وأن الداعية الصادق يبدأ بنفسه ولا يطلب من الناس ما لا يلتزمه.',
      ],
      lessons: [
        'التوحيد أساس الإصلاح، والعدل في المعاملات من مقتضيات الإيمان.',
        'الغش والتطفيف وبخس الناس حقوقهم من صور الفساد المحرمة.',
        'على الناصح أن يبدأ بنفسه وألا يخالف فعله قوله.',
        'لا يجوز تهديد الناس أو إكراههم على ترك الحق.',
        'ينبغي التفريق بين ما نص عليه القرآن وما اختلفت فيه كتب التفسير.',
      ],
      practicalApplication: 'طبّق وصايا شعيب عليه السلام:\n\n• لا تغش في البيع أو الشراء، ولا تخفِ عيباً في سلعة.\n• أدِّ حقوق الناس كاملة، سواء كانت مالاً أو وقتاً أو عملاً.\n• لا تستخدم منصبك أو خبرتك لتأخذ ما لا تستحق.\n• إذا نصحت غيرك، فابدأ بمراجعة سلوكك أنت.\n\n**تأمل:** هل تعطي الناس في عملك أو معاملاتك الحق كاملاً كما تحب أن يعاملوك؟',
      question: SeerahQuestion(
        question: 'ما أبرز فساد أهل مدين الذي نهى عنه شعيب عليه السلام؟',
        options: ['التطفيف في الكيل والميزان', 'عبادة الكواكب فقط', 'ترك الزراعة', 'عدم بناء البيوت'],
        correctAnswer: 0,
        explanation: 'نهى شعيب قومه عن نقص الكيل والميزان وبخس الناس أشياءهم، كما في سورة هود وسورة الأعراف.',
      ),
      relatedStories: ['الأمانة في البيع والشراء', 'العدل في الإسلام'],
    ),

    // القصة 51 — لقاء العقبة الأول والتمهيد للهجرة | المصادر: السيرة لابن هشام؛ صحيح البخاري 3892 في شروط البيعة.
    SeerahStory(
      id: 51,
      title: 'لقاء العقبة الأول',
      subtitle: 'بداية الطريق إلى يثرب',
      category: 'السيرة النبوية',
      location: 'مكة المكرمة — منى',
      readingMinutes: 6,
      emoji: '🤝',
      storyParagraphs: [
        'في موسم الحج، كان النبي ﷺ يعرض دعوته على القبائل التي تأتي إلى مكة، يبحث عمّن يسمع الحق ويحمي حرية الناس في الإيمان. وفي أحد المواسم التقى ستة رجال من الخزرج قدموا من يثرب، فدعاهم إلى الإسلام وقرأ عليهم القرآن.',
        'استجاب الرجال الستة وآمنوا برسول الله ﷺ. وتذكر كتب السيرة أسماءهم: أسعد بن زرارة، وعوف بن الحارث، ورافع بن مالك، وقطبة بن عامر، وعقبة بن عامر بن نابي، وجابر بن عبد الله بن رئاب. ولا ينبغي الخلط بين عقبة بن عامر المذكور هنا وبين الصحابي المشهور عقبة بن عامر الجهني.',
        'عاد هؤلاء إلى يثرب وهم يحملون رسالة جديدة، وحدثوا قومهم عن الإسلام. وكانت يثرب تعيش تاريخاً من النزاع بين الأوس والخزرج، فرأى القادمون أن رسالة التوحيد والأخوة قد تكون سبباً في جمع القلوب بعد طول خصومة.',
        'وفي موسم الحج التالي، قدم اثنا عشر رجلاً من أهل يثرب، فبايعوا النبي ﷺ عند العقبة على أصول عظيمة: ألا يشركوا بالله شيئاً، ولا يسرقوا، ولا يزنوا، ولا يقتلوا أولادهم، ولا يأتوا ببهتان، وألا يعصوا النبي ﷺ في معروف. وهذه الشروط ثابتة في حديث عبادة بن الصامت في صحيح البخاري، وهي قريبة من آيات البيعة في سورة الممتحنة.',
        'وبعد البيعة أرسل النبي ﷺ مصعب بن عمير رضي الله عنه إلى يثرب ليعلّم من أسلم القرآن وأحكام الدين. فكان عمله تعليماً هادئاً وصبراً على الناس، لا استعجالاً للنتائج ولا إكراهاً لأحد.',
        'وهكذا لم تقع الهجرة فجأة؛ بل سبقتها لقاءات، وإيمان، وبيعة، وتعليم، وبناء روابط بين المؤمنين. وتكشف القصة أن التغيير الكبير قد يبدأ بعدد قليل من أصحاب القلوب الصادقة.',
      ],
      lessons: [
        'قد يبدأ التغيير الكبير باستجابة عدد قليل من الصادقين.',
        'التوحيد والأخلاق أساس أي مجتمع صالح.',
        'التعليم والصبر يسبقان بناء المجتمع القوي.',
        'الوفاء بالبيعة والعهد مسؤولية عظيمة.',
      ],
      practicalApplication: 'طبّق معاني اللقاء الأول:\n\n• ابدأ بإصلاح نفسك ومن حولك بالحكمة.\n• لا تحتقر أثر الكلمة الطيبة ولو استجاب لها شخص واحد.\n• اجعل الصدق والأمانة أساس علاقاتك.\n• ساعد على إصلاح الخلافات بدل تأجيجها.',
      question: SeerahQuestion(
        question: 'من الصحابي الذي أرسله النبي ﷺ إلى يثرب ليعلّم أهلها القرآن؟',
        options: ['مصعب بن عمير', 'زيد بن حارثة', 'بلال بن رباح', 'أبو عبيدة بن الجراح'],
        correctAnswer: 0,
        explanation: 'أرسل النبي ﷺ مصعب بن عمير رضي الله عنه بعد بيعة العقبة ليعلّم من أسلم في يثرب.',
      ),
      relatedStories: ['بيعة العقبة الثانية', 'الهجرة إلى المدينة'],
    ),

    // القصة 52 — بيعة العقبة الثانية | المصادر: صحيح البخاري، كتاب مناقب الأنصار؛ السيرة لابن هشام.
    SeerahStory(
      id: 52,
      title: 'بيعة العقبة الثانية',
      subtitle: 'عهد النصرة والحماية',
      category: 'السيرة النبوية',
      location: 'مكة المكرمة — العقبة بمنى',
      readingMinutes: 7,
      emoji: '🌙',
      storyParagraphs: [
        'بعد أن انتشر الإسلام في بيوت من يثرب بجهد مصعب بن عمير رضي الله عنه، جاء في موسم الحج التالي وفد أكبر من المسلمين، واجتمعوا بالنبي ﷺ ليلاً عند العقبة في سرية وحذر؛ لأن قريشاً كانت تراقب الدعوة وتؤذي أصحابها.',
        'تذكر روايات السيرة أن الذين حضروا كانوا ثلاثة وسبعين رجلاً وامرأتين، وأن المرأتين هما نسيبة بنت كعب وأسماء بنت عمرو رضي الله عنهما. وتختلف بعض المصادر في طريقة عدّ الحاضرين، لذلك يُذكر العدد على أنه العدد المشهور في رواية ابن إسحاق.',
        'تكلم العباس بن عبد المطلب، وكان لم يسلم بعد بحسب رواية السيرة، فنبّه أهل يثرب إلى خطورة ما هم مقبلون عليه: فهم يدعون النبي ﷺ إلى بلدهم، وعليهم أن يعرفوا أنهم سيحمونه من خصومه. فأظهروا استعدادهم للوفاء بما عاهدوا عليه.',
        'كانت البيعة على السمع والطاعة في المنشط والمكره، والإنفاق في العسر واليسر، والأمر بالمعروف والنهي عن المنكر، والقيام لله دون خوف من لوم الناس، ونصرة النبي ﷺ وحمايته إذا قدم إليهم. وهي بيعة نصرة ومسؤولية، وليست مجرد إعلان محبة.',
        'واختار النبي ﷺ منهم اثني عشر نقيباً، ليكونوا مسؤولين عن قومهم ويتابعوا شؤونهم. ثم انصرفوا إلى رحالهم، وبدأ المسلمون بعد ذلك يهاجرون إلى يثرب أفراداً وجماعات، حتى أذن الله لنبيه ﷺ بالهجرة.',
        'كانت هذه البيعة نقطة تحول في تاريخ الدعوة؛ فقد انتقلت من جماعة مستضعفة تتعرض للأذى في مكة إلى مجتمع يستعد لاستقبالها وحمايتها. ولم يكن ذلك طلباً للجاه أو المال، بل التزاماً بنصرة الحق وتحمل تبعاته.',
      ],
      lessons: [
        'نصرة الحق تحتاج إلى التزام عملي لا إلى الكلام وحده.',
        'الوفاء بالعهد من أعظم أخلاق المؤمن.',
        'القيادة مسؤولية وخدمة وليست تشريفاً فقط.',
        'التخطيط والعمل الجماعي من أسباب نجاح الدعوة.',
      ],
      practicalApplication: 'استفد من البيعة:\n\n• كن واضحاً في وعودك ولا تعد بما لا تستطيع.\n• انصر المظلوم بالطرق المشروعة.\n• شارك في عمل جماعي نافع والتزم بمسؤوليتك.\n• اجعل رضا الله مقدماً على خوفك من كلام الناس.',
      question: SeerahQuestion(
        question: 'كم نقيباً اختيروا من أهل يثرب بعد البيعة؟',
        options: ['ثمانية', 'عشرة', 'اثنا عشر', 'خمسة عشر'],
        correctAnswer: 2,
        explanation: 'اختير اثنا عشر نقيباً ليتولوا متابعة شؤون قومهم.',
      ),
      relatedStories: ['لقاء العقبة الأول', 'الهجرة إلى المدينة'],
    ),

    // القصة 53 — الهجرة إلى الحبشة | المصادر: السيرة لابن هشام؛ رواية أم سلمة في مسند أحمد في قصة جعفر والنجاشي.
    SeerahStory(
      id: 53,
      title: 'الهجرة إلى الحبشة',
      subtitle: 'حين وجد المستضعفون الأمان',
      category: 'الهجرة',
      location: 'مكة المكرمة — الحبشة',
      readingMinutes: 7,
      emoji: '🛳️',
      storyParagraphs: [
        'اشتد أذى قريش على من آمن بالله ورسوله ﷺ، وصار بعض المسلمين يتعرضون للتعذيب والضغط ليرجعوا عن دينهم. وكان النبي ﷺ حريصاً على سلامتهم، فأرشد من اشتد عليه الأذى إلى الهجرة إلى الحبشة؛ لأن بها ملكاً لا يُظلم عنده أحد، كما ورد في روايات السيرة.',
        'خرجت جماعة من المسلمين تاركة الأهل والديار طلباً للأمان على الدين. وتذكر كتب السيرة هجرتين إلى الحبشة، وتورد أعداداً وتواريخ مختلفة بين الروايات؛ لذلك لا نجعل رقماً واحداً أو يوماً محدداً حقيقة قطعية لا خلاف فيها.',
        'لم يرضَ بعض زعماء قريش أن يجد المسلمون مأمناً، فأرسلوا وفداً إلى النجاشي يحمل الهدايا ويطلب تسليم المهاجرين. لكن النجاشي لم يحكم عليهم من كلام خصومهم، بل استدعاهم وسمع منهم مباشرة، وأعطاهم فرصة لشرح ما يؤمنون به.',
        'تقدم جعفر بن أبي طالب رضي الله عنه فتحدث عن حال العرب قبل الإسلام، وما كان في المجتمع من عبادة للأصنام وقطيعة للرحم وظلم للضعيف، ثم بيّن أن الله بعث فيهم رسولاً يعرفون صدقه وأمانته، فأمرهم بالتوحيد والصدق والعفاف وصلة الرحم وحسن الجوار.',
        'وسأل النجاشي عن شيء مما جاء به النبي ﷺ، فقرأ جعفر آيات من سورة مريم. وتذكر رواية أم سلمة رضي الله عنها أن النجاشي تأثر بما سمع، ورفض تسليم المسلمين إلى وفد قريش. وهذه القصة من أشهر أخبار الهجرة في كتب السيرة، مع ضرورة التمييز بين أصل الحادثة وتفاصيل الروايات وأسانيدها.',
        'تعلمنا الهجرة إلى الحبشة أن حفظ الدين والنفس مقصد معتبر، وأن العدل قد يوجد عند من لا يشاركنا الاعتقاد. كما نرى في موقف جعفر أهمية الحديث بالحكمة والوضوح، دون سب أو تشويه أو تنازل عن أصول الدين.',
      ],
      lessons: [
        'حفظ الدين والنفس من مقاصد الهجرة المشروعة.',
        'العدل قيمة ينبغي إنصاف الناس بها مهما اختلفت أديانهم.',
        'حسن عرض الحق يحتاج إلى علم وهدوء وشجاعة.',
        'لا يجوز الحكم على الناس بسماع طرف واحد من الخصومة.',
      ],
      practicalApplication: 'طبّق الدروس:\n\n• كن عادلاً حتى مع من تختلف معه.\n• تعلّم أن تشرح معتقدك بأدب ووضوح.\n• لا تنقل خبراً قبل التثبت منه.\n• ابحث عن الأمان والبيئة التي تعينك على طاعة الله.',
      question: SeerahQuestion(
        question: 'من الصحابي الذي تحدث أمام النجاشي باسم المهاجرين؟',
        options: ['جعفر بن أبي طالب', 'عثمان بن عفان', 'عبد الرحمن بن عوف', 'سعد بن أبي وقاص'],
        correctAnswer: 0,
        explanation: 'تحدث جعفر بن أبي طالب رضي الله عنه وقرأ على النجاشي آيات من سورة مريم.',
      ),
      relatedStories: ['جعفر بن أبي طالب', 'الثبات على الدين'],
    ),

    // القصة 54 — بنو النضير | المصادر: سورة الحشر 59:2-5؛ كتب المغازي والسيرة.
    SeerahStory(
      id: 54,
      title: 'إجلاء بني النضير',
      subtitle: 'عاقبة نقض العهد',
      category: 'السيرة النبوية',
      location: 'المدينة المنورة',
      readingMinutes: 6,
      emoji: '🏘️',
      storyParagraphs: [
        'كان بنو النضير جماعة من يهود المدينة، وكانت بينهم وبين النبي ﷺ عهود وعلاقات في إطار المجتمع الذي نشأ بعد الهجرة. وتذكر كتب السيرة أن التوتر وقع بعد حادثة محاولة اغتيال النبي ﷺ، حين كان عندهم في شأن دية رجلين، فأُخبر بما دبّره بعضهم وغادر المكان.',
        'لا يصح اختزال الحادثة في عبارة عامة من غير بيان سياقها؛ فقد تناولتها كتب المغازي، ونزلت سورة الحشر بذكر إجلاء الذين كفروا من أهل الكتاب من ديارهم، وذكرت اعتمادهم على حصونهم ثم خروجهم منها. فالقرآن هو الأصل الأوثق في وصف الحدث وعاقبته.',
        'حاصر المسلمون حصون بني النضير بعد ذلك، ثم انتهى الأمر بإجلائهم عن المدينة. وتذكر روايات السيرة أنهم أخذوا ما استطاعوا من أموالهم ومتاعهم، وأن بعضهم اتجه إلى خيبر وبعضهم إلى الشام. وتختلف تفاصيل الأموال والمدة والأعداد في الروايات، فلا ينبغي الجزم بما لا يثبت.',
        'وتشير سورة الحشر إلى أن بعضهم كان يخرب بيوته بيده وبأيدي المؤمنين، ثم تدعو الآيات أصحاب الأبصار إلى الاعتبار. كما ورد في السورة حكم الفيء الذي أفاءه الله على رسوله، وبيان مصارفه، ومن ذلك إعانة فقراء المهاجرين.',
        'والدرس الذي نأخذه من القصة ليس تعميماً على جماعة دينية أو عرقية، بل فهم واقعة تاريخية محددة في سياق عهد وصراع سياسي وأمني كما عرضتها المصادر. فالوفاء بالعهد واجب، والغدر والاعتداء لا يبرران، والعدل يقتضي ألا يحمل الناس ذنب غيرهم.',
      ],
      lessons: [
        'الوفاء بالعهود أساس استقرار المجتمعات.',
        'الاعتماد على القوة والحصون لا يغني عن الحق والعدل.',
        'ينبغي قراءة الوقائع التاريخية في سياقها لا بالتعميم.',
        'القرآن يدعو إلى الاعتبار والتثبت من الأخبار.',
      ],
      practicalApplication: 'تعلّم من القصة:\n\n• التزم بالعهود والاتفاقات التي تعقدها.\n• لا تنسب خطأ فرد إلى جماعة كاملة.\n• اقرأ الأحداث التاريخية من مصادرها وسياقها.\n• اجعل العدل ضابطاً في الحكم على الخصوم.',
      question: SeerahQuestion(
        question: 'أي سورة تناولت إجلاء بني النضير؟',
        options: ['سورة الحشر', 'سورة الكهف', 'سورة مريم', 'سورة النور'],
        correctAnswer: 0,
        explanation: 'تبدأ سورة الحشر بذكر إخراج الذين كفروا من أهل الكتاب من ديارهم، ويربط المفسرون ذلك ببني النضير.',
      ),
      relatedStories: ['غزوة الأحزاب', 'الوفاء بالعهد'],
    ),

    // القصة 55 — بنو قريظة | المصادر: صحيح البخاري 4121؛ سورة الأحزاب 26-27.
    SeerahStory(
      id: 55,
      title: 'بنو قريظة بعد الأحزاب',
