      readingMinutes: 7,
      emoji: '⚖️',
      storyParagraphs: [
        'بعد انتهاء غزوة الأحزاب، توجه النبي ﷺ إلى بني قريظة، وهي واقعة جاءت في سياق حصار المدينة والخطر العسكري الذي تعرض له المسلمون. ويذكر القرآن أن فريقاً من أهل الكتاب الذين ظاهروا الأحزاب أُخرجوا من صياصيهم، وأن الله أورث المؤمنين أرضهم وديارهم وأموالهم.',
        'انتهى الأمر إلى أن نزل بنو قريظة على حكم سعد بن معاذ رضي الله عنه، وكان من سادة الأوس. فأرسل النبي ﷺ إليه، وجاء سعد محمولاً على دابة بسبب إصابته في الخندق، ثم حكم في الواقعة بحكم يتعلق بالمقاتلين والذراري.',
        'ورد أصل هذا التحكيم في صحيح البخاري عن أبي سعيد الخدري رضي الله عنه: أن النبي ﷺ قال للأنصار عند قدوم سعد: «قوموا إلى سيدكم»، ثم أخبره أن القوم نزلوا على حكمه، فحكم في مقاتلتهم وسبي ذراريهم، فقال النبي ﷺ إن حكمه وافق حكم الله أو حكم الملك، كما جاء في الرواية.',
        'من المهم عرض هذه الحادثة بأمانة تاريخية، فلا تُحذف من السيرة ولا تُستعمل كذلك لتبرير ظلم أو عدوان في زماننا. إنها واقعة حكم وتحكيم في سياق حرب وحصار قديم، وتفاصيلها تُدرس من خلال مصادرها، مع تجنب إطلاق أحكام على جماعات معاصرة أو تعميم المسؤولية.',
        'وكان سعد بن معاذ قد أصيب في غزوة الخندق، ثم توفي متأثراً بجراحه. وتذكر السنة فضله ومكانته بين الأنصار، ويظهر في القصة احترام النبي ﷺ له وتقديره لمكانته، مع التأكيد أن الحكم في القضايا العامة ليس مجالاً للأهواء الفردية.',
      ],
      lessons: [
        'يجب دراسة الوقائع التاريخية في سياقها ومصادرها.',
        'التحكيم يحتاج إلى مسؤولية ومعرفة بعواقب القرار.',
        'لا يجوز تحويل حادثة تاريخية إلى مبرر لظلم معاصر.',
        'احترام أصحاب المسؤولية لا يعني تقديس الأشخاص أو تعطيل النقد العلمي.',
      ],
      practicalApplication: 'استفد:\n\n• تحرَّ الدقة قبل نقل أحداث التاريخ.\n• لا تستخدم النصوص خارج سياقها لتبرير الاعتداء.\n• إذا توليت مسؤولية، فاجعل العدل والأمانة أساس قرارك.\n• فرّق بين الحكم على واقعة تاريخية والحكم على الناس اليوم.',
      question: SeerahQuestion(
        question: 'من الذي حكم في بني قريظة بعد نزولهم على التحكيم؟',
        options: ['سعد بن معاذ', 'أبو عبيدة بن الجراح', 'زيد بن ثابت', 'عبد الله بن رواحة'],
        correctAnswer: 0,
        explanation: 'نزل بنو قريظة على حكم سعد بن معاذ رضي الله عنه، كما ورد في صحيح البخاري.',
      ),
      relatedStories: ['غزوة الخندق', 'سعد بن معاذ'],
    ),

