      emoji: '✉️',
      storyParagraphs: [
        'بعد صلح الحديبية، اتسعت الدعوة وبدأ النبي ﷺ يكاتب بعض الملوك والحكام يدعوهم إلى الإسلام. ومن أشهر هذه المكاتبات الرسالة التي بعث بها إلى هرقل عظيم الروم، وهي محفوظة ضمن حديث أبي سفيان الطويل في صحيح البخاري.',
        'كان أبو سفيان في تجارة بالشام قبل إسلامه، فاستدعاه هرقل مع جماعة من قريش ليسأله عن النبي ﷺ. سأله عن نسبه، وصدقه، وأتباعه، وهل يزيدون أم ينقصون، وهل يرتد أحد منهم، وهل عُرف عنه الغدر. وكان أبو سفيان يجيب بما يعرفه، مع أنه كان يومئذ خصماً للنبي ﷺ.',
        'ثم طلب هرقل كتاب رسول الله ﷺ، فقرأ الرسالة التي بدأت بالبسملة، وفيها التعريف بالنبي ﷺ والدعوة إلى الإسلام، وخاتمتها آية من سورة آل عمران تدعو أهل الكتاب إلى كلمة سواء. وتُظهر الرواية أن الرسالة كانت واضحة في مقصدها، موجزة في عبارتها، وموجهة إلى الحاكم باسمه ولقبه.',
        'تأمل هرقل فيما سمعه من أبي سفيان وفيما قرأه من الرسالة، وظهرت منه أسئلة تدل على فهمه لدلائل النبوة، لكنه لم يدخل في الإسلام. ولا يصح أن ننسب إليه إسلاماً ثابتاً؛ فالمصادر الصحيحة لا تثبت ذلك.',
        'وتذكر كتب السيرة رسائل أخرى إلى حكام وأمراء، لكن تفاصيل بعض تلك المكاتبات وألفاظها وأجوبة أصحابها ليست في درجة واحدة من الثبوت. لذلك نركز هنا على الرسالة إلى هرقل لأنها ثابتة في صحيح البخاري، ونحذر من تقديم كل ما اشتهر في كتب السيرة على أنه حديث صحيح.',
        'تعلمنا القصة أن الدعوة تحتاج إلى وضوح وحكمة ومعرفة بالمخاطَب، وأن الإنسان قد يعرف بعض الحق ثم تمنعه المصالح أو المكانة من اتباعه. كما تعلمنا أن صدق الخصم في الشهادة قد يكشف الحقيقة حتى لو لم يكن مؤمناً بها بعد.',
      ],
      lessons: [
        'الدعوة إلى الله تكون بالحكمة والبيان الحسن.',
        'الصدق واجب حتى عند الحديث عن الخصم.',
        'المعرفة بالحق لا تكفي ما لم يتبعها عمل.',
        'ينبغي التفريق بين الروايات الصحيحة والأخبار المشهورة فقط.',
      ],
      practicalApplication: 'طبّق الدروس:\n\n• خاطب الناس بما يفهمون دون تنازل عن الحق.\n• كن صادقاً في وصف من تختلف معه.\n• لا تنشر رسالة أو حديثاً حتى تتحقق من مصدره.\n• لا تجعل المكانة أو المصلحة تمنعك من قبول الحق.',
      question: SeerahQuestion(
        question: 'من الحاكم الذي قرأ رسالة النبي ﷺ في الحديث الصحيح؟',
        options: ['هرقل عظيم الروم', 'كسرى ملك الفرس', 'النجاشي', 'المقوقس'],
        correctAnswer: 0,
        explanation: 'وردت قصة رسالة النبي ﷺ إلى هرقل ضمن حديث أبي سفيان في صحيح البخاري.',
      ),
      relatedStories: ['الهجرة إلى الحبشة', 'الدعوة بالحكمة'],
    ),

    // القصة 57 — عثمان بن عفان | المصادر: صحيح مسلم 2401؛ صحيح البخاري 4987 وفضائل عثمان.
    SeerahStory(
      id: 57,
      title: 'عثمان بن عفان ذو النورين',
      subtitle: 'الحياء والبذل وخدمة القرآن',
      category: 'الصحابة',
      location: 'مكة المكرمة — المدينة المنورة',
      readingMinutes: 7,
      emoji: '🌿',
      storyParagraphs: [
        'عثمان بن عفان رضي الله عنه من السابقين إلى الإسلام، ومن أصحاب النبي ﷺ الذين عُرفوا بالحياء والرفق والإنفاق. وتزوج رقية بنت رسول الله ﷺ، ثم بعد وفاتها تزوج أختها أم كلثوم، ولذلك اشتهر بلقب ذي النورين.',
        'ومن فضائله ما رواه مسلم عن عائشة رضي الله عنها: أن النبي ﷺ كان في حاله المعتادة، فلما استأذن عثمان جلس وسوّى ثيابه، ثم قال: «ألا أستحي من رجل تستحي منه الملائكة؟». وهذا حديث صحيح يبين عظيم حيائه ومكانته.',
        'وكان عثمان من أهل البذل في سبيل الله. ففي صحيح البخاري أن النبي ﷺ قال في بئر رومة: «من يحفر بئر رومة فله الجنة»، فحفرها عثمان، وقال في جيش العسرة: «من جهز جيش العسرة فله الجنة»، فجهزه عثمان. ولا حاجة إلى تكرار أرقام تفصيلية متداولة في بعض القصص ما لم تثبت بسند واضح.',
        'وفي خلافته ظهر عمل عظيم لحفظ وحدة المسلمين في قراءة القرآن. فقد خشي حذيفة بن اليمان اختلاف الناس في القراءة، فطلب من عثمان أن يتدارك الأمر. فأرسل عثمان إلى حفصة رضي الله عنها يطلب الصحف التي جُمع فيها القرآن في عهد أبي بكر، ثم كلّف لجنة من الصحابة بنسخ مصاحف موحدة، وأرسل نسخاً إلى الأمصار.',
        'لم يكن عمل عثمان إنشاء قرآن جديداً، بل توحيد المصاحف على ما ثبت من القرآن، منعاً للنزاع والاختلاف بين المسلمين. وهذا التفصيل مهم حتى نفهم دوره بدقة ونحفظ فضل الصحابة الذين شاركوا في الجمع والنسخ.',
        'توفي عثمان رضي الله عنه مقتولاً في الفتنة، بعد أن حوصر في داره. وتفاصيل الأيام الأخيرة تروى بأخبار متعددة متفاوتة الثبوت، لذلك نكتفي هنا بأصل مقتله ظلماً، ولا نجزم بكل مشهد شاع في بعض الروايات.',
      ],
      lessons: [
        'الحياء خلق عظيم لا يتعارض مع الشجاعة وتحمل المسؤولية.',
        'المال نعمة، ومن أفضل وجوه شكرها إنفاقه في الخير.',
        'خدمة القرآن تكون بالتعلم والتعليم وحفظ وحدة الأمة.',
        'التثبت واجب عند نقل أخبار الفتن والأحداث المؤلمة.',
      ],
      practicalApplication: 'اقتدِ بعثمان رضي الله عنه:\n\n• أنفق من مالك في مشروع نافع.\n• تحلَّ بالحياء مع الثبات على الحق.\n• شارك في خدمة القرآن تعلماً وتعليماً.\n• لا تنشر أخبار الفتن دون تحقق من صحتها.',
      question: SeerahQuestion(
        question: 'ما العمل الذي قام به عثمان رضي الله عنه لمنع اختلاف المسلمين في المصاحف؟',
        options: ['نسخ المصاحف وإرسالها إلى الأمصار', 'تغيير آيات القرآن', 'إلغاء حفظ القرآن', 'كتابة تفسير واحد ملزم'],
        correctAnswer: 0,
        explanation: 'نسخ عثمان رضي الله عنه المصاحف اعتماداً على الصحف المحفوظة، وأرسل نسخاً إلى الأمصار منعاً للاختلاف.',
      ),
      relatedStories: ['جمع القرآن', 'الحياء في الإسلام'],
    ),

    // القصة 58 — الحسن والحسين | المصادر: صحيح البخاري 2704؛ جامع الترمذي 3768؛ صحيح مسلم في فضائل الحسن والحسين.
    SeerahStory(
      id: 58,
      title: 'الحسن والحسين',
      subtitle: 'محبة النبي ﷺ وسيدَا شباب أهل الجنة',
      category: 'الصحابة',
