      readingMinutes: 7,
      emoji: '💚',
      storyParagraphs: [
        'الحسن والحسين رضي الله عنهما ابنا علي بن أبي طالب وفاطمة الزهراء رضي الله عنهما، وحفيدا رسول الله ﷺ. وكان النبي ﷺ يحبهما ويظهر رحمته بهما، فكان في ذلك تعليم للأمة أن محبة الأطفال والرفق بهم من مكارم الأخلاق.',
        'ورد عن النبي ﷺ في جامع الترمذي: «الحسن والحسين سيدا شباب أهل الجنة»، وحسنه وصححه أهل العلم. كما ثبت في الصحيحين أن النبي ﷺ كان يحمل أمامة بنت زينب في الصلاة، وثبتت أحاديث في ملاطفته للحسن والحسين وتقبيلهما.',
        'ومن أعظم المواقف التي تتصل بالحسن رضي الله عنه قول النبي ﷺ: «إن ابني هذا سيد، ولعل الله أن يصلح به بين فئتين عظيمتين من المسلمين». وقد تحقق معنى الحديث حين تنازل الحسن عن الخلافة لمعاوية سنة 41 هـ، رغبة في جمع كلمة المسلمين ووقف القتال.',
        'أما الحسين رضي الله عنه فقد قُتل في كربلاء سنة 61 هـ، في حادثة مؤلمة من تاريخ المسلمين. ومحبة الحسين وتوقيره لا تعني الغلو فيه، كما أن دراسة مقتله لا ينبغي أن تتحول إلى سب أو تحريض؛ بل نتعلم من الحدث حرمة الدماء وخطورة الفتن.',
        'وتجمع سيرة الحسن والحسين بين محبة آل بيت النبي ﷺ، والرحمة، والشجاعة، وطلب الإصلاح. وقد بقيت مكانتهما محفوظة في قلوب المسلمين، مع وجوب العدل والإنصاف عند الحديث عن الخلافات التاريخية.',
      ],
      lessons: [
        'محبة آل بيت النبي ﷺ وتوقيرهم من محبة رسول الله ﷺ.',
        'الرحمة بالأطفال خلق نبوي أصيل.',
        'حقن الدماء والإصلاح بين المسلمين من أعظم الأعمال.',
        'ينبغي تناول الفتن التاريخية بالعلم والعدل لا بالتعصب.',
      ],
      practicalApplication: 'تعلّم من سيرتهما:\n\n• عامل الأطفال بالرحمة والرفق.\n• احفظ لآل بيت النبي ﷺ مكانتهم دون غلو.\n• اسعَ للإصلاح بين المتخاصمين.\n• ابتعد عن خطاب الكراهية عند الحديث عن التاريخ.',
      question: SeerahQuestion(
        question: 'ما الذي تنبأ به النبي ﷺ للحسن بن علي رضي الله عنهما؟',
        options: ['أن يصلح الله به بين فئتين عظيمتين', 'أن يكون أول مؤذن', 'أن يفتح مكة', 'أن يهاجر إلى الحبشة'],
        correctAnswer: 0,
        explanation: 'قال النبي ﷺ إن ابنه الحسن سيد، ولعل الله أن يصلح به بين فئتين عظيمتين من المسلمين.',
      ),
      relatedStories: ['فضل آل بيت النبي ﷺ', 'الإصلاح بين الناس'],
    ),

    // القصة 59 — خديجة بنت خويلد | المصادر: صحيح البخاري 3 و3820؛ صحيح مسلم في فضائل خديجة.
    SeerahStory(
      id: 59,
      title: 'خديجة بنت خويلد',
      subtitle: 'سكن النبي ﷺ وأول من آمن به',
      category: 'الصحابة',
      location: 'مكة المكرمة',
      readingMinutes: 7,
      emoji: '🌸',
      storyParagraphs: [
        'خديجة بنت خويلد رضي الله عنها زوج النبي ﷺ، وكانت ذات شرف وعقل وتجارة. عرفها الناس بحسن السيرة، ثم تزوجها النبي ﷺ قبل البعثة، وكانت أول زوجاته، وأم أولاده منها إلا إبراهيم، وظلت معه حتى وفاتها.',
        'لما نزل الوحي على النبي ﷺ في غار حراء، عاد إلى خديجة يرجف فؤاده، فطمأنته وذكّرته بخصاله الطيبة: صلة الرحم، وحمل الكل، وإكرام الضيف، وإعانة أصحاب الحق. وهذا الموقف ثابت في حديث بدء الوحي في صحيح البخاري، ويظهر عقلها وثباتها وحسن مواساتها.',
        'كانت خديجة أول من آمن برسول الله ﷺ وصدقه، ووقفت معه في بداية الدعوة حين كان الطريق صعباً. ساندته وواسته، وتحملت معه أذى قريش والحصار، فكان وجودها في حياته سكينة وعوناً كبيراً.',
        'وبعد وفاتها ظل النبي ﷺ يذكر فضلها ويحسن إلى صديقاتها. وفي صحيح البخاري أن جبريل أتى النبي ﷺ يبشر خديجة ببيت في الجنة من قصب، لا صخب فيه ولا نصب، وأن يبلغها السلام من ربها ومنه. وهذه بشارة عظيمة تدل على مكانتها.',
        'ولا ينبغي الجزم بتفاصيل مختلف فيها مثل عمرها الدقيق عند الزواج أو ترتيب بعض الوقائع إلا مع بيان اختلاف الروايات. أما الثابت فهو فضلها، وسبقها إلى الإيمان، ومساندتها للنبي ﷺ، والبشارة النبوية لها بالجنة.',
        'تعلمنا خديجة رضي الله عنها أن الإيمان يظهر في المواقف، وأن الوفاء لا ينتهي بوفاة الأحبة، وأن الكلمة الطيبة والمساندة الصادقة قد تكونان أعظم عون للإنسان في أشد لحظات حياته.',
      ],
      lessons: [
        'المساندة الصادقة تظهر قيمتها وقت الشدائد.',
        'السبق إلى الخير منزلة عظيمة.',
        'الوفاء للأحبة يكون بذكر فضلهم والإحسان إلى من يحبون.',
        'العقل والحكمة والثبات صفات عظيمة في المرأة والرجل.',
      ],
      practicalApplication: 'اقتدِ بخديجة رضي الله عنها:\n\n• كن سنداً لمن يمر بوقت صعب.\n• اذكر محاسن الناس ولا تنسَ فضلهم.\n• بادر إلى تصديق الحق والعمل به.\n• استخدم مالك ومكانتك في نصرة الخير.',
      question: SeerahQuestion(
        question: 'بماذا بشّر جبريل خديجة رضي الله عنها؟',
        options: ['ببيت في الجنة لا صخب فيه ولا نصب', 'بكنز في الدنيا', 'بالعودة إلى مكة', 'بولاية قومها'],
        correctAnswer: 0,
        explanation: 'بشرها جبريل عليه السلام ببيت في الجنة من قصب لا صخب فيه ولا نصب، كما في صحيح البخاري.',
      ),
      relatedStories: ['نزول الوحي', 'أمهات المؤمنين'],
    ),

    // القصة 60 — أسماء بنت أبي بكر | المصادر: صحيح البخاري 3907؛ أخبار الهجرة في كتب السيرة.
    SeerahStory(
