      storyParagraphs: [
        'أسماء بنت أبي بكر رضي الله عنها صحابية جليلة، وهي ابنة أبي بكر الصديق وأخت عائشة رضي الله عنهما. عاشت في بيت عرف بالإيمان والثبات، وكان لها دور في خدمة النبي ﷺ وأبيها أبي بكر حين استعدا للهجرة من مكة إلى المدينة.',
        'تروي أسماء في صحيح البخاري أنها جهزت سفرة الطعام للنبي ﷺ وأبي بكر، ولم تجد ما تربط به وعاء الزاد إلا نطاقها، فقال لها أبوها أن تشقه نصفين. ففعلت، فصار لها نطاقان، ومن هنا اشتهرت بلقب «ذات النطاقين».',
        'تذكر روايات السيرة أنها كانت تحمل الطعام إلى النبي ﷺ وأبي بكر في الغار، وأنها واجهت أذى أبي جهل حين جاء يسأل عن أبيها. وتفاصيل الحوار والضرب الواردة في بعض الروايات تُذكر مع نسبتها إلى كتب السيرة، أما أصل تجهيزها الزاد وشق نطاقها فثابت في صحيح البخاري.',
        'تظهر القصة أن خدمة الدعوة ليست محصورة في القتال أو الخطابة؛ فقد تكون في إعداد الطعام، أو حفظ السر، أو تحمل المشقة، أو أداء مهمة صغيرة في وقت حاسم. وقد شاركت أسماء بما تستطيع، فكان عملها سبباً في تيسير رحلة الهجرة.',
        'وعاشت أسماء بعد ذلك عمراً طويلاً، وعُرفت بالصبر والثبات، وكانت أماً لعبد الله بن الزبير رضي الله عنهما. لكننا في هذه القصة نركز على الموقف الثابت في الهجرة، دون إضافة تفاصيل لا تقوم عليها حجة واضحة.',
        'تعلمنا أسماء رضي الله عنها أن الشجاعة ليست دائماً في مواجهة العدو بالسلاح؛ فقد تكون في تحمل المسؤولية، وبذل ما نملك، وخدمة الحق بإخلاص حتى لو بدا العمل بسيطاً.',
      ],
      lessons: [
        'قد يكون العمل الصغير عظيماً إذا جاء في وقته وبإخلاص.',
        'المرأة المسلمة شاركت في نصرة الدعوة بأعمال متنوعة.',
        'الشجاعة تشمل تحمل المسؤولية والصبر على المشقة.',
        'التعاون الأسري من أسباب نجاح الأعمال الكبيرة.',
      ],
      practicalApplication: 'اقتدِ بأسماء رضي الله عنها:\n\n• ساعد أهلك ومن حولك في أوقات الحاجة.\n• لا تحتقر عملاً نافعاً ولو كان بسيطاً.\n• كن أميناً على الأسرار والمسؤوليات.\n• ابذل ما تستطيع لنصرة الخير دون انتظار شهرة أو مقابل.',
      question: SeerahQuestion(
        question: 'لماذا لُقبت أسماء بنت أبي بكر بذات النطاقين؟',
        options: ['لأنها شقت نطاقها نصفين لتربط الزاد', 'لأنها لبست ثوبين في الحج', 'لأنها هاجرت مرتين', 'لأنها كانت تملك دارين'],
        correctAnswer: 0,
        explanation: 'شقت نطاقها نصفين لتربط وعاء الزاد في رحلة الهجرة، فلقبت بذات النطاقين، كما في صحيح البخاري.',
      ),
      relatedStories: ['الهجرة إلى المدينة', 'أبو بكر الصديق'],
